window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["NEH"]={"book":"NEH","editions":{"hbo-source":[[1,1,"דִּבְרֵ֥י נְחֶמְיָ֖ה בֶּן־חֲכַלְיָ֑ה וַ⁠יְהִ֤י בְ⁠חֹֽדֶשׁ־כסלו שְׁנַ֣ת עֶשְׂרִ֔ים וַ⁠אֲנִ֥י הָיִ֖יתִי בְּ⁠שׁוּשַׁ֥ן הַ⁠בִּירָֽה׃","di̇bĕré֥y nĕẖemĕyá֖h bėn-ẖàkalĕyá֑h wa⁠yĕhi֤y bĕ⁠ẖòֽdeş̌-kslw şĕ̌na֣ţ ʻeşĕ̂ri֔ym wa⁠ʼàni֥y háyi֖yţiy bĕ̇⁠ş̌ẇşǎ֥n ha⁠bi̇yráֽh׃"],[1,2,"וַ⁠יָּבֹ֨א חֲנָ֜נִי אֶחָ֧ד מֵ⁠אַחַ֛⁠י ה֥וּא וַ⁠אֲנָשִׁ֖ים מִֽ⁠יהוּדָ֑ה וָ⁠אֶשְׁאָלֵ֞⁠ם עַל־הַ⁠יְּהוּדִ֧ים הַ⁠פְּלֵיטָ֛ה אֲשֶֽׁר־נִשְׁאֲר֥וּ מִן־הַ⁠שֶּׁ֖בִי וְ⁠עַל־יְרוּשָׁלִָֽם׃","wa⁠yá̇bò֨ʼ ẖàná֜niy ʼeẖá֧d mé⁠ʼaẖa֛⁠y h֥ẇʼ wa⁠ʼànáşǐ֖ym miֽ⁠yhẇdá֑h wá⁠ʼeşĕ̌ʼálé֞⁠m ʻal-ha⁠yĕ̇hẇdi֧ym ha⁠pĕ̇léytá֛h ʼàşěֽr-nişĕ̌ʼàr֥ẇ min-ha⁠şė֖̌biy wĕ⁠ʻal-yĕrẇşá̌liáֽm׃"],[1,3,"וַ⁠יֹּאמְרוּ֮ לִ⁠י֒ הַֽ⁠נִּשְׁאָרִ֞ים אֲשֶֽׁר־נִשְׁאֲר֤וּ מִן־הַ⁠שְּׁבִי֙ שָׁ֣ם בַּ⁠מְּדִינָ֔ה בְּ⁠רָעָ֥ה גְדֹלָ֖ה וּ⁠בְ⁠חֶרְפָּ֑ה וְ⁠חוֹמַ֤ת יְרוּשָׁלִַ֨ם֙ מְפֹרָ֔צֶת וּ⁠שְׁעָרֶ֖י⁠הָ נִצְּת֥וּ בָ⁠אֵֽשׁ׃","wa⁠yò̇ʼmĕrẇ֮ li⁠y֒ haֽ⁠ni̇şĕ̌ʼári֞ym ʼàşěֽr-nişĕ̌ʼàr֤ẇ min-ha⁠şĕ̇̌biy֙ şá֣̌m bȧ⁠mĕ̇diyná֔h bĕ̇⁠ráʻá֥h gĕdòlá֖h ẇ⁠bĕ⁠ẖerĕpá֑̇h wĕ⁠ẖwòma֤ţ yĕrẇşá̌lia֨m֙ mĕpòrá֔ẕeţ ẇ⁠şĕ̌ʻáre֖y⁠há niẕĕ̇ţ֥ẇ bá⁠ʼéֽş̌׃"],[1,4,"וַ⁠יְהִ֞י כְּ⁠שָׁמְעִ֣⁠י ׀ אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה יָשַׁ֨בְתִּי֙ וָֽ⁠אֶבְכֶּ֔ה וָ⁠אֶתְאַבְּלָ֖⁠ה יָמִ֑ים וָֽ⁠אֱהִ֥י צָם֙ וּ⁠מִתְפַּלֵּ֔ל לִ⁠פְנֵ֖י אֱלֹהֵ֥י הַ⁠שָּׁמָֽיִם׃","wa⁠yĕhi֞y kĕ̇⁠şá̌mĕʻi֣⁠y ׀ ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh yáşǎ֨bĕţi̇y֙ wáֽ⁠ʼebĕkė֔h wá⁠ʼeţĕʼabĕ̇lá֖⁠h yámi֑ym wáֽ⁠ʼèhi֥y ẕám֙ ẇ⁠miţĕpȧlé̇֔l li⁠pĕné֖y ʼèlòhé֥y ha⁠şá̇̌máֽyim׃"],[1,5,"וָ⁠אֹמַ֗ר אָֽנָּ֤א יְהוָה֙ אֱלֹהֵ֣י הַ⁠שָּׁמַ֔יִם הָ⁠אֵ֥ל הַ⁠גָּד֖וֹל וְ⁠הַ⁠נּוֹרָ֑א שֹׁמֵ֤ר הַ⁠בְּרִית֙ וָ⁠חֶ֔סֶד לְ⁠אֹהֲבָ֖י⁠ו וּ⁠לְ⁠שֹׁמְרֵ֥י מִצְוֺתָֽי⁠ו׃","wá⁠ʼòma֗r ʼáֽná֤̇ʼ yĕhwáh֙ ʼèlòhé֣y ha⁠şá̇̌ma֔yim há⁠ʼé֥l ha⁠gá̇d֖wòl wĕ⁠ha⁠ṅwòrá֑ʼ şò̌mé֤r ha⁠bĕ̇riyţ֙ wá⁠ẖe֔sed lĕ⁠ʼòhàbá֖y⁠w ẇ⁠lĕ⁠şò̌mĕré֥y miẕĕwֺţáֽy⁠w׃"],[1,6,"תְּהִ֣י נָ֣א אָזְנְ⁠ךָֽ־קַשֶּׁ֣בֶת וְֽ⁠עֵינֶ֪י⁠ךָ פְתֻוּח֟וֹת לִ⁠שְׁמֹ֣עַ אֶל־תְּפִלַּ֣ת עַבְדְּ⁠ךָ֡ אֲשֶׁ֣ר אָנֹכִי֩ מִתְפַּלֵּ֨ל לְ⁠פָנֶ֤י⁠ךָ הַ⁠יּוֹם֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה עַל־בְּנֵ֥י יִשְׂרָאֵ֖ל עֲבָדֶ֑י⁠ךָ וּ⁠מִתְוַדֶּ֗ה עַל־חַטֹּ֤אות בְּנֵֽי־יִשְׂרָאֵל֙ אֲשֶׁ֣ר חָטָ֣אנוּ לָ֔⁠ךְ וַ⁠אֲנִ֥י וּ⁠בֵית־אָבִ֖⁠י חָטָֽאנוּ׃","ţĕ̇hi֣y ná֣ʼ ʼázĕnĕ⁠káֽ-qaşė֣̌beţ wĕֽ⁠ʻéyne֪y⁠ká pĕţuẇẖ֟wòţ li⁠şĕ̌mò֣ʻa ʼel-ţĕ̇pilȧ֣ţ ʻabĕdĕ̇⁠ká֡ ʼàşě֣r ʼánòkiy֩ miţĕpȧlé̇֨l lĕ⁠páne֤y⁠ká ha⁠ẏwòm֙ ywòmá֣m wá⁠la֔yĕláh ʻal-bĕ̇né֥y yişĕ̂ráʼé֖l ʻàbáde֑y⁠ká ẇ⁠miţĕwadė֗h ʻal-ẖatò֤̇ʼwţ bĕ̇néֽy-yişĕ̂ráʼél֙ ʼàşě֣r ẖátá֣ʼnẇ lá֔⁠kĕ wa⁠ʼàni֥y ẇ⁠béyţ-ʼábi֖⁠y ẖátáֽʼnẇ׃"],[1,7,"חֲבֹ֖ל חָבַ֣לְנוּ לָ֑⁠ךְ וְ⁠לֹא־שָׁמַ֣רְנוּ אֶת־הַ⁠מִּצְוֺ֗ת וְ⁠אֶת־הַֽ⁠חֻקִּים֙ וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֥ר צִוִּ֖יתָ אֶת־מֹשֶׁ֥ה עַבְדֶּֽ⁠ךָ׃","ẖàbò֖l ẖába֣lĕnẇ lá֑⁠kĕ wĕ⁠lòʼ-şá̌ma֣rĕnẇ ʼeţ-ha⁠mi̇ẕĕwֺ֗ţ wĕ⁠ʼeţ-haֽ⁠ẖuqi̇ym֙ wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֥r ẕiwi֖̇yţá ʼeţ-mòşě֥h ʻabĕdėֽ⁠ká׃"],[1,8,"זְכָר־נָא֙ אֶת־הַ⁠דָּבָ֔ר אֲשֶׁ֥ר צִוִּ֛יתָ אֶת־מֹשֶׁ֥ה עַבְדְּ⁠ךָ֖ לֵ⁠אמֹ֑ר אַתֶּ֣ם תִּמְעָ֔לוּ אֲנִ֕י אָפִ֥יץ אֶתְ⁠כֶ֖ם בָּ⁠עַמִּֽים׃","zĕkár-náʼ֙ ʼeţ-ha⁠dá̇bá֔r ʼàşě֥r ẕiwi֛̇yţá ʼeţ-mòşě֥h ʻabĕdĕ̇⁠ká֖ lé⁠ʼmò֑r ʼaţė֣m ţi̇mĕʻá֔lẇ ʼàni֕y ʼápi֥yẕ ʼeţĕ⁠ke֖m bá̇⁠ʻamiֽ̇ym׃"],[1,9,"וְ⁠שַׁבְתֶּ֣ם אֵלַ֔⁠י וּ⁠שְׁמַרְתֶּם֙ מִצְוֺתַ֔⁠י וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם אִם־יִהְיֶ֨ה נִֽדַּחֲ⁠כֶ֜ם בִּ⁠קְצֵ֤ה הַ⁠שָּׁמַ֨יִם֙ מִ⁠שָּׁ֣ם אֲקַבְּצֵ֔⁠ם ו⁠הבואתי⁠ם אֶל־הַ⁠מָּק֔וֹם אֲשֶׁ֣ר בָּחַ֔רְתִּי לְ⁠שַׁכֵּ֥ן אֶת־שְׁמִ֖⁠י שָֽׁם׃","wĕ⁠şǎbĕţė֣m ʼéla֔⁠y ẇ⁠şĕ̌marĕţėm֙ miẕĕwֺţa֔⁠y wa⁠ʻàşîyţe֖m ʼòţá֑⁠m ʼim-yihĕye֨h niֽdȧẖà⁠ke֜m bi̇⁠qĕẕé֤h ha⁠şá̇̌ma֨yim֙ mi⁠şá֣̇̌m ʼàqabĕ̇ẕé֔⁠m w⁠hbwʼţy⁠m ʼel-ha⁠má̇q֔wòm ʼàşě֣r bá̇ẖa֔rĕţi̇y lĕ⁠şǎké֥̇n ʼeţ-şĕ̌mi֖⁠y şáֽ̌m׃"],[1,10,"וְ⁠הֵ֥ם עֲבָדֶ֖י⁠ךָ וְ⁠עַמֶּ֑⁠ךָ אֲשֶׁ֤ר פָּדִ֨יתָ֙ בְּ⁠כֹחֲ⁠ךָ֣ הַ⁠גָּד֔וֹל וּ⁠בְ⁠יָדְ⁠ךָ֖ הַ⁠חֲזָקָֽה׃","wĕ⁠hé֥m ʻàbáde֖y⁠ká wĕ⁠ʻamė֑⁠ká ʼàşě֤r pá̇di֨yţá֙ bĕ̇⁠kòẖà⁠ká֣ ha⁠gá̇d֔wòl ẇ⁠bĕ⁠yádĕ⁠ká֖ ha⁠ẖàzáqáֽh׃"],[1,11,"אָנָּ֣א אֲדֹנָ֗⁠י תְּהִ֣י נָ֣א אָזְנְ⁠ךָֽ־קַ֠שֶּׁבֶת אֶל־תְּפִלַּ֨ת עַבְדְּ⁠ךָ֜ וְ⁠אֶל־תְּפִלַּ֣ת עֲבָדֶ֗י⁠ךָ הַֽ⁠חֲפֵצִים֙ לְ⁠יִרְאָ֣ה אֶת־שְׁמֶ֔⁠ךָ וְ⁠הַצְלִֽיחָ⁠ה־נָּ֤א לְ⁠עַבְדְּ⁠ךָ֙ הַ⁠יּ֔וֹם וּ⁠תְנֵ֣⁠הוּ לְ⁠רַחֲמִ֔ים לִ⁠פְנֵ֖י הָ⁠אִ֣ישׁ הַ⁠זֶּ֑ה וַ⁠אֲנִ֛י הָיִ֥יתִי מַשְׁקֶ֖ה לַ⁠מֶּֽלֶךְ׃פ","ʼáná֣̇ʼ ʼàdòná֗⁠y ţĕ̇hi֣y ná֣ʼ ʼázĕnĕ⁠káֽ-qa֠şė̌beţ ʼel-ţĕ̇pilȧ֨ţ ʻabĕdĕ̇⁠ká֜ wĕ⁠ʼel-ţĕ̇pilȧ֣ţ ʻàbáde֗y⁠ká haֽ⁠ẖàpéẕiym֙ lĕ⁠yirĕʼá֣h ʼeţ-şĕ̌me֔⁠ká wĕ⁠haẕĕliֽyẖá⁠h-ná֤̇ʼ lĕ⁠ʻabĕdĕ̇⁠ká֙ ha⁠ẏ֔wòm ẇ⁠ţĕné֣⁠hẇ lĕ⁠raẖàmi֔ym li⁠pĕné֖y há⁠ʼi֣yş̌ ha⁠zė֑h wa⁠ʼàni֛y háyi֥yţiy maşĕ̌qe֖h la⁠mėֽlekĕ׃p"],[2,1,"וַ⁠יְהִ֣י ׀ בְּ⁠חֹ֣דֶשׁ נִיסָ֗ן שְׁנַ֥ת עֶשְׂרִ֛ים לְ⁠אַרְתַּחְשַׁ֥סְתְּא הַ⁠מֶּ֖לֶךְ יַ֣יִן לְ⁠פָנָ֑י⁠ו וָ⁠אֶשָּׂ֤א אֶת־הַ⁠יַּ֨יִן֙ וָ⁠אֶתְּנָ֣⁠ה לַ⁠מֶּ֔לֶךְ וְ⁠לֹא־הָיִ֥יתִי רַ֖ע לְ⁠פָנָֽי⁠ו׃","wa⁠yĕhi֣y ׀ bĕ̇⁠ẖò֣deş̌ niysá֗n şĕ̌na֥ţ ʻeşĕ̂ri֛ym lĕ⁠ʼarĕţȧẖĕşǎ֥sĕţĕ̇ʼ ha⁠mė֖lekĕ ya֣yin lĕ⁠páná֑y⁠w wá⁠ʼeşá֤̇̂ʼ ʼeţ-ha⁠yȧ֨yin֙ wá⁠ʼeţĕ̇ná֣⁠h la⁠mė֔lekĕ wĕ⁠lòʼ-háyi֥yţiy ra֖ʻ lĕ⁠pánáֽy⁠w׃"],[2,2,"וַ⁠יֹּאמֶר֩ לִ֨⁠י הַ⁠מֶּ֜לֶךְ מַדּ֣וּעַ ׀ פָּנֶ֣י⁠ךָ רָעִ֗ים וְ⁠אַתָּה֙ אֵֽינְ⁠ךָ֣ חוֹלֶ֔ה אֵ֣ין זֶ֔ה כִּי־אִ֖ם רֹ֣עַֽ לֵ֑ב וָ⁠אִירָ֖א הַרְבֵּ֥ה מְאֹֽד׃","wa⁠yò̇ʼmer֩ li֨⁠y ha⁠mė֜lekĕ maḋ֣ẇʻa ׀ pá̇ne֣y⁠ká ráʻi֗ym wĕ⁠ʼaţá̇h֙ ʼéֽynĕ⁠ká֣ ẖwòle֔h ʼé֣yn ze֔h ki̇y-ʼi֖m rò֣ʻaֽ lé֑b wá⁠ʼiyrá֖ʼ harĕbé֥̇h mĕʼòֽd׃"],[2,3,"וָ⁠אֹמַ֣ר לַ⁠מֶּ֔לֶךְ הַ⁠מֶּ֖לֶךְ לְ⁠עוֹלָ֣ם יִחְיֶ֑ה מַדּ֜וּעַ לֹא־יֵרְע֣וּ פָנַ֗⁠י אֲשֶׁ֨ר הָ⁠עִ֜יר בֵּית־קִבְר֤וֹת אֲבֹתַ⁠י֙ חֲרֵבָ֔ה וּ⁠שְׁעָרֶ֖י⁠הָ אֻכְּל֥וּ בָ⁠אֵֽשׁ׃ס","wá⁠ʼòma֣r la⁠mė֔lekĕ ha⁠mė֖lekĕ lĕ⁠ʻwòlá֣m yiẖĕye֑h maḋ֜ẇʻa lòʼ-yérĕʻ֣ẇ pána֗⁠y ʼàşě֨r há⁠ʻi֜yr bé̇yţ-qibĕr֤wòţ ʼàbòţa⁠y֙ ẖàrébá֔h ẇ⁠şĕ̌ʻáre֖y⁠há ʼukĕ̇l֥ẇ bá⁠ʼéֽş̌׃s"],[2,4,"וַ⁠יֹּ֤אמֶר לִ⁠י֙ הַ⁠מֶּ֔לֶךְ עַל־מַה־זֶּ֖ה אַתָּ֣ה מְבַקֵּ֑שׁ וָֽ⁠אֶתְפַּלֵּ֔ל אֶל־אֱלֹהֵ֖י הַ⁠שָּׁמָֽיִם׃","wa⁠yò֤̇ʼmer li⁠y֙ ha⁠mė֔lekĕ ʻal-mah-zė֖h ʼaţá֣̇h mĕbaqé֑̇ş̌ wáֽ⁠ʼeţĕpȧlé̇֔l ʼel-ʼèlòhé֖y ha⁠şá̇̌máֽyim׃"],[2,5,"וָ⁠אֹמַ֣ר לַ⁠מֶּ֔לֶךְ אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב וְ⁠אִם־יִיטַ֥ב עַבְדְּ⁠ךָ֖ לְ⁠פָנֶ֑י⁠ךָ אֲשֶׁ֧ר תִּשְׁלָחֵ֣⁠נִי אֶל־יְהוּדָ֗ה אֶל־עִ֛יר קִבְר֥וֹת אֲבֹתַ֖⁠י וְ⁠אֶבְנֶֽ⁠נָּה׃","wá⁠ʼòma֣r la⁠mė֔lekĕ ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb wĕ⁠ʼim-yiyta֥b ʻabĕdĕ̇⁠ká֖ lĕ⁠páne֑y⁠ká ʼàşě֧r ţi̇şĕ̌láẖé֣⁠niy ʼel-yĕhẇdá֗h ʼel-ʻi֛yr qibĕr֥wòţ ʼàbòţa֖⁠y wĕ⁠ʼebĕneֽ⁠ná̇h׃"],[2,6,"וַ⁠יֹּאמֶר֩ לִ֨⁠י הַ⁠מֶּ֜לֶךְ וְ⁠הַ⁠שֵּׁגַ֣ל ׀ יוֹשֶׁ֣בֶת אֶצְל֗⁠וֹ עַד־מָתַ֛י יִהְיֶ֥ה מַֽהֲלָכֲ⁠ךָ֖ וּ⁠מָתַ֣י תָּשׁ֑וּב וַ⁠יִּיטַ֤ב לִ⁠פְנֵֽי־הַ⁠מֶּ֨לֶךְ֙ וַ⁠יִּשְׁלָחֵ֔⁠נִי וָֽ⁠אֶתְּנָ֥⁠ה ל֖⁠וֹ זְמָֽן׃","wa⁠yò̇ʼmer֩ li֨⁠y ha⁠mė֜lekĕ wĕ⁠ha⁠şé̇̌ga֣l ׀ ywòşě֣beţ ʼeẕĕl֗⁠wò ʻad-máţa֛y yihĕye֥h maֽhàlákà⁠ká֖ ẇ⁠máţa֣y ţá̇ş֑̌ẇb wa⁠yi̇yta֤b li⁠pĕnéֽy-ha⁠mė֨lekĕ֙ wa⁠yi̇şĕ̌láẖé֔⁠niy wáֽ⁠ʼeţĕ̇ná֥⁠h l֖⁠wò zĕmáֽn׃"],[2,7,"וָ⁠אוֹמַר֮ לַ⁠מֶּלֶךְ֒ אִם־עַל־הַ⁠מֶּ֣לֶךְ ט֔וֹב אִגְּרוֹת֙ יִתְּנוּ־לִ֔⁠י עַֽל־פַּחֲו֖וֹת עֵ֣בֶר הַ⁠נָּהָ֑ר אֲשֶׁר֙ יַעֲבִיר֔וּ⁠נִי עַ֥ד אֲשֶׁר־אָב֖וֹא אֶל־יְהוּדָֽה׃","wá⁠ʼwòmar֮ la⁠mėlekĕ֒ ʼim-ʻal-ha⁠mė֣lekĕ t֔wòb ʼigĕ̇rwòţ֙ yiţĕ̇nẇ-li֔⁠y ʻaֽl-pȧẖàw֖wòţ ʻé֣ber ha⁠ná̇há֑r ʼàşěr֙ yaʻàbiyr֔ẇ⁠niy ʻa֥d ʼàşěr-ʼáb֖wòʼ ʼel-yĕhẇdáֽh׃"],[2,8,"וְ⁠אִגֶּ֡רֶת אֶל־אָסָף֩ שֹׁמֵ֨ר הַ⁠פַּרְדֵּ֜ס אֲשֶׁ֣ר לַ⁠מֶּ֗לֶךְ אֲשֶׁ֣ר יִתֶּן־לִ֣⁠י עֵצִ֡ים לְ֠⁠קָרוֹת אֶת־שַׁעֲרֵ֨י הַ⁠בִּירָ֤ה אֲשֶׁר־לַ⁠בַּ֨יִת֙ וּ⁠לְ⁠חוֹמַ֣ת הָ⁠עִ֔יר וְ⁠לַ⁠בַּ֖יִת אֲשֶׁר־אָב֣וֹא אֵלָ֑י⁠ו וַ⁠יִּתֶּן־לִ֣⁠י הַ⁠מֶּ֔לֶךְ כְּ⁠יַד־אֱלֹהַ֖⁠י הַ⁠טּוֹבָ֥ה עָלָֽ⁠י׃","wĕ⁠ʼigė֡reţ ʼel-ʼásáp֩ şò̌mé֨r ha⁠pȧrĕdé̇֜s ʼàşě֣r la⁠mė֗lekĕ ʼàşě֣r yiţėn-li֣⁠y ʻéẕi֡ym lĕ֠⁠qárwòţ ʼeţ-şǎʻàré֨y ha⁠bi̇yrá֤h ʼàşěr-la⁠bȧ֨yiţ֙ ẇ⁠lĕ⁠ẖwòma֣ţ há⁠ʻi֔yr wĕ⁠la⁠bȧ֖yiţ ʼàşěr-ʼáb֣wòʼ ʼélá֑y⁠w wa⁠yi̇ţėn-li֣⁠y ha⁠mė֔lekĕ kĕ̇⁠yad-ʼèlòha֖⁠y ha⁠ṫwòbá֥h ʻáláֽ⁠y׃"],[2,9,"וָֽ⁠אָב֗וֹא אֶֽל־פַּֽחֲווֹת֙ עֵ֣בֶר הַ⁠נָּהָ֔ר וָ⁠אֶתְּנָ֣⁠ה לָ⁠הֶ֔ם אֵ֖ת אִגְּר֣וֹת הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֤ח עִמִּ⁠י֙ הַ⁠מֶּ֔לֶךְ שָׂ֥רֵי חַ֖יִל וּ⁠פָרָשִֽׁים׃פ","wáֽ⁠ʼáb֗wòʼ ʼeֽl-pȧֽẖàwwòţ֙ ʻé֣ber ha⁠ná̇há֔r wá⁠ʼeţĕ̇ná֣⁠h lá⁠he֔m ʼé֖ţ ʼigĕ̇r֣wòţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֤ẖ ʻimi̇⁠y֙ ha⁠mė֔lekĕ şá֥̂réy ẖa֖yil ẇ⁠páráşǐֽym׃p"],[2,10,"וַ⁠יִּשְׁמַ֞ע סַנְבַלַּ֣ט הַ⁠חֹרֹנִ֗י וְ⁠טֽוֹבִיָּה֙ הָ⁠עֶ֣בֶד הָֽ⁠עַמֹּנִ֔י וַ⁠יֵּ֥רַע לָ⁠הֶ֖ם רָעָ֣ה גְדֹלָ֑ה אֲשֶׁר־בָּ֥א אָדָ֔ם לְ⁠בַקֵּ֥שׁ טוֹבָ֖ה לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇şĕ̌ma֞ʻ sanĕbalȧ֣t ha⁠ẖòròni֗y wĕ⁠tֽwòbiyá̇h֙ há⁠ʻe֣bed háֽ⁠ʻamò̇ni֔y wa⁠yé֥̇raʻ lá⁠he֖m ráʻá֣h gĕdòlá֑h ʼàşěr-bá֥̇ʼ ʼádá֔m lĕ⁠baqé֥̇ş̌ twòbá֖h li⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[2,11,"וָ⁠אָב֖וֹא אֶל־יְרוּשָׁלִָ֑ם וָ⁠אֱהִי־שָׁ֖ם יָמִ֥ים שְׁלֹשָֽׁה׃","wá⁠ʼáb֖wòʼ ʼel-yĕrẇşá̌liá֑m wá⁠ʼèhiy-şá֖̌m yámi֥ym şĕ̌lòşáֽ̌h׃"],[2,12,"וָ⁠אָק֣וּם ׀ לַ֗יְלָה אֲנִי֮ וַ⁠אֲנָשִׁ֣ים ׀ מְעַט֮ עִמִּ⁠י֒ וְ⁠לֹא־הִגַּ֣דְתִּי לְ⁠אָדָ֔ם מָ֗ה אֱלֹהַ⁠י֙ נֹתֵ֣ן אֶל־לִבִּ֔⁠י לַ⁠עֲשׂ֖וֹת לִ⁠ירוּשָׁלִָ֑ם וּ⁠בְהֵמָה֙ אֵ֣ין עִמִּ֔⁠י כִּ֚י אִם־הַ⁠בְּהֵמָ֔ה אֲשֶׁ֥ר אֲנִ֖י רֹכֵ֥ב בָּֽ⁠הּ׃","wá⁠ʼáq֣ẇm ׀ la֗yĕláh ʼàniy֮ wa⁠ʼànáşǐ֣ym ׀ mĕʻat֮ ʻimi̇⁠y֒ wĕ⁠lòʼ-higȧ֣dĕţi̇y lĕ⁠ʼádá֔m má֗h ʼèlòha⁠y֙ nòţé֣n ʼel-libi̇֔⁠y la⁠ʻàş֖̂wòţ li⁠yrẇşá̌liá֑m ẇ⁠bĕhémáh֙ ʼé֣yn ʻimi̇֔⁠y ki֚̇y ʼim-ha⁠bĕ̇hémá֔h ʼàşě֥r ʼàni֖y ròké֥b báֽ̇⁠ḣ׃"],[2,13,"וָ⁠אֵצְאָ֨⁠ה בְ⁠שַֽׁעַר־הַ⁠גַּ֜יא לַ֗יְלָה וְ⁠אֶל־פְּנֵי֙ עֵ֣ין הַתַּנִּ֔ין וְ⁠אֶל־שַׁ֖עַר הָ⁠אַשְׁפֹּ֑ת וָ⁠אֱהִ֨י שֹׂבֵ֜ר בְּ⁠חוֹמֹ֤ת יְרוּשָׁלִַ֨ם֙ אֲשֶׁר־ ה⁠מפרוצים וּ⁠שְׁעָרֶ֖י⁠הָ אֻכְּל֥וּ בָ⁠אֵֽשׁ׃","wá⁠ʼéẕĕʼá֨⁠h bĕ⁠şǎֽʻar-ha⁠gȧ֜yʼ la֗yĕláh wĕ⁠ʼel-pĕ̇néy֙ ʻé֣yn haţȧni̇֔yn wĕ⁠ʼel-şǎ֖ʻar há⁠ʼaşĕ̌pò֑̇ţ wá⁠ʼèhi֨y şò̂bé֜r bĕ̇⁠ẖwòmò֤ţ yĕrẇşá̌lia֨m֙ ʼàşěr- h⁠mprwẕym ẇ⁠şĕ̌ʻáre֖y⁠há ʼukĕ̇l֥ẇ bá⁠ʼéֽş̌׃"],[2,14,"וָ⁠אֶֽעֱבֹר֙ אֶל־שַׁ֣עַר הָ⁠עַ֔יִן וְ⁠אֶל־בְּרֵכַ֖ת הַ⁠מֶּ֑לֶךְ וְ⁠אֵין־מָק֥וֹם לַ⁠בְּהֵמָ֖ה לַ⁠עֲבֹ֥ר תַּחְתָּֽ⁠י׃","wá⁠ʼeֽʻèbòr֙ ʼel-şǎ֣ʻar há⁠ʻa֔yin wĕ⁠ʼel-bĕ̇réka֖ţ ha⁠mė֑lekĕ wĕ⁠ʼéyn-máq֥wòm la⁠bĕ̇hémá֖h la⁠ʻàbò֥r ţȧẖĕţáֽ̇⁠y׃"],[2,15,"וָ⁠אֱהִ֨י עֹלֶ֤ה בַ⁠נַּ֨חַל֙ לַ֔יְלָה וָ⁠אֱהִ֥י שֹׂבֵ֖ר בַּ⁠חוֹמָ֑ה וָ⁠אָשׁ֗וּב וָ⁠אָב֛וֹא בְּ⁠שַׁ֥עַר הַ⁠גַּ֖יְא וָ⁠אָשֽׁוּב׃","wá⁠ʼèhi֨y ʻòle֤h ba⁠nȧ֨ẖal֙ la֔yĕláh wá⁠ʼèhi֥y şò̂bé֖r bȧ⁠ẖwòmá֑h wá⁠ʼáş̌֗ẇb wá⁠ʼáb֛wòʼ bĕ̇⁠şǎ֥ʻar ha⁠gȧ֖yĕʼ wá⁠ʼáşֽ̌ẇb׃"],[2,16,"וְ⁠הַ⁠סְּגָנִ֗ים לֹ֤א יָדְעוּ֙ אָ֣נָה הָלַ֔כְתִּי וּ⁠מָ֖ה אֲנִ֣י עֹשֶׂ֑ה וְ⁠לַ⁠יְּהוּדִ֨ים וְ⁠לַ⁠כֹּהֲנִ֜ים וְ⁠לַ⁠חֹרִ֣ים וְ⁠לַ⁠סְּגָנִ֗ים וּ⁠לְ⁠יֶ֨תֶר֙ עֹשֵׂ֣ה הַ⁠מְּלָאכָ֔ה עַד־כֵּ֖ן לֹ֥א הִגַּֽדְתִּי׃","wĕ⁠ha⁠sĕ̇gáni֗ym lò֤ʼ yádĕʻẇ֙ ʼá֣náh hála֔kĕţi̇y ẇ⁠má֖h ʼàni֣y ʻòşê֑h wĕ⁠la⁠yĕ̇hẇdi֨ym wĕ⁠la⁠kò̇hàni֜ym wĕ⁠la⁠ẖòri֣ym wĕ⁠la⁠sĕ̇gáni֗ym ẇ⁠lĕ⁠ye֨ţer֙ ʻòşé֣̂h ha⁠mĕ̇láʼká֔h ʻad-ké֖̇n lò֥ʼ higȧֽdĕţi̇y׃"],[2,17,"וָ⁠אוֹמַ֣ר אֲלֵ⁠הֶ֗ם אַתֶּ֤ם רֹאִים֙ הָ⁠רָעָה֙ אֲשֶׁ֣ר אֲנַ֣חְנוּ בָ֔⁠הּ אֲשֶׁ֤ר יְרוּשָׁלִַ֨ם֙ חֲרֵבָ֔ה וּ⁠שְׁעָרֶ֖י⁠הָ נִצְּת֣וּ בָ⁠אֵ֑שׁ לְכ֗וּ וְ⁠נִבְנֶה֙ אֶת־חוֹמַ֣ת יְרוּשָׁלִַ֔ם וְ⁠לֹא־נִהְיֶ֥ה ע֖וֹד חֶרְפָּֽה׃","wá⁠ʼwòma֣r ʼàlé⁠he֗m ʼaţė֤m ròʼiym֙ há⁠ráʻáh֙ ʼàşě֣r ʼàna֣ẖĕnẇ bá֔⁠ḣ ʼàşě֤r yĕrẇşá̌lia֨m֙ ẖàrébá֔h ẇ⁠şĕ̌ʻáre֖y⁠há niẕĕ̇ţ֣ẇ bá⁠ʼé֑ş̌ lĕk֗ẇ wĕ⁠nibĕneh֙ ʼeţ-ẖwòma֣ţ yĕrẇşá̌lia֔m wĕ⁠lòʼ-nihĕye֥h ʻ֖wòd ẖerĕpáֽ̇h׃"],[2,18,"וָ⁠אַגִּ֨יד לָ⁠הֶ֜ם אֶת־יַ֣ד אֱלֹהַ֗⁠י אֲשֶׁר־הִיא֙ טוֹבָ֣ה עָלַ֔⁠י וְ⁠אַף־דִּבְרֵ֥י הַ⁠מֶּ֖לֶךְ אֲשֶׁ֣ר אָֽמַר־לִ֑⁠י וַ⁠יֹּֽאמְרוּ֙ נָק֣וּם וּ⁠בָנִ֔ינוּ וַ⁠יְחַזְּק֥וּ יְדֵי⁠הֶ֖ם לַ⁠טּוֹבָֽה׃פ","wá⁠ʼagi̇֨yd lá⁠he֜m ʼeţ-ya֣d ʼèlòha֗⁠y ʼàşěr-hiyʼ֙ twòbá֣h ʻála֔⁠y wĕ⁠ʼap-di̇bĕré֥y ha⁠mė֖lekĕ ʼàşě֣r ʼáֽmar-li֑⁠y wa⁠yòֽ̇ʼmĕrẇ֙ náq֣ẇm ẇ⁠báni֔ynẇ wa⁠yĕẖazĕ̇q֥ẇ yĕdéy⁠he֖m la⁠ṫwòbáֽh׃p"],[2,19,"וַ⁠יִּשְׁמַע֩ סַנְבַלַּ֨ט הַ⁠חֹרֹנִ֜י וְ⁠טֹבִיָּ֣ה ׀ הָ⁠עֶ֣בֶד הָֽ⁠עַמּוֹנִ֗י וְ⁠גֶ֨שֶׁם֙ הָֽ⁠עַרְבִ֔י וַ⁠יַּלְעִ֣גוּ לָ֔⁠נוּ וַ⁠יִּבְז֖וּ עָלֵ֑י⁠נוּ וַ⁠יֹּאמְר֗וּ מָֽה־הַ⁠דָּבָ֤ר הַ⁠זֶּה֙ אֲשֶׁ֣ר אַתֶּ֣ם עֹשִׂ֔ים הַ⁠עַ֥ל הַ⁠מֶּ֖לֶךְ אַתֶּ֥ם מֹרְדִֽים׃","wa⁠yi̇şĕ̌maʻ֩ sanĕbalȧ֨t ha⁠ẖòròni֜y wĕ⁠tòbiyá֣̇h ׀ há⁠ʻe֣bed háֽ⁠ʻaṁwòni֗y wĕ⁠ge֨şěm֙ háֽ⁠ʻarĕbi֔y wa⁠yȧlĕʻi֣gẇ lá֔⁠nẇ wa⁠yi̇bĕz֖ẇ ʻálé֑y⁠nẇ wa⁠yò̇ʼmĕr֗ẇ máֽh-ha⁠dá̇bá֤r ha⁠zėh֙ ʼàşě֣r ʼaţė֣m ʻòşî֔ym ha⁠ʻa֥l ha⁠mė֖lekĕ ʼaţė֥m mòrĕdiֽym׃"],[2,20,"וָ⁠אָשִׁ֨יב אוֹתָ֜⁠ם דָּבָ֗ר וָ⁠אוֹמַ֤ר לָ⁠הֶם֙ אֱלֹהֵ֣י הַ⁠שָּׁמַ֔יִם ה֚וּא יַצְלִ֣יחַֽ לָ֔⁠נוּ וַ⁠אֲנַ֥חְנוּ עֲבָדָ֖י⁠ו נָק֣וּם וּ⁠בָנִ֑ינוּ וְ⁠לָ⁠כֶ֗ם אֵֽין־חֵ֧לֶק וּ⁠צְדָקָ֛ה וְ⁠זִכָּר֖וֹן בִּ⁠ירוּשָׁלִָֽם׃","wá⁠ʼáşǐ֨yb ʼwòţá֜⁠m dá̇bá֗r wá⁠ʼwòma֤r lá⁠hem֙ ʼèlòhé֣y ha⁠şá̇̌ma֔yim h֚ẇʼ yaẕĕli֣yẖaֽ lá֔⁠nẇ wa⁠ʼàna֥ẖĕnẇ ʻàbádá֖y⁠w náq֣ẇm ẇ⁠báni֑ynẇ wĕ⁠lá⁠ke֗m ʼéֽyn-ẖé֧leq ẇ⁠ẕĕdáqá֛h wĕ⁠ziká̇r֖wòn bi̇⁠yrẇşá̌liáֽm׃"],[3,1,"וַ⁠יָּ֡קָם אֶלְיָשִׁיב֩ הַ⁠כֹּהֵ֨ן הַ⁠גָּד֜וֹל וְ⁠אֶחָ֣י⁠ו הַ⁠כֹּהֲנִ֗ים וַ⁠יִּבְנוּ֙ אֶת־שַׁ֣עַר הַ⁠צֹּ֔אן הֵ֣מָּה קִדְּשׁ֔וּ⁠הוּ וַֽ⁠יַּעֲמִ֖ידוּ דַּלְתֹתָ֑י⁠ו וְ⁠עַד־מִגְדַּ֤ל הַ⁠מֵּאָה֙ קִדְּשׁ֔וּ⁠הוּ עַ֖ד מִגְדַּ֥ל חֲנַנְאֵֽל׃ס","wa⁠yá̇֡qám ʼelĕyáşǐyb֩ ha⁠kò̇hé֨n ha⁠gá̇d֜wòl wĕ⁠ʼeẖá֣y⁠w ha⁠kò̇hàni֗ym wa⁠yi̇bĕnẇ֙ ʼeţ-şǎ֣ʻar ha⁠ẕò̇֔ʼn hé֣má̇h qidĕ̇ş̌֔ẇ⁠hẇ wֽa⁠yȧʻàmi֖ydẇ dȧlĕţòţá֑y⁠w wĕ⁠ʻad-migĕdȧ֤l ha⁠mé̇ʼáh֙ qidĕ̇ş̌֔ẇ⁠hẇ ʻa֖d migĕdȧ֥l ẖànanĕʼéֽl׃s"],[3,2,"וְ⁠עַל־יָד֥⁠וֹ בָנ֖וּ אַנְשֵׁ֣י יְרֵח֑וֹ ס וְ⁠עַל־יָד֣⁠וֹ בָנָ֔ה זַכּ֖וּר בֶּן־אִמְרִֽי׃ס","wĕ⁠ʻal-yád֥⁠wò bán֖ẇ ʼanĕşé֣̌y yĕréẖ֑wò s wĕ⁠ʻal-yád֣⁠wò báná֔h zak֖̇ẇr bėn-ʼimĕriֽy׃s"],[3,3,"וְ⁠אֵת֙ שַׁ֣עַר הַ⁠דָּגִ֔ים בָּנ֖וּ בְּנֵ֣י הַ⁠סְּנָאָ֑ה הֵ֣מָּה קֵר֔וּ⁠הוּ וַֽ⁠יַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔י⁠ו מַנְעוּלָ֖י⁠ו וּ⁠בְרִיחָֽי⁠ו׃ס","wĕ⁠ʼéţ֙ şǎ֣ʻar ha⁠dá̇gi֔ym bá̇n֖ẇ bĕ̇né֣y ha⁠sĕ̇náʼá֑h hé֣má̇h qér֔ẇ⁠hẇ wֽa⁠yȧʻàmi֨ydẇ֙ dȧlĕţòţá֔y⁠w manĕʻẇlá֖y⁠w ẇ⁠bĕriyẖáֽy⁠w׃s"],[3,4,"וְ⁠עַל־יָדָ֣⁠ם הֶחֱזִ֗יק מְרֵמ֤וֹת בֶּן־אוּרִיָּה֙ בֶּן־הַקּ֔וֹץ ס וְ⁠עַל־יָדָ֣⁠ם הֶחֱזִ֔יק מְשֻׁלָּ֥ם בֶּן־בֶּרֶכְיָ֖ה בֶּן־מְשֵׁיזַבְאֵ֑ל ס וְ⁠עַל־יָדָ֣⁠ם הֶֽחֱזִ֔יק צָד֖וֹק בֶּֽן־בַּעֲנָֽא׃ס","wĕ⁠ʻal-yádá֣⁠m heẖèzi֗yq mĕrém֤wòţ bėn-ʼẇriyá̇h֙ bėn-haq̇֔wòẕ s wĕ⁠ʻal-yádá֣⁠m heẖèzi֔yq mĕşǔlá֥̇m bėn-bėrekĕyá֖h bėn-mĕşé̌yzabĕʼé֑l s wĕ⁠ʻal-yádá֣⁠m heֽẖèzi֔yq ẕád֖wòq bėֽn-bȧʻànáֽʼ׃s"],[3,5,"וְ⁠עַל־יָדָ֖⁠ם הֶחֱזִ֣יקוּ הַ⁠תְּקוֹעִ֑ים וְ⁠אַדִּֽירֵי⁠הֶם֙ לֹא־הֵבִ֣יאוּ צַוָּרָ֔⁠ם בַּ⁠עֲבֹדַ֖ת אֲדֹנֵי⁠הֶֽם׃ס","wĕ⁠ʻal-yádá֖⁠m heẖèzi֣yqẇ ha⁠ţĕ̇qwòʻi֑ym wĕ⁠ʼadiֽ̇yréy⁠hem֙ lòʼ-hébi֣yʼẇ ẕawá̇rá֔⁠m bȧ⁠ʻàbòda֖ţ ʼàdònéy⁠heֽm׃s"],[3,6,"וְ⁠אֵת֩ שַׁ֨עַר הַיְשָׁנָ֜ה הֶחֱזִ֗יקוּ יֽוֹיָדָע֙ בֶּן־פָּסֵ֔חַ וּ⁠מְשֻׁלָּ֖ם בֶּן־בְּסֽוֹדְיָ֑ה הֵ֣מָּה קֵר֔וּ⁠הוּ וַֽ⁠יַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔י⁠ו וּ⁠מַנְעֻלָ֖י⁠ו וּ⁠בְרִיחָֽי⁠ו׃ס","wĕ⁠ʼéţ֩ şǎ֨ʻar hayĕşá̌ná֜h heẖèzi֗yqẇ yֽwòyádáʻ֙ bėn-pá̇sé֔ẖa ẇ⁠mĕşǔlá֖̇m bėn-bĕ̇sֽwòdĕyá֑h hé֣má̇h qér֔ẇ⁠hẇ wֽa⁠yȧʻàmi֨ydẇ֙ dȧlĕţòţá֔y⁠w ẇ⁠manĕʻulá֖y⁠w ẇ⁠bĕriyẖáֽy⁠w׃s"],[3,7,"וְ⁠עַל־יָדָ֨⁠ם הֶחֱזִ֜יק מְלַטְיָ֣ה הַ⁠גִּבְעֹנִ֗י וְ⁠יָדוֹן֙ הַ⁠מֵּרֹ֣נֹתִ֔י אַנְשֵׁ֥י גִבְע֖וֹן וְ⁠הַ⁠מִּצְפָּ֑ה לְ⁠כִסֵּ֕א פַּחַ֖ת עֵ֥בֶר הַ⁠נָּהָֽר׃ס","wĕ⁠ʻal-yádá֨⁠m heẖèzi֜yq mĕlatĕyá֣h ha⁠gi̇bĕʻòni֗y wĕ⁠yádwòn֙ ha⁠mé̇rò֣nòţi֔y ʼanĕşé֥̌y gibĕʻ֖wòn wĕ⁠ha⁠mi̇ẕĕpá֑̇h lĕ⁠kisé̇֕ʼ pȧẖa֖ţ ʻé֥ber ha⁠ná̇háֽr׃s"],[3,8,"עַל־יָד֣⁠וֹ הֶחֱזִ֗יק עֻזִּיאֵ֤ל בֶּֽן־חַרְהֲיָה֙ צֽוֹרְפִ֔ים ס וְ⁠עַל־יָד֣⁠וֹ הֶחֱזִ֔יק חֲנַנְיָ֖ה בֶּן־הָ⁠רַקָּחִ֑ים וַ⁠יַּֽעַזְבוּ֙ יְר֣וּשָׁלִַ֔ם עַ֖ד הַ⁠חוֹמָ֥ה הָ⁠רְחָבָֽה׃ס","ʻal-yád֣⁠wò heẖèzi֗yq ʻuzi̇yʼé֤l bėֽn-ẖarĕhàyáh֙ ẕֽwòrĕpi֔ym s wĕ⁠ʻal-yád֣⁠wò heẖèzi֔yq ẖànanĕyá֖h bėn-há⁠raqá̇ẖi֑ym wa⁠yȧֽʻazĕbẇ֙ yĕr֣ẇşá̌lia֔m ʻa֖d ha⁠ẖwòmá֥h há⁠rĕẖábáֽh׃s"],[3,9,"וְ⁠עַל־יָדָ֤⁠ם הֶחֱזִיק֙ רְפָיָ֣ה בֶן־ח֔וּר שַׂ֕ר חֲצִ֖י פֶּ֥לֶךְ יְרוּשָׁלִָֽם׃ס","wĕ⁠ʻal-yádá֤⁠m heẖèziyq֙ rĕpáyá֣h ben-ẖ֔ẇr şâ֕r ẖàẕi֖y pė֥lekĕ yĕrẇşá̌liáֽm׃s"],[3,10,"וְ⁠עַל־יָדָ֧⁠ם הֶחֱזִ֛יק יְדָיָ֥ה בֶן־חֲרוּמַ֖ף וְ⁠נֶ֣גֶד בֵּית֑⁠וֹ ס וְ⁠עַל־יָד֣⁠וֹ הֶחֱזִ֔יק חַטּ֖וּשׁ בֶּן־חֲשַׁבְנְיָֽה׃","wĕ⁠ʻal-yádá֧⁠m heẖèzi֛yq yĕdáyá֥h ben-ẖàrẇma֖p wĕ⁠ne֣ged bé̇yţ֑⁠wò s wĕ⁠ʻal-yád֣⁠wò heẖèzi֔yq ẖaṫ֖ẇş̌ bėn-ẖàşǎbĕnĕyáֽh׃"],[3,11,"מִדָּ֣ה שֵׁנִ֗ית הֶחֱזִיק֙ מַלְכִּיָּ֣ה בֶן־חָרִ֔ם וְ⁠חַשּׁ֖וּב בֶּן־פַּחַ֣ת מוֹאָ֑ב וְ⁠אֵ֖ת מִגְדַּ֥ל הַ⁠תַּנּוּרִֽים׃ס","midá֣̇h şé̌ni֗yţ heẖèziyq֙ malĕki̇yá֣̇h ben-ẖári֔m wĕ⁠ẖaş֖̇̌ẇb bėn-pȧẖa֣ţ mwòʼá֑b wĕ⁠ʼé֖ţ migĕdȧ֥l ha⁠ţȧṅẇriֽym׃s"],[3,12,"וְ⁠עַל־יָד֣⁠וֹ הֶחֱזִ֗יק שַׁלּוּם֙ בֶּן־הַלּוֹחֵ֔שׁ שַׂ֕ר חֲצִ֖י פֶּ֣לֶךְ יְרוּשָׁלִָ֑ם ה֖וּא וּ⁠בְנוֹתָֽי⁠ו׃ס","wĕ⁠ʻal-yád֣⁠wò heẖèzi֗yq şǎl̇ẇm֙ bėn-hal̇wòẖé֔ş̌ şâ֕r ẖàẕi֖y pė֣lekĕ yĕrẇşá̌liá֑m h֖ẇʼ ẇ⁠bĕnwòţáֽy⁠w׃s"],[3,13,"אֵת֩ שַׁ֨עַר הַ⁠גַּ֜יְא הֶחֱזִ֣יק חָנוּן֮ וְ⁠יֹשְׁבֵ֣י זָנוֹחַ֒ הֵ֣מָּה בָנ֔וּ⁠הוּ וַֽ⁠יַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔י⁠ו מַנְעֻלָ֖י⁠ו וּ⁠בְרִיחָ֑י⁠ו וְ⁠אֶ֤לֶף אַמָּה֙ בַּ⁠חוֹמָ֔ה עַ֖ד שַׁ֥עַר הָ⁠שֲׁפֽוֹת׃","ʼéţ֩ şǎ֨ʻar ha⁠gȧ֜yĕʼ heẖèzi֣yq ẖánẇn֮ wĕ⁠yòşĕ̌bé֣y zánwòẖa֒ hé֣má̇h bán֔ẇ⁠hẇ wֽa⁠yȧʻàmi֨ydẇ֙ dȧlĕţòţá֔y⁠w manĕʻulá֖y⁠w ẇ⁠bĕriyẖá֑y⁠w wĕ⁠ʼe֤lep ʼamá̇h֙ bȧ⁠ẖwòmá֔h ʻa֖d şǎ֥ʻar há⁠şà̌pֽwòţ׃"],[3,14,"וְ⁠אֵ֣ת ׀ שַׁ֣עַר הָ⁠אַשְׁפּ֗וֹת הֶחֱזִיק֙ מַלְכִּיָּ֣ה בֶן־רֵכָ֔ב שַׂ֖ר פֶּ֣לֶךְ בֵּית־הַכָּ֑רֶם ה֣וּא יִבְנֶ֔⁠נּוּ וְ⁠יַעֲמִיד֙ דַּלְתֹתָ֔י⁠ו מַנְעֻלָ֖י⁠ו וּ⁠בְרִיחָֽי⁠ו׃ס","wĕ⁠ʼé֣ţ ׀ şǎ֣ʻar há⁠ʼaşĕ̌ṗ֗wòţ heẖèziyq֙ malĕki̇yá֣̇h ben-réká֔b şâ֖r pė֣lekĕ bé̇yţ-haká֑̇rem h֣ẇʼ yibĕne֔⁠ṅẇ wĕ⁠yaʻàmiyd֙ dȧlĕţòţá֔y⁠w manĕʻulá֖y⁠w ẇ⁠bĕriyẖáֽy⁠w׃s"],[3,15,"וְ⁠אֵת֩ שַׁ֨עַר הָ⁠עַ֜יִן הֶ֠חֱזִיק שַׁלּ֣וּן בֶּן־כָּל־חֹזֶה֮ שַׂ֣ר פֶּ֣לֶךְ הַ⁠מִּצְפָּה֒ ה֤וּא יִבְנֶ֨⁠נּוּ֙ וִ⁠יטַֽלְלֶ֔⁠נּוּ ויעמידו דַּלְתֹתָ֔י⁠ו מַנְעֻלָ֖י⁠ו וּ⁠בְרִיחָ֑י⁠ו וְ֠⁠אֵת חוֹמַ֞ת בְּרֵכַ֤ת הַ⁠שֶּׁ֨לַח֙ לְ⁠גַן־הַ⁠מֶּ֔לֶךְ וְ⁠עַד־הַֽ⁠מַּעֲל֔וֹת הַ⁠יּוֹרְד֖וֹת מֵ⁠עִ֥יר דָּוִֽיד׃ס","wĕ⁠ʼéţ֩ şǎ֨ʻar há⁠ʻa֜yin he֠ẖèziyq şǎl֣̇ẇn bėn-ká̇l-ẖòzeh֮ şâ֣r pė֣lekĕ ha⁠mi̇ẕĕpá̇h֒ h֤ẇʼ yibĕne֨⁠ṅẇ֙ wi⁠ytaֽlĕle֔⁠ṅẇ wyʻmydw dȧlĕţòţá֔y⁠w manĕʻulá֖y⁠w ẇ⁠bĕriyẖá֑y⁠w wĕ֠⁠ʼéţ ẖwòma֞ţ bĕ̇réka֤ţ ha⁠şė̌֨laẖ֙ lĕ⁠gan-ha⁠mė֔lekĕ wĕ⁠ʻad-haֽ⁠mȧʻàl֔wòţ ha⁠ẏwòrĕd֖wòţ mé⁠ʻi֥yr dá̇wiֽyd׃s"],[3,16,"אַחֲרָ֤י⁠ו הֶחֱזִיק֙ נְחֶמְיָ֣ה בֶן־עַזְבּ֔וּק שַׂ֕ר חֲצִ֖י פֶּ֣לֶךְ בֵּֽית־צ֑וּר עַד־נֶ֨גֶד֙ קִבְרֵ֣י דָוִ֔יד וְ⁠עַד־הַ⁠בְּרֵכָה֙ הָ⁠עֲשׂוּיָ֔ה וְ⁠עַ֖ד בֵּ֥ית הַ⁠גִּבֹּרִֽים׃ס","ʼaẖàrá֤y⁠w heẖèziyq֙ nĕẖemĕyá֣h ben-ʻazĕḃ֔ẇq şâ֕r ẖàẕi֖y pė֣lekĕ béֽ̇yţ-ẕ֑ẇr ʻad-ne֨ged֙ qibĕré֣y dáwi֔yd wĕ⁠ʻad-ha⁠bĕ̇rékáh֙ há⁠ʻàş̂ẇyá֔h wĕ⁠ʻa֖d bé֥̇yţ ha⁠gi̇bò̇riֽym׃s"],[3,17,"אַחֲרָ֛י⁠ו הֶחֱזִ֥יקוּ הַ⁠לְוִיִּ֖ם רְח֣וּם בֶּן־בָּנִ֑י עַל־יָד֣⁠וֹ הֶחֱזִ֗יק חֲשַׁבְיָ֛ה שַׂר־חֲצִי־פֶ֥לֶךְ קְעִילָ֖ה לְ⁠פִלְכּֽ⁠וֹ׃ס","ʼaẖàrá֛y⁠w heẖèzi֥yqẇ ha⁠lĕwiyi֖̇m rĕẖ֣ẇm bėn-bá̇ni֑y ʻal-yád֣⁠wò heẖèzi֗yq ẖàşǎbĕyá֛h şâr-ẖàẕiy-pe֥lekĕ qĕʻiylá֖h lĕ⁠pilĕkֽ̇⁠wò׃s"],[3,18,"אַחֲרָי⁠ו֙ הֶחֱזִ֣יקוּ אֲחֵי⁠הֶ֔ם בַּוַּ֖י בֶּן־חֵנָדָ֑ד שַׂ֕ר חֲצִ֖י פֶּ֥לֶךְ קְעִילָֽה׃ס","ʼaẖàráy⁠w֙ heẖèzi֣yqẇ ʼàẖéy⁠he֔m bȧwȧ֖y bėn-ẖénádá֑d şâ֕r ẖàẕi֖y pė֥lekĕ qĕʻiyláֽh׃s"],[3,19,"וַ⁠יְחַזֵּ֨ק עַל־יָד֜⁠וֹ עֵ֧זֶר בֶּן־יֵשׁ֛וּעַ שַׂ֥ר הַ⁠מִּצְפָּ֖ה מִדָּ֣ה שֵׁנִ֑ית מִ⁠נֶּ֕גֶד עֲלֹ֥ת הַ⁠נֶּ֖שֶׁק הַ⁠מִּקְצֹֽעַ׃ס","wa⁠yĕẖazé̇֨q ʻal-yád֜⁠wò ʻé֧zer bėn-yéş֛̌ẇʻa şâ֥r ha⁠mi̇ẕĕpá֖̇h midá֣̇h şé̌ni֑yţ mi⁠nė֕ged ʻàlò֥ţ ha⁠nė֖şěq ha⁠mi̇qĕẕòֽʻa׃s"],[3,20,"אַחֲרָ֨י⁠ו הֶחֱרָ֧ה הֶחֱזִ֛יק בָּר֥וּךְ בֶּן־זבי מִדָּ֣ה שֵׁנִ֑ית מִן־הַ֨⁠מִּקְצ֔וֹעַ עַד־פֶּ֨תַח֙ בֵּ֣ית אֶלְיָשִׁ֔יב הַ⁠כֹּהֵ֖ן הַ⁠גָּדֽוֹל׃ס","ʼaẖàrá֨y⁠w heẖèrá֧h heẖèzi֛yq bá̇r֥ẇkĕ bėn-zby midá֣̇h şé̌ni֑yţ min-ha֨⁠mi̇qĕẕ֔wòʻa ʻad-pė֨ţaẖ֙ bé֣̇yţ ʼelĕyáşǐ֔yb ha⁠kò̇hé֖n ha⁠gá̇dֽwòl׃s"],[3,21,"אַחֲרָ֣י⁠ו הֶחֱזִ֗יק מְרֵמ֧וֹת בֶּן־אוּרִיָּ֛ה בֶּן־הַקּ֖וֹץ מִדָּ֣ה שֵׁנִ֑ית מִ⁠פֶּ֨תַח֙ בֵּ֣ית אֶלְיָשִׁ֔יב וְ⁠עַד־תַּכְלִ֖ית בֵּ֥ית אֶלְיָשִֽׁיב׃ס","ʼaẖàrá֣y⁠w heẖèzi֗yq mĕrém֧wòţ bėn-ʼẇriyá֛̇h bėn-haq֖̇wòẕ midá֣̇h şé̌ni֑yţ mi⁠pė֨ţaẖ֙ bé֣̇yţ ʼelĕyáşǐ֔yb wĕ⁠ʻad-ţȧkĕli֖yţ bé֥̇yţ ʼelĕyáşǐֽyb׃s"],[3,22,"וְ⁠אַחֲרָ֛י⁠ו הֶחֱזִ֥יקוּ הַ⁠כֹּהֲנִ֖ים אַנְשֵׁ֥י הַ⁠כִּכָּֽר׃","wĕ⁠ʼaẖàrá֛y⁠w heẖèzi֥yqẇ ha⁠kò̇hàni֖ym ʼanĕşé֥̌y ha⁠ki̇káֽ̇r׃"],[3,23,"אַחֲרָ֨י⁠ו הֶחֱזִ֧יק בִּנְיָמִ֛ן וְ⁠חַשּׁ֖וּב נֶ֣גֶד בֵּיתָ֑⁠ם ס אַחֲרָ֣י⁠ו הֶחֱזִ֗יק עֲזַרְיָ֧ה בֶן־מַעֲשֵׂיָ֛ה בֶּן־עֲנָֽנְיָ֖ה אֵ֥צֶל בֵּיתֽ⁠וֹ׃ס","ʼaẖàrá֨y⁠w heẖèzi֧yq bi̇nĕyámi֛n wĕ⁠ẖaş֖̇̌ẇb ne֣ged bé̇yţá֑⁠m s ʼaẖàrá֣y⁠w heẖèzi֗yq ʻàzarĕyá֧h ben-maʻàşé̂yá֛h bėn-ʻànáֽnĕyá֖h ʼé֥ẕel bé̇yţֽ⁠wò׃s"],[3,24,"אַחֲרָ֣י⁠ו הֶחֱזִ֗יק בִּנּ֛וּי בֶּן־חֵנָדָ֖ד מִדָּ֣ה שֵׁנִ֑ית מִ⁠בֵּ֣ית עֲזַרְיָ֔ה עַד־הַ⁠מִּקְצ֖וֹעַ וְ⁠עַד־הַ⁠פִּנָּֽה׃","ʼaẖàrá֣y⁠w heẖèzi֗yq bi̇ṅ֛ẇy bėn-ẖénádá֖d midá֣̇h şé̌ni֑yţ mi⁠bé֣̇yţ ʻàzarĕyá֔h ʻad-ha⁠mi̇qĕẕ֖wòʻa wĕ⁠ʻad-ha⁠pi̇náֽ̇h׃"],[3,25,"פָּלָ֣ל בֶּן־אוּזַי֮ מִ⁠נֶּ֣גֶד הַ⁠מִּקְצוֹעַ֒ וְ⁠הַ⁠מִּגְדָּ֗ל הַ⁠יּוֹצֵא֙ מִ⁠בֵּ֤ית הַ⁠מֶּ֨לֶךְ֙ הָֽ⁠עֶלְי֔וֹן אֲשֶׁ֖ר לַ⁠חֲצַ֣ר הַ⁠מַּטָּרָ֑ה אַחֲרָ֖י⁠ו פְּדָיָ֥ה בֶן־פַּרְעֹֽשׁ׃ס","pá̇lá֣l bėn-ʼẇzay֮ mi⁠nė֣ged ha⁠mi̇qĕẕwòʻa֒ wĕ⁠ha⁠mi̇gĕdá̇֗l ha⁠ẏwòẕéʼ֙ mi⁠bé֤̇yţ ha⁠mė֨lekĕ֙ háֽ⁠ʻelĕy֔wòn ʼàşě֖r la⁠ẖàẕa֣r ha⁠mȧtá̇rá֑h ʼaẖàrá֖y⁠w pĕ̇dáyá֥h ben-pȧrĕʻòֽş̌׃s"],[3,26,"וְ⁠הַ֨⁠נְּתִינִ֔ים הָי֥וּ יֹשְׁבִ֖ים בָּ⁠עֹ֑פֶל עַ֠ד נֶ֜גֶד שַׁ֤עַר הַ⁠מַּ֨יִם֙ לַ⁠מִּזְרָ֔ח וְ⁠הַ⁠מִּגְדָּ֖ל הַ⁠יּוֹצֵֽא׃ס","wĕ⁠ha֨⁠nĕ̇ţiyni֔ym háy֥ẇ yòşĕ̌bi֖ym bá̇⁠ʻò֑pel ʻa֠d ne֜ged şǎ֤ʻar ha⁠mȧ֨yim֙ la⁠mi̇zĕrá֔ẖ wĕ⁠ha⁠mi̇gĕdá֖̇l ha⁠ẏwòẕéֽʼ׃s"],[3,27,"אַחֲרָ֛י⁠ו הֶחֱזִ֥יקוּ הַ⁠תְּקֹעִ֖ים מִדָּ֣ה שֵׁנִ֑ית מִ⁠נֶּ֜גֶד הַ⁠מִּגְדָּ֤ל הַ⁠גָּדוֹל֙ הַ⁠יּוֹצֵ֔א וְ⁠עַ֖ד חוֹמַ֥ת הָ⁠עֹֽפֶל׃","ʼaẖàrá֛y⁠w heẖèzi֥yqẇ ha⁠ţĕ̇qòʻi֖ym midá֣̇h şé̌ni֑yţ mi⁠nė֜ged ha⁠mi̇gĕdá֤̇l ha⁠gá̇dwòl֙ ha⁠ẏwòẕé֔ʼ wĕ⁠ʻa֖d ẖwòma֥ţ há⁠ʻòֽpel׃"],[3,28,"מֵ⁠עַ֣ל ׀ שַׁ֣עַר הַ⁠סּוּסִ֗ים הֶחֱזִ֨יקוּ֙ הַ⁠כֹּ֣הֲנִ֔ים אִ֖ישׁ לְ⁠נֶ֥גֶד בֵּיתֽ⁠וֹ׃ס","mé⁠ʻa֣l ׀ şǎ֣ʻar ha⁠ṡẇsi֗ym heẖèzi֨yqẇ֙ ha⁠kò֣̇hàni֔ym ʼi֖yş̌ lĕ⁠ne֥ged bé̇yţֽ⁠wò׃s"],[3,29,"אַחֲרָ֧י⁠ו הֶחֱזִ֛יק צָד֥וֹק בֶּן־אִמֵּ֖ר נֶ֣גֶד בֵּית֑⁠וֹ ס וְ⁠אַחֲרָ֤י⁠ו הֶחֱזִיק֙ שְׁמַֽעְיָ֣ה בֶן־שְׁכַנְיָ֔ה שֹׁמֵ֖ר שַׁ֥עַר הַ⁠מִּזְרָֽח׃ס","ʼaẖàrá֧y⁠w heẖèzi֛yq ẕád֥wòq bėn-ʼimé֖̇r ne֣ged bé̇yţ֑⁠wò s wĕ⁠ʼaẖàrá֤y⁠w heẖèziyq֙ şĕ̌maֽʻĕyá֣h ben-şĕ̌kanĕyá֔h şò̌mé֖r şǎ֥ʻar ha⁠mi̇zĕráֽẖ׃s"],[3,30,"אחר⁠י הֶחֱזִ֜יק חֲנַנְיָ֣ה בֶן־שֶׁלֶמְיָ֗ה וְ⁠חָנ֧וּן בֶּן־צָלָ֛ף הַ⁠שִּׁשִּׁ֖י מִדָּ֣ה שֵׁנִ֑י ס אַחֲרָ֣י⁠ו הֶחֱזִ֗יק מְשֻׁלָּם֙ בֶּן־בֶּ֣רֶכְיָ֔ה נֶ֖גֶד נִשְׁכָּתֽ⁠וֹ׃ס","ʼẖr⁠y heẖèzi֜yq ẖànanĕyá֣h ben-şělemĕyá֗h wĕ⁠ẖán֧ẇn bėn-ẕálá֛p ha⁠şi̇̌şi֖̇̌y midá֣̇h şé̌ni֑y s ʼaẖàrá֣y⁠w heẖèzi֗yq mĕşǔlá̇m֙ bėn-bė֣rekĕyá֔h ne֖ged nişĕ̌ká̇ţֽ⁠wò׃s"],[3,31,"אחר⁠י הֶחֱזִ֗יק מַלְכִּיָּה֙ בֶּן־הַ⁠צֹּ֣רְפִ֔י עַד־בֵּ֥ית הַ⁠נְּתִינִ֖ים וְ⁠הָ⁠רֹכְלִ֑ים נֶ֚גֶד שַׁ֣עַר הַ⁠מִּפְקָ֔ד וְ⁠עַ֖ד עֲלִיַּ֥ת הַ⁠פִּנָּֽה׃","ʼẖr⁠y heẖèzi֗yq malĕki̇yá̇h֙ bėn-ha⁠ẕò֣̇rĕpi֔y ʻad-bé֥̇yţ ha⁠nĕ̇ţiyni֖ym wĕ⁠há⁠ròkĕli֑ym ne֚ged şǎ֣ʻar ha⁠mi̇pĕqá֔d wĕ⁠ʻa֖d ʻàliyȧ֥ţ ha⁠pi̇náֽ̇h׃"],[3,32,"וּ⁠בֵ֨ין עֲלִיַּ֤ת הַ⁠פִּנָּה֙ לְ⁠שַׁ֣עַר הַ⁠צֹּ֔אן הֶחֱזִ֥יקוּ הַ⁠צֹּרְפִ֖ים וְ⁠הָ⁠רֹכְלִֽים׃פ","ẇ⁠bé֨yn ʻàliyȧ֤ţ ha⁠pi̇ná̇h֙ lĕ⁠şǎ֣ʻar ha⁠ẕò̇֔ʼn heẖèzi֥yqẇ ha⁠ẕò̇rĕpi֖ym wĕ⁠há⁠ròkĕliֽym׃p"],[4,1,"וַ⁠יְהִ֞י כַּ⁠אֲשֶׁ֧ר שָׁמַ֣ע סַנְבַלַּ֗ט כִּֽי־אֲנַ֤חְנוּ בוֹנִים֙ אֶת־הַ֣⁠חוֹמָ֔ה וַ⁠יִּ֣חַר ל֔⁠וֹ וַ⁠יִּכְעַ֖ס הַרְבֵּ֑ה וַ⁠יַּלְעֵ֖ג עַל־הַ⁠יְּהוּדִֽים׃","wa⁠yĕhi֞y kȧ⁠ʼàşě֧r şá̌ma֣ʻ sanĕbalȧ֗t kiֽ̇y-ʼàna֤ẖĕnẇ bwòniym֙ ʼeţ-ha֣⁠ẖwòmá֔h wa⁠yi֣̇ẖar l֔⁠wò wa⁠yi̇kĕʻa֖s harĕbé֑̇h wa⁠yȧlĕʻé֖g ʻal-ha⁠yĕ̇hẇdiֽym׃"],[4,2,"וַ⁠יֹּ֣אמֶר ׀ לִ⁠פְנֵ֣י אֶחָ֗י⁠ו וְ⁠חֵיל֙ שֹֽׁמְר֔וֹן וַ⁠יֹּ֕אמֶר מָ֛ה הַ⁠יְּהוּדִ֥ים הָ⁠אֲמֵלָלִ֖ים עֹשִׂ֑ים הֲ⁠יַעַזְב֨וּ לָ⁠הֶ֤ם הֲ⁠יִזְבָּ֨חוּ֙ הַ⁠יְכַלּ֣וּ בַ⁠יּ֔וֹם הַ⁠יְחַיּ֧וּ אֶת־הָ⁠אֲבָנִ֛ים מֵ⁠עֲרֵמ֥וֹת הֶ⁠עָפָ֖ר וְ⁠הֵ֥מָּה שְׂרוּפֽוֹת׃","wa⁠yò֣̇ʼmer ׀ li⁠pĕné֣y ʼeẖá֗y⁠w wĕ⁠ẖéyl֙ şòֽ̌mĕr֔wòn wa⁠yò̇֕ʼmer má֛h ha⁠yĕ̇hẇdi֥ym há⁠ʼàméláli֖ym ʻòşî֑ym hà⁠yaʻazĕb֨ẇ lá⁠he֤m hà⁠yizĕbá̇֨ẖẇ֙ ha⁠yĕkal֣̇ẇ ba⁠ẏ֔wòm ha⁠yĕẖaẏ֧ẇ ʼeţ-há⁠ʼàbáni֛ym mé⁠ʻàrém֥wòţ he⁠ʻápá֖r wĕ⁠hé֥má̇h şĕ̂rẇpֽwòţ׃"],[4,3,"וְ⁠טוֹבִיָּ֥ה הָ⁠עַמֹּנִ֖י אֶצְל֑⁠וֹ וַ⁠יֹּ֗אמֶר גַּ֚ם אֲשֶׁר־הֵ֣ם בּוֹנִ֔ים אִם־יַעֲלֶ֣ה שׁוּעָ֔ל וּ⁠פָרַ֖ץ חוֹמַ֥ת אַבְנֵי⁠הֶֽם׃פ","wĕ⁠twòbiyá֥̇h há⁠ʻamò̇ni֖y ʼeẕĕl֑⁠wò wa⁠yò̇֗ʼmer gȧ֚m ʼàşěr-hé֣m ḃwòni֔ym ʼim-yaʻàle֣h ş̌ẇʻá֔l ẇ⁠pára֖ẕ ẖwòma֥ţ ʼabĕnéy⁠heֽm׃p"],[4,4,"שְׁמַ֤ע אֱלֹהֵ֨י⁠נוּ֙ כִּֽי־הָיִ֣ינוּ בוּזָ֔ה וְ⁠הָשֵׁ֥ב חֶרְפָּתָ֖⁠ם אֶל־רֹאשָׁ֑⁠ם וּ⁠תְנֵ֥⁠ם לְ⁠בִזָּ֖ה בְּ⁠אֶ֥רֶץ שִׁבְיָֽה׃","şĕ̌ma֤ʻ ʼèlòhé֨y⁠nẇ֙ kiֽ̇y-háyi֣ynẇ bẇzá֔h wĕ⁠háşé֥̌b ẖerĕpá̇ţá֖⁠m ʼel-ròʼşá֑̌⁠m ẇ⁠ţĕné֥⁠m lĕ⁠bizá֖̇h bĕ̇⁠ʼe֥reẕ şǐbĕyáֽh׃"],[4,5,"וְ⁠אַל־תְּכַס֙ עַל־עֲוֺנָ֔⁠ם וְ⁠חַטָּאתָ֖⁠ם מִ⁠לְּ⁠פָנֶ֣י⁠ךָ אַל־תִּמָּחֶ֑ה כִּ֥י הִכְעִ֖יסוּ לְ⁠נֶ֥גֶד הַ⁠בּוֹנִֽים׃","wĕ⁠ʼal-ţĕ̇kas֙ ʻal-ʻàwֺná֔⁠m wĕ⁠ẖatá̇ʼţá֖⁠m mi⁠lĕ̇⁠páne֣y⁠ká ʼal-ţi̇má̇ẖe֑h ki֥̇y hikĕʻi֖ysẇ lĕ⁠ne֥ged ha⁠ḃwòniֽym׃"],[4,6,"וַ⁠נִּבְנֶה֙ אֶת־הַ֣⁠חוֹמָ֔ה וַ⁠תִּקָּשֵׁ֥ר כָּל־הַ⁠חוֹמָ֖ה עַד־חֶצְיָ֑⁠הּ וַ⁠יְהִ֧י לֵ֦ב לָ⁠עָ֖ם לַ⁠עֲשֽׂוֹת׃פ","wa⁠ni̇bĕneh֙ ʼeţ-ha֣⁠ẖwòmá֔h wa⁠ţi̇qá̇şé֥̌r ká̇l-ha⁠ẖwòmá֖h ʻad-ẖeẕĕyá֑⁠ḣ wa⁠yĕhi֧y lé֦b lá⁠ʻá֖m la⁠ʻàşֽ̂wòţ׃p"],[4,7,"וַ⁠יְהִ֣י כַ⁠אֲשֶׁ֣ר שָׁמַ֣ע סַנְבַלַּ֡ט וְ֠⁠טוֹבִיָּה וְ⁠הָ⁠עַרְבִ֨ים וְ⁠הָ⁠עַמֹּנִ֜ים וְ⁠הָ⁠אַשְׁדּוֹדִ֗ים כִּֽי־עָלְתָ֤ה אֲרוּכָה֙ לְ⁠חֹמ֣וֹת יְרוּשָׁלִַ֔ם כִּי־הֵחֵ֥לּוּ הַ⁠פְּרֻצִ֖ים לְ⁠הִסָּתֵ֑ם וַ⁠יִּ֥חַר לָ⁠הֶ֖ם מְאֹֽד׃","wa⁠yĕhi֣y ka⁠ʼàşě֣r şá̌ma֣ʻ sanĕbalȧ֡t wĕ֠⁠twòbiyá̇h wĕ⁠há⁠ʻarĕbi֨ym wĕ⁠há⁠ʻamò̇ni֜ym wĕ⁠há⁠ʼaşĕ̌ḋwòdi֗ym kiֽ̇y-ʻálĕţá֤h ʼàrẇkáh֙ lĕ⁠ẖòm֣wòţ yĕrẇşá̌lia֔m ki̇y-héẖé֥l̇ẇ ha⁠pĕ̇ruẕi֖ym lĕ⁠hisá̇ţé֑m wa⁠yi֥̇ẖar lá⁠he֖m mĕʼòֽd׃"],[4,8,"וַ⁠יִּקְשְׁר֤וּ כֻלָּ⁠ם֙ יַחְדָּ֔ו לָ⁠ב֖וֹא לְ⁠הִלָּחֵ֣ם בִּ⁠ירוּשָׁלִָ֑ם וְ⁠לַ⁠עֲשׂ֥וֹת ל֖⁠וֹ תּוֹעָֽה׃","wa⁠yi̇qĕşĕ̌r֤ẇ kulá̇⁠m֙ yaẖĕdá̇֔w lá⁠b֖wòʼ lĕ⁠hilá̇ẖé֣m bi̇⁠yrẇşá̌liá֑m wĕ⁠la⁠ʻàş֥̂wòţ l֖⁠wò ţ̇wòʻáֽh׃"],[4,9,"וַ⁠נִּתְפַּלֵּ֖ל אֶל־אֱלֹהֵ֑י⁠נוּ וַ⁠נַּעֲמִ֨יד מִשְׁמָ֧ר עֲלֵי⁠הֶ֛ם יוֹמָ֥ם וָ⁠לַ֖יְלָה מִ⁠פְּנֵי⁠הֶֽם׃","wa⁠ni̇ţĕpȧlé֖̇l ʼel-ʼèlòhé֑y⁠nẇ wa⁠nȧʻàmi֨yd mişĕ̌má֧r ʻàléy⁠he֛m ywòmá֥m wá⁠la֖yĕláh mi⁠pĕ̇néy⁠heֽm׃"],[4,10,"וַ⁠יֹּ֣אמֶר יְהוּדָ֗ה כָּשַׁל֙ כֹּ֣חַ הַ⁠סַּבָּ֔ל וְ⁠הֶ⁠עָפָ֖ר הַרְבֵּ֑ה וַ⁠אֲנַ֨חְנוּ֙ לֹ֣א נוּכַ֔ל לִ⁠בְנ֖וֹת בַּ⁠חוֹמָֽה׃","wa⁠yò֣̇ʼmer yĕhẇdá֗h ká̇şǎl֙ kò֣̇ẖa ha⁠sȧbá̇֔l wĕ⁠he⁠ʻápá֖r harĕbé֑̇h wa⁠ʼàna֨ẖĕnẇ֙ lò֣ʼ nẇka֔l li⁠bĕn֖wòţ bȧ⁠ẖwòmáֽh׃"],[4,11,"וַ⁠יֹּאמְר֣וּ צָרֵ֗י⁠נוּ לֹ֤א יֵדְעוּ֙ וְ⁠לֹ֣א יִרְא֔וּ עַ֛ד אֲשֶׁר־נָב֥וֹא אֶל־תּוֹכָ֖⁠ם וַ⁠הֲרַגְנ֑וּ⁠ם וְ⁠הִשְׁבַּ֖תְנוּ אֶת־הַ⁠מְּלָאכָֽה׃","wa⁠yò̇ʼmĕr֣ẇ ẕáré֗y⁠nẇ lò֤ʼ yédĕʻẇ֙ wĕ⁠lò֣ʼ yirĕʼ֔ẇ ʻa֛d ʼàşěr-náb֥wòʼ ʼel-ţ̇wòká֖⁠m wa⁠hàragĕn֑ẇ⁠m wĕ⁠hişĕ̌bȧ֖ţĕnẇ ʼeţ-ha⁠mĕ̇láʼkáֽh׃"],[4,12,"וַֽ⁠יְהִי֙ כַּ⁠אֲשֶׁר־בָּ֣אוּ הַ⁠יְּהוּדִ֔ים הַ⁠יֹּשְׁבִ֖ים אֶצְלָ֑⁠ם וַ⁠יֹּ֤אמְרוּ לָ֨⁠נוּ֙ עֶ֣שֶׂר פְּעָמִ֔ים מִ⁠כָּל־הַ⁠מְּקֹמ֖וֹת אֲשֶׁר־תָּשׁ֥וּבוּ עָלֵֽי⁠נוּ׃","waֽ⁠yĕhiy֙ kȧ⁠ʼàşěr-bá֣̇ʼẇ ha⁠yĕ̇hẇdi֔ym ha⁠yò̇şĕ̌bi֖ym ʼeẕĕlá֑⁠m wa⁠yò֤̇ʼmĕrẇ lá֨⁠nẇ֙ ʻe֣şêr pĕ̇ʻámi֔ym mi⁠ká̇l-ha⁠mĕ̇qòm֖wòţ ʼàşěr-ţá̇ş֥̌ẇbẇ ʻáléֽy⁠nẇ׃"],[4,13,"וָֽ⁠אַעֲמִ֞יד מִֽ⁠תַּחְתִּיּ֧וֹת לַ⁠מָּק֛וֹם מֵ⁠אַחֲרֵ֥י לַ⁠חוֹמָ֖ה ב⁠צחחיים וָֽ⁠אַעֲמִ֤יד אֶת־הָ⁠עָם֙ לְ⁠מִשְׁפָּח֔וֹת עִם־חַרְבֹתֵי⁠הֶ֛ם רָמְחֵי⁠הֶ֖ם וְ⁠קַשְּׁתֹתֵי⁠הֶֽם׃","wáֽ⁠ʼaʻàmi֞yd miֽ⁠ţȧẖĕţi̇ẏ֧wòţ la⁠má̇q֛wòm mé⁠ʼaẖàré֥y la⁠ẖwòmá֖h b⁠ẕẖẖyym wáֽ⁠ʼaʻàmi֤yd ʼeţ-há⁠ʻám֙ lĕ⁠mişĕ̌pá̇ẖ֔wòţ ʻim-ẖarĕbòţéy⁠he֛m rámĕẖéy⁠he֖m wĕ⁠qaşĕ̇̌ţòţéy⁠heֽm׃"],[4,14,"וָ⁠אֵ֣רֶא וָ⁠אָק֗וּם וָ⁠אֹמַ֞ר אֶל־הַ⁠חֹרִ֤ים וְ⁠אֶל־הַ⁠סְּגָנִים֙ וְ⁠אֶל־יֶ֣תֶר הָ⁠עָ֔ם אַל־תִּֽירְא֖וּ מִ⁠פְּנֵי⁠הֶ֑ם אֶת־אֲדֹנָ֞⁠י הַ⁠גָּד֤וֹל וְ⁠הַ⁠נּוֹרָא֙ זְכֹ֔רוּ וְ⁠הִֽלָּחֲמ֗וּ עַל־אֲחֵי⁠כֶם֙ בְּנֵי⁠כֶ֣ם וּ⁠בְנֹתֵי⁠כֶ֔ם נְשֵׁי⁠כֶ֖ם וּ⁠בָתֵּי⁠כֶֽם׃פ","wá⁠ʼé֣reʼ wá⁠ʼáq֗ẇm wá⁠ʼòma֞r ʼel-ha⁠ẖòri֤ym wĕ⁠ʼel-ha⁠sĕ̇gániym֙ wĕ⁠ʼel-ye֣ţer há⁠ʻá֔m ʼal-ţiֽ̇yrĕʼ֖ẇ mi⁠pĕ̇néy⁠he֑m ʼeţ-ʼàdòná֞⁠y ha⁠gá̇d֤wòl wĕ⁠ha⁠ṅwòráʼ֙ zĕkò֔rẇ wĕ⁠hiֽlá̇ẖàm֗ẇ ʻal-ʼàẖéy⁠kem֙ bĕ̇néy⁠ke֣m ẇ⁠bĕnòţéy⁠ke֔m nĕşé̌y⁠ke֖m ẇ⁠báţé̇y⁠keֽm׃p"],[4,15,"וַ⁠יְהִ֞י כַּֽ⁠אֲשֶׁר־שָׁמְע֤וּ אוֹיְבֵ֨י⁠נוּ֙ כִּי־נ֣וֹדַֽע לָ֔⁠נוּ וַ⁠יָּ֥פֶר הָ⁠אֱלֹהִ֖ים אֶת־עֲצָתָ֑⁠ם ו⁠נשוב כֻּלָּ֨⁠נוּ֙ אֶל־הַ֣⁠חוֹמָ֔ה אִ֖ישׁ אֶל־מְלַאכְתּֽ⁠וֹ׃","wa⁠yĕhi֞y kȧֽ⁠ʼàşěr-şá̌mĕʻ֤ẇ ʼwòyĕbé֨y⁠nẇ֙ ki̇y-n֣wòdaֽʻ lá֔⁠nẇ wa⁠yá֥̇per há⁠ʼèlòhi֖ym ʼeţ-ʻàẕáţá֑⁠m w⁠nşwb ku̇lá̇֨⁠nẇ֙ ʼel-ha֣⁠ẖwòmá֔h ʼi֖yş̌ ʼel-mĕlaʼkĕţֽ̇⁠wò׃"],[4,16,"וַ⁠יְהִ֣י ׀ מִן־הַ⁠יּ֣וֹם הַ⁠ה֗וּא חֲצִ֣י נְעָרַ⁠י֮ עֹשִׂ֣ים בַּ⁠מְּלָאכָה֒ וְ⁠חֶצְיָ֗⁠ם מַחֲזִיקִים֙ וְ⁠הָ⁠רְמָחִ֣ים הַ⁠מָּגִנִּ֔ים וְ⁠הַ⁠קְּשָׁת֖וֹת וְ⁠הַ⁠שִּׁרְיֹנִ֑ים וְ⁠הַ֨⁠שָּׂרִ֔ים אַחֲרֵ֖י כָּל־בֵּ֥ית יְהוּדָֽה׃","wa⁠yĕhi֣y ׀ min-ha⁠ẏ֣wòm ha⁠h֗ẇʼ ẖàẕi֣y nĕʻára⁠y֮ ʻòşî֣ym bȧ⁠mĕ̇láʼkáh֒ wĕ⁠ẖeẕĕyá֗⁠m maẖàziyqiym֙ wĕ⁠há⁠rĕmáẖi֣ym ha⁠má̇gini̇֔ym wĕ⁠ha⁠qĕ̇şá̌ţ֖wòţ wĕ⁠ha⁠şi̇̌rĕyòni֑ym wĕ⁠ha֨⁠şá̇̂ri֔ym ʼaẖàré֖y ká̇l-bé֥̇yţ yĕhẇdáֽh׃"],[4,17,"הַ⁠בּוֹנִ֧ים בַּ⁠חוֹמָ֛ה וְ⁠הַ⁠נֹּשְׂאִ֥ים בַּ⁠סֶּ֖בֶל עֹמְשִׂ֑ים בְּ⁠אַחַ֤ת יָד⁠וֹ֙ עֹשֶׂ֣ה בַ⁠מְּלָאכָ֔ה וְ⁠אַחַ֖ת מַחֲזֶ֥קֶת הַ⁠שָּֽׁלַח׃","ha⁠ḃwòni֧ym bȧ⁠ẖwòmá֛h wĕ⁠ha⁠nò̇şĕ̂ʼi֥ym bȧ⁠sė֖bel ʻòmĕşî֑ym bĕ̇⁠ʼaẖa֤ţ yád⁠wò֙ ʻòşê֣h ba⁠mĕ̇láʼká֔h wĕ⁠ʼaẖa֖ţ maẖàze֥qeţ ha⁠şáֽ̇̌laẖ׃"],[4,18,"וְ⁠הַ֨⁠בּוֹנִ֔ים אִ֥ישׁ חַרְבּ֛⁠וֹ אֲסוּרִ֥ים עַל־מָתְנָ֖י⁠ו וּ⁠בוֹנִ֑ים וְ⁠הַ⁠תּוֹקֵ֥עַ בַּ⁠שּׁוֹפָ֖ר אֶצְלִֽ⁠י׃","wĕ⁠ha֨⁠ḃwòni֔ym ʼi֥yş̌ ẖarĕḃ֛⁠wò ʼàsẇri֥ym ʻal-máţĕná֖y⁠w ẇ⁠bwòni֑ym wĕ⁠ha⁠ţ̇wòqé֥ʻa bȧ⁠ş̇̌wòpá֖r ʼeẕĕliֽ⁠y׃"],[4,19,"וָ⁠אֹמַ֞ר אֶל־הַ⁠חֹרִ֤ים וְ⁠אֶל־הַ⁠סְּגָנִים֙ וְ⁠אֶל־יֶ֣תֶר הָ⁠עָ֔ם הַ⁠מְּלָאכָ֥ה הַרְבֵּ֖ה וּ⁠רְחָבָ֑ה וַ⁠אֲנַ֗חְנוּ נִפְרָדִים֙ עַל־הַ֣⁠חוֹמָ֔ה רְחוֹקִ֖ים אִ֥ישׁ מֵ⁠אָחִֽי⁠ו׃","wá⁠ʼòma֞r ʼel-ha⁠ẖòri֤ym wĕ⁠ʼel-ha⁠sĕ̇gániym֙ wĕ⁠ʼel-ye֣ţer há⁠ʻá֔m ha⁠mĕ̇láʼká֥h harĕbé֖̇h ẇ⁠rĕẖábá֑h wa⁠ʼàna֗ẖĕnẇ nipĕrádiym֙ ʻal-ha֣⁠ẖwòmá֔h rĕẖwòqi֖ym ʼi֥yş̌ mé⁠ʼáẖiֽy⁠w׃"],[4,20,"בִּ⁠מְק֗וֹם אֲשֶׁ֤ר תִּשְׁמְעוּ֙ אֶת־ק֣וֹל הַ⁠שּׁוֹפָ֔ר שָׁ֖מָּ⁠ה תִּקָּבְצ֣וּ אֵלֵ֑י⁠נוּ אֱלֹהֵ֖י⁠נוּ יִלָּ֥חֶם לָֽ⁠נוּ׃","bi̇⁠mĕq֗wòm ʼàşě֤r ţi̇şĕ̌mĕʻẇ֙ ʼeţ-q֣wòl ha⁠ş̇̌wòpá֔r şá֖̌má̇⁠h ţi̇qá̇bĕẕ֣ẇ ʼélé֑y⁠nẇ ʼèlòhé֖y⁠nẇ yilá֥̇ẖem láֽ⁠nẇ׃"],[4,21,"וַ⁠אֲנַ֖חְנוּ עֹשִׂ֣ים בַּ⁠מְּלָאכָ֑ה וְ⁠חֶצְיָ֗⁠ם מַחֲזִיקִים֙ בָּֽ⁠רְמָחִ֔ים מֵ⁠עֲל֣וֹת הַ⁠שַּׁ֔חַר עַ֖ד צֵ֥את הַ⁠כּוֹכָבִֽים׃","wa⁠ʼàna֖ẖĕnẇ ʻòşî֣ym bȧ⁠mĕ̇láʼká֑h wĕ⁠ẖeẕĕyá֗⁠m maẖàziyqiym֙ báֽ̇⁠rĕmáẖi֔ym mé⁠ʻàl֣wòţ ha⁠şȧ̌֔ẖar ʻa֖d ẕé֥ʼţ ha⁠k̇wòkábiֽym׃"],[4,22,"גַּ֣ם בָּ⁠עֵ֤ת הַ⁠הִיא֙ אָמַ֣רְתִּי לָ⁠עָ֔ם אִ֣ישׁ וְ⁠נַעֲר֔⁠וֹ יָלִ֖ינוּ בְּ⁠ת֣וֹךְ יְרוּשָׁלִָ֑ם וְ⁠הָֽיוּ־לָ֧⁠נוּ הַ⁠לַּ֛יְלָה מִשְׁמָ֖ר וְ⁠הַ⁠יּ֥וֹם מְלָאכָֽה׃","gȧ֣m bá̇⁠ʻé֤ţ ha⁠hiyʼ֙ ʼáma֣rĕţi̇y lá⁠ʻá֔m ʼi֣yş̌ wĕ⁠naʻàr֔⁠wò yáli֖ynẇ bĕ̇⁠ţ֣wòkĕ yĕrẇşá̌liá֑m wĕ⁠háֽyẇ-lá֧⁠nẇ ha⁠lȧ֛yĕláh mişĕ̌má֖r wĕ⁠ha⁠ẏ֥wòm mĕláʼkáֽh׃"],[4,23,"וְ⁠אֵ֨ין אֲנִ֜י וְ⁠אַחַ֣⁠י וּ⁠נְעָרַ֗⁠י וְ⁠אַנְשֵׁ֤י הַ⁠מִּשְׁמָר֙ אֲשֶׁ֣ר אַחֲרַ֔⁠י אֵין־אֲנַ֥חְנוּ פֹשְׁטִ֖ים בְּגָדֵ֑י⁠נוּ אִ֖ישׁ שִׁלְח֥⁠וֹ הַ⁠מָּֽיִם׃ס","wĕ⁠ʼé֨yn ʼàni֜y wĕ⁠ʼaẖa֣⁠y ẇ⁠nĕʻára֗⁠y wĕ⁠ʼanĕşé֤̌y ha⁠mi̇şĕ̌már֙ ʼàşě֣r ʼaẖàra֔⁠y ʼéyn-ʼàna֥ẖĕnẇ pòşĕ̌ti֖ym bĕ̇gádé֑y⁠nẇ ʼi֖yş̌ şǐlĕẖ֥⁠wò ha⁠máֽ̇yim׃s"],[5,1,"וַ⁠תְּהִ֨י צַעֲקַ֥ת הָ⁠עָ֛ם וּ⁠נְשֵׁי⁠הֶ֖ם גְּדוֹלָ֑ה אֶל־אֲחֵי⁠הֶ֖ם הַ⁠יְּהוּדִֽים׃","wa⁠ţĕ̇hi֨y ẕaʻàqa֥ţ há⁠ʻá֛m ẇ⁠nĕşé̌y⁠he֖m gĕ̇dwòlá֑h ʼel-ʼàẖéy⁠he֖m ha⁠yĕ̇hẇdiֽym׃"],[5,2,"וְ⁠יֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים בָּנֵ֥י⁠נוּ וּ⁠בְנֹתֵ֖י⁠נוּ אֲנַ֣חְנוּ רַבִּ֑ים וְ⁠נִקְחָ֥ה דָגָ֖ן וְ⁠נֹאכְלָ֥ה וְ⁠נִחְיֶֽה׃","wĕ⁠yéş̌֙ ʼàşě֣r ʼòmĕri֔ym bá̇né֥y⁠nẇ ẇ⁠bĕnòţé֖y⁠nẇ ʼàna֣ẖĕnẇ rabi֑̇ym wĕ⁠niqĕẖá֥h dágá֖n wĕ⁠nòʼkĕlá֥h wĕ⁠niẖĕyeֽh׃"],[5,3,"וְ⁠יֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים שְׂדֹתֵ֛י⁠נוּ וּ⁠כְרָמֵ֥י⁠נוּ וּ⁠בָתֵּ֖י⁠נוּ אֲנַ֣חְנוּ עֹרְבִ֑ים וְ⁠נִקְחָ֥ה דָגָ֖ן בָּ⁠רָעָֽב׃","wĕ⁠yéş̌֙ ʼàşě֣r ʼòmĕri֔ym şĕ̂dòţé֛y⁠nẇ ẇ⁠kĕrámé֥y⁠nẇ ẇ⁠báţé֖̇y⁠nẇ ʼàna֣ẖĕnẇ ʻòrĕbi֑ym wĕ⁠niqĕẖá֥h dágá֖n bá̇⁠ráʻáֽb׃"],[5,4,"וְ⁠יֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים לָוִ֥ינוּ כֶ֖סֶף לְ⁠מִדַּ֣ת הַ⁠מֶּ֑לֶךְ שְׂדֹתֵ֖י⁠נוּ וּ⁠כְרָמֵֽי⁠נוּ׃","wĕ⁠yéş̌֙ ʼàşě֣r ʼòmĕri֔ym láwi֥ynẇ ke֖sep lĕ⁠midȧ֣ţ ha⁠mė֑lekĕ şĕ̂dòţé֖y⁠nẇ ẇ⁠kĕráméֽy⁠nẇ׃"],[5,5,"וְ⁠עַתָּ֗ה כִּ⁠בְשַׂ֤ר אַחֵ֨י⁠נוּ֙ בְּשָׂרֵ֔⁠נוּ כִּ⁠בְנֵי⁠הֶ֖ם בָּנֵ֑י⁠נוּ וְ⁠הִנֵּ֣ה אֲנַ֣חְנוּ כֹ֠בְשִׁים אֶת־בָּנֵ֨י⁠נוּ וְ⁠אֶת־בְּנֹתֵ֜י⁠נוּ לַ⁠עֲבָדִ֗ים וְ⁠יֵ֨שׁ מִ⁠בְּנֹתֵ֤י⁠נוּ נִכְבָּשׁוֹת֙ וְ⁠אֵ֣ין לְ⁠אֵ֣ל יָדֵ֔⁠נוּ וּ⁠שְׂדֹתֵ֥י⁠נוּ וּ⁠כְרָמֵ֖י⁠נוּ לַ⁠אֲחֵרִֽים׃","wĕ⁠ʻaţá̇֗h ki̇⁠bĕşâ֤r ʼaẖé֨y⁠nẇ֙ bĕ̇şá̂ré֔⁠nẇ ki̇⁠bĕnéy⁠he֖m bá̇né֑y⁠nẇ wĕ⁠hiné֣̇h ʼàna֣ẖĕnẇ kò֠bĕşǐym ʼeţ-bá̇né֨y⁠nẇ wĕ⁠ʼeţ-bĕ̇nòţé֜y⁠nẇ la⁠ʻàbádi֗ym wĕ⁠yé֨ş̌ mi⁠bĕ̇nòţé֤y⁠nẇ nikĕbá̇ş̌wòţ֙ wĕ⁠ʼé֣yn lĕ⁠ʼé֣l yádé֔⁠nẇ ẇ⁠şĕ̂dòţé֥y⁠nẇ ẇ⁠kĕrámé֖y⁠nẇ la⁠ʼàẖériֽym׃"],[5,6,"וַ⁠יִּ֥חַר לִ֖⁠י מְאֹ֑ד כַּ⁠אֲשֶׁ֤ר שָׁמַ֨עְתִּי֙ אֶת־זַֽעֲקָתָ֔⁠ם וְ⁠אֵ֖ת הַ⁠דְּבָרִ֥ים הָ⁠אֵֽלֶּה׃","wa⁠yi֥̇ẖar li֖⁠y mĕʼò֑d kȧ⁠ʼàşě֤r şá̌ma֨ʻĕţi̇y֙ ʼeţ-zaֽʻàqáţá֔⁠m wĕ⁠ʼé֖ţ ha⁠dĕ̇bári֥ym há⁠ʼéֽlėh׃"],[5,7,"וַ⁠יִּמָּלֵ֨ךְ לִבִּ֜⁠י עָלַ֗⁠י וָ⁠אָרִ֨יבָ⁠ה֙ אֶת־הַ⁠חֹרִ֣ים וְ⁠אֶת־הַ⁠סְּגָנִ֔ים וָ⁠אֹמְרָ֣⁠ה לָ⁠הֶ֔ם מַשָּׁ֥א אִישׁ־בְּ⁠אָחִ֖י⁠ו אַתֶּ֣ם נשאים וָ⁠אֶתֵּ֥ן עֲלֵי⁠הֶ֖ם קְהִלָּ֥ה גְדוֹלָֽה׃","wa⁠yi̇má̇lé֨kĕ libi̇֜⁠y ʻála֗⁠y wá⁠ʼári֨ybá⁠h֙ ʼeţ-ha⁠ẖòri֣ym wĕ⁠ʼeţ-ha⁠sĕ̇gáni֔ym wá⁠ʼòmĕrá֣⁠h lá⁠he֔m maşá֥̇̌ʼ ʼiyş̌-bĕ̇⁠ʼáẖi֖y⁠w ʼaţė֣m nşʼym wá⁠ʼeţé֥̇n ʻàléy⁠he֖m qĕhilá֥̇h gĕdwòláֽh׃"],[5,8,"וָ⁠אֹמְרָ֣⁠ה לָ⁠הֶ֗ם אֲנַ֣חְנוּ קָ֠נִינוּ אֶת־אַחֵ֨י⁠נוּ הַ⁠יְּהוּדִ֜ים הַ⁠נִּמְכָּרִ֤ים לַ⁠גּוֹיִם֙ כְּ⁠דֵ֣י בָ֔⁠נוּ וְ⁠גַם־אַתֶּ֛ם תִּמְכְּר֥וּ אֶת־אֲחֵי⁠כֶ֖ם וְ⁠נִמְכְּרוּ־לָ֑⁠נוּ וַֽ⁠יַּחֲרִ֔ישׁוּ וְ⁠לֹ֥א מָצְא֖וּ דָּבָֽר׃ס","wá⁠ʼòmĕrá֣⁠h lá⁠he֗m ʼàna֣ẖĕnẇ qá֠niynẇ ʼeţ-ʼaẖé֨y⁠nẇ ha⁠yĕ̇hẇdi֜ym ha⁠ni̇mĕká̇ri֤ym la⁠ġwòyim֙ kĕ̇⁠dé֣y bá֔⁠nẇ wĕ⁠gam-ʼaţė֛m ţi̇mĕkĕ̇r֥ẇ ʼeţ-ʼàẖéy⁠ke֖m wĕ⁠nimĕkĕ̇rẇ-lá֑⁠nẇ wֽa⁠yȧẖàri֔yş̌ẇ wĕ⁠lò֥ʼ máẕĕʼ֖ẇ dá̇báֽr׃s"],[5,9,"ו⁠יאמר לֹא־ט֥וֹב הַ⁠דָּבָ֖ר אֲשֶׁר־אַתֶּ֣ם עֹשִׂ֑ים הֲ⁠ל֞וֹא בְּ⁠יִרְאַ֤ת אֱלֹהֵ֨י⁠נוּ֙ תֵּלֵ֔כוּ מֵ⁠חֶרְפַּ֖ת הַ⁠גּוֹיִ֥ם אוֹיְבֵֽי⁠נוּ׃","w⁠yʼmr lòʼ-t֥wòb ha⁠dá̇bá֖r ʼàşěr-ʼaţė֣m ʻòşî֑ym hà⁠l֞wòʼ bĕ̇⁠yirĕʼa֤ţ ʼèlòhé֨y⁠nẇ֙ ţé̇lé֔kẇ mé⁠ẖerĕpȧ֖ţ ha⁠ġwòyi֥m ʼwòyĕbéֽy⁠nẇ׃"],[5,10,"וְ⁠גַם־אֲנִי֙ אַחַ֣⁠י וּ⁠נְעָרַ֔⁠י נֹשִׁ֥ים בָּ⁠הֶ֖ם כֶּ֣סֶף וְ⁠דָגָ֑ן נַֽעַזְבָה־נָּ֖א אֶת־הַ⁠מַּשָּׁ֥א הַ⁠זֶּֽה׃","wĕ⁠gam-ʼàniy֙ ʼaẖa֣⁠y ẇ⁠nĕʻára֔⁠y nòşǐ֥ym bá̇⁠he֖m kė֣sep wĕ⁠dágá֑n naֽʻazĕbáh-ná֖̇ʼ ʼeţ-ha⁠mȧşá֥̇̌ʼ ha⁠zėֽh׃"],[5,11,"הָשִׁיבוּ֩ נָ֨א לָ⁠הֶ֜ם כְּ⁠הַ⁠יּ֗וֹם שְׂדֹתֵי⁠הֶ֛ם כַּרְמֵי⁠הֶ֥ם זֵיתֵי⁠הֶ֖ם וּ⁠בָתֵּי⁠הֶ֑ם וּ⁠מְאַ֨ת הַ⁠כֶּ֤סֶף וְ⁠הַ⁠דָּגָן֙ הַ⁠תִּיר֣וֹשׁ וְ⁠הַ⁠יִּצְהָ֔ר אֲשֶׁ֥ר אַתֶּ֖ם נֹשִׁ֥ים בָּ⁠הֶֽם׃","háşǐybẇ֩ ná֨ʼ lá⁠he֜m kĕ̇⁠ha⁠ẏ֗wòm şĕ̂dòţéy⁠he֛m kȧrĕméy⁠he֥m zéyţéy⁠he֖m ẇ⁠báţé̇y⁠he֑m ẇ⁠mĕʼa֨ţ ha⁠kė֤sep wĕ⁠ha⁠dá̇gán֙ ha⁠ţi̇yr֣wòş̌ wĕ⁠ha⁠yi̇ẕĕhá֔r ʼàşě֥r ʼaţė֖m nòşǐ֥ym bá̇⁠heֽm׃"],[5,12,"וַ⁠יֹּאמְר֣וּ נָשִׁ֗יב וּ⁠מֵ⁠הֶם֙ לֹ֣א נְבַקֵּ֔שׁ כֵּ֣ן נַעֲשֶׂ֔ה כַּ⁠אֲשֶׁ֖ר אַתָּ֣ה אוֹמֵ֑ר וָ⁠אֶקְרָא֙ אֶת־הַ⁠כֹּ֣הֲנִ֔ים וָֽ⁠אַשְׁבִּיעֵ֔⁠ם לַ⁠עֲשׂ֖וֹת כַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yò̇ʼmĕr֣ẇ náşǐ֗yb ẇ⁠mé⁠hem֙ lò֣ʼ nĕbaqé̇֔ş̌ ké֣̇n naʻàşê֔h kȧ⁠ʼàşě֖r ʼaţá֣̇h ʼwòmé֑r wá⁠ʼeqĕráʼ֙ ʼeţ-ha⁠kò֣̇hàni֔ym wáֽ⁠ʼaşĕ̌bi̇yʻé֔⁠m la⁠ʻàş֖̂wòţ kȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[5,13,"גַּם־חָצְנִ֣⁠י נָעַ֗רְתִּי וָֽ⁠אֹמְרָ֡⁠ה כָּ֣כָה יְנַעֵ֪ר הָֽ⁠אֱלֹהִ֟ים אֶת־כָּל־הָ⁠אִישׁ֩ אֲשֶׁ֨ר לֹֽא־יָקִ֜ים אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה מִ⁠בֵּית⁠וֹ֙ וּ⁠מִ֣⁠יגִיע֔⁠וֹ וְ⁠כָ֛כָה יִהְיֶ֥ה נָע֖וּר וָ⁠רֵ֑ק וַ⁠יֹּאמְר֨וּ כָֽל־הַ⁠קָּהָ֜ל אָמֵ֗ן וַֽ⁠יְהַלְלוּ֙ אֶת־יְהוָ֔ה וַ⁠יַּ֥עַשׂ הָ⁠עָ֖ם כַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","gȧm-ẖáẕĕni֣⁠y náʻa֗rĕţi̇y wáֽ⁠ʼòmĕrá֡⁠h ká֣̇káh yĕnaʻé֪r háֽ⁠ʼèlòhi֟ym ʼeţ-ká̇l-há⁠ʼiyş̌֩ ʼàşě֨r lòֽʼ-yáqi֜ym ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h mi⁠bé̇yţ⁠wò֙ ẇ⁠mi֣⁠ygiyʻ֔⁠wò wĕ⁠ká֛káh yihĕye֥h náʻ֖ẇr wá⁠ré֑q wa⁠yò̇ʼmĕr֨ẇ káֽl-ha⁠qá̇há֜l ʼámé֗n waֽ⁠yĕhalĕlẇ֙ ʼeţ-yĕhwá֔h wa⁠yȧ֥ʻaş̂ há⁠ʻá֖m kȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[5,14,"גַּ֞ם מִ⁠יּ֣וֹם ׀ אֲשֶׁר־צִוָּ֣ה אֹתִ֗⁠י לִ⁠הְי֣וֹת פֶּחָ⁠ם֮ בְּ⁠אֶ֣רֶץ יְהוּדָה֒ מִ⁠שְּׁנַ֣ת עֶשְׂרִ֗ים וְ֠⁠עַד שְׁנַ֨ת שְׁלֹשִׁ֤ים וּ⁠שְׁתַּ֨יִם֙ לְ⁠אַרְתַּחְשַׁ֣סְתְּא הַ⁠מֶּ֔לֶךְ שָׁנִ֖ים שְׁתֵּ֣ים עֶשְׂרֵ֑ה אֲנִ֣י וְ⁠אַחַ֔⁠י לֶ֥חֶם הַ⁠פֶּ֖חָה לֹ֥א אָכַֽלְתִּי׃","gȧ֞m mi⁠ẏ֣wòm ׀ ʼàşěr-ẕiwá֣̇h ʼòţi֗⁠y li⁠hĕy֣wòţ pėẖá⁠m֮ bĕ̇⁠ʼe֣reẕ yĕhẇdáh֒ mi⁠şĕ̇̌na֣ţ ʻeşĕ̂ri֗ym wĕ֠⁠ʻad şĕ̌na֨ţ şĕ̌lòşǐ֤ym ẇ⁠şĕ̌ţȧ֨yim֙ lĕ⁠ʼarĕţȧẖĕşǎ֣sĕţĕ̇ʼ ha⁠mė֔lekĕ şá̌ni֖ym şĕ̌ţé֣̇ym ʻeşĕ̂ré֑h ʼàni֣y wĕ⁠ʼaẖa֔⁠y le֥ẖem ha⁠pė֖ẖáh lò֥ʼ ʼákaֽlĕţi̇y׃"],[5,15,"וְ⁠הַ⁠פַּחוֹת֩ הָ⁠רִאשֹׁנִ֨ים אֲשֶׁר־לְ⁠פָנַ֜⁠י הִכְבִּ֣ידוּ עַל־הָ⁠עָ֗ם וַ⁠יִּקְח֨וּ מֵ⁠הֶ֜ם בְּ⁠לֶ֤חֶם וָ⁠יַ֨יִן֙ אַחַר֙ כֶּֽסֶף־שְׁקָלִ֣ים אַרְבָּעִ֔ים גַּ֥ם נַעֲרֵי⁠הֶ֖ם שָׁלְט֣וּ עַל־הָ⁠עָ֑ם וַ⁠אֲנִי֙ לֹא־עָשִׂ֣יתִי כֵ֔ן מִ⁠פְּנֵ֖י יִרְאַ֥ת אֱלֹהִֽים׃","wĕ⁠ha⁠pȧẖwòţ֩ há⁠riʼşò̌ni֨ym ʼàşěr-lĕ⁠pána֜⁠y hikĕbi֣̇ydẇ ʻal-há⁠ʻá֗m wa⁠yi̇qĕẖ֨ẇ mé⁠he֜m bĕ̇⁠le֤ẖem wá⁠ya֨yin֙ ʼaẖar֙ kėֽsep-şĕ̌qáli֣ym ʼarĕbá̇ʻi֔ym gȧ֥m naʻàréy⁠he֖m şá̌lĕt֣ẇ ʻal-há⁠ʻá֑m wa⁠ʼàniy֙ lòʼ-ʻáşî֣yţiy ké֔n mi⁠pĕ̇né֖y yirĕʼa֥ţ ʼèlòhiֽym׃"],[5,16,"וְ֠⁠גַם בִּ⁠מְלֶ֜אכֶת הַ⁠חוֹמָ֤ה הַ⁠זֹּאת֙ הֶחֱזַ֔קְתִּי וְ⁠שָׂדֶ֖ה לֹ֣א קָנִ֑ינוּ וְ⁠כָל־נְעָרַ֔⁠י קְבוּצִ֥ים שָׁ֖ם עַל־הַ⁠מְּלָאכָֽה׃","wĕ֠⁠gam bi̇⁠mĕle֜ʼkeţ ha⁠ẖwòmá֤h ha⁠zò̇ʼţ֙ heẖèza֔qĕţi̇y wĕ⁠şá̂de֖h lò֣ʼ qáni֑ynẇ wĕ⁠kál-nĕʻára֔⁠y qĕbẇẕi֥ym şá֖̌m ʻal-ha⁠mĕ̇láʼkáֽh׃"],[5,17,"וְ⁠הַ⁠יְּהוּדִ֨ים וְ⁠הַ⁠סְּגָנִ֜ים מֵאָ֧ה וַ⁠חֲמִשִּׁ֣ים אִ֗ישׁ וְ⁠הַ⁠בָּאִ֥ים אֵלֵ֛י⁠נוּ מִן־הַ⁠גּוֹיִ֥ם אֲשֶׁר־סְבִיבֹתֵ֖י⁠נוּ עַל־שֻׁלְחָנִֽ⁠י׃","wĕ⁠ha⁠yĕ̇hẇdi֨ym wĕ⁠ha⁠sĕ̇gáni֜ym méʼá֧h wa⁠ẖàmişi֣̇̌ym ʼi֗yş̌ wĕ⁠ha⁠bá̇ʼi֥ym ʼélé֛y⁠nẇ min-ha⁠ġwòyi֥m ʼàşěr-sĕbiybòţé֖y⁠nẇ ʻal-şǔlĕẖániֽ⁠y׃"],[5,18,"וַ⁠אֲשֶׁר֩ הָיָ֨ה נַעֲשֶׂ֜ה לְ⁠י֣וֹם אֶחָ֗ד שׁ֣וֹר אֶחָ֞ד צֹ֠אן שֵׁשׁ־בְּרֻר֤וֹת וְ⁠צִפֳּרִים֙ נַֽעֲשׂוּ־לִ֔⁠י וּ⁠בֵ֨ין עֲשֶׂ֧רֶת יָמִ֛ים בְּ⁠כָל־יַ֖יִן לְ⁠הַרְבֵּ֑ה וְ⁠עִם־זֶ֗ה לֶ֤חֶם הַ⁠פֶּחָה֙ לֹ֣א בִקַּ֔שְׁתִּי כִּֽי־כָֽבְדָ֥ה הָ⁠עֲבֹדָ֖ה עַל־הָ⁠עָ֥ם הַ⁠זֶּֽה׃","wa⁠ʼàşěr֩ háyá֨h naʻàşê֜h lĕ⁠y֣wòm ʼeẖá֗d ş֣̌wòr ʼeẖá֞d ẕò֠ʼn şé̌ş̌-bĕ̇rur֤wòţ wĕ⁠ẕipȯriym֙ naֽʻàş̂ẇ-li֔⁠y ẇ⁠bé֨yn ʻàşê֧reţ yámi֛ym bĕ̇⁠kál-ya֖yin lĕ⁠harĕbé֑̇h wĕ⁠ʻim-ze֗h le֤ẖem ha⁠pėẖáh֙ lò֣ʼ biqȧ֔şĕ̌ţi̇y kiֽ̇y-káֽbĕdá֥h há⁠ʻàbòdá֖h ʻal-há⁠ʻá֥m ha⁠zėֽh׃"],[5,19,"זָכְרָ⁠ה־לִּ֥⁠י אֱלֹהַ֖⁠י לְ⁠טוֹבָ֑ה כֹּ֥ל אֲשֶׁר־עָשִׂ֖יתִי עַל־הָ⁠עָ֥ם הַ⁠זֶּֽה׃פ","zákĕrá⁠h-li֥̇⁠y ʼèlòha֖⁠y lĕ⁠twòbá֑h kò֥̇l ʼàşěr-ʻáşî֖yţiy ʻal-há⁠ʻá֥m ha⁠zėֽh׃p"],[6,1,"וַ⁠יְהִ֣י כַ⁠אֲשֶׁ֣ר נִשְׁמַ֣ע לְ⁠סַנְבַלַּ֣ט וְ֠⁠טוֹבִיָּה וּ⁠לְ⁠גֶ֨שֶׁם הָֽ⁠עַרְבִ֜י וּ⁠לְ⁠יֶ֣תֶר אֹֽיְבֵ֗י⁠נוּ כִּ֤י בָנִ֨יתִי֙ אֶת־הַ֣⁠חוֹמָ֔ה וְ⁠לֹא־נ֥וֹתַר בָּ֖⁠הּ פָּ֑רֶץ גַּ֚ם עַד־הָ⁠עֵ֣ת הַ⁠הִ֔יא דְּלָת֖וֹת לֹא־הֶעֱמַ֥דְתִּי בַ⁠שְּׁעָרִֽים׃","wa⁠yĕhi֣y ka⁠ʼàşě֣r nişĕ̌ma֣ʻ lĕ⁠sanĕbalȧ֣t wĕ֠⁠twòbiyá̇h ẇ⁠lĕ⁠ge֨şěm háֽ⁠ʻarĕbi֜y ẇ⁠lĕ⁠ye֣ţer ʼòֽyĕbé֗y⁠nẇ ki֤̇y báni֨yţiy֙ ʼeţ-ha֣⁠ẖwòmá֔h wĕ⁠lòʼ-n֥wòţar bá֖̇⁠ḣ pá֑̇reẕ gȧ֚m ʻad-há⁠ʻé֣ţ ha⁠hi֔yʼ dĕ̇láţ֖wòţ lòʼ-heʻèma֥dĕţi̇y ba⁠şĕ̇̌ʻáriֽym׃"],[6,2,"וַ⁠יִּשְׁלַ֨ח סַנְבַלַּ֤ט וְ⁠גֶ֨שֶׁם֙ אֵלַ֣⁠י לֵ⁠אמֹ֔ר לְכָ֞⁠ה וְ⁠נִֽוָּעֲדָ֥ה יַחְדָּ֛ו בַּ⁠כְּפִירִ֖ים בְּ⁠בִקְעַ֣ת אוֹנ֑וֹ וְ⁠הֵ֨מָּה֙ חֹֽשְׁבִ֔ים לַ⁠עֲשׂ֥וֹת לִ֖⁠י רָעָֽה׃","wa⁠yi̇şĕ̌la֨ẖ sanĕbalȧ֤t wĕ⁠ge֨şěm֙ ʼéla֣⁠y lé⁠ʼmò֔r lĕká֞⁠h wĕ⁠niֽwá̇ʻàdá֥h yaẖĕdá֛̇w bȧ⁠kĕ̇piyri֖ym bĕ̇⁠biqĕʻa֣ţ ʼwòn֑wò wĕ⁠hé֨má̇h֙ ẖòֽşĕ̌bi֔ym la⁠ʻàş֥̂wòţ li֖⁠y ráʻáֽh׃"],[6,3,"וָ⁠אֶשְׁלְחָ֨⁠ה עֲלֵי⁠הֶ֤ם מַלְאָכִים֙ לֵ⁠אמֹ֔ר מְלָאכָ֤ה גְדוֹלָה֙ אֲנִ֣י עֹשֶׂ֔ה וְ⁠לֹ֥א אוּכַ֖ל לָ⁠רֶ֑דֶת לָ֣⁠מָּה תִשְׁבַּ֤ת הַ⁠מְּלָאכָה֙ כַּ⁠אֲשֶׁ֣ר אַרְפֶּ֔⁠הָ וְ⁠יָרַדְתִּ֖י אֲלֵי⁠כֶֽם׃","wá⁠ʼeşĕ̌lĕẖá֨⁠h ʻàléy⁠he֤m malĕʼákiym֙ lé⁠ʼmò֔r mĕláʼká֤h gĕdwòláh֙ ʼàni֣y ʻòşê֔h wĕ⁠lò֥ʼ ʼẇka֖l lá⁠re֑deţ lá֣⁠má̇h ţişĕ̌bȧ֤ţ ha⁠mĕ̇láʼkáh֙ kȧ⁠ʼàşě֣r ʼarĕpė֔⁠há wĕ⁠yáradĕţi֖̇y ʼàléy⁠keֽm׃"],[6,4,"וַ⁠יִּשְׁלְח֥וּ אֵלַ֛⁠י כַּ⁠דָּבָ֥ר הַ⁠זֶּ֖ה אַרְבַּ֣ע פְּעָמִ֑ים וָ⁠אָשִׁ֥יב אוֹתָ֖⁠ם כַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃ס","wa⁠yi̇şĕ̌lĕẖ֥ẇ ʼéla֛⁠y kȧ⁠dá̇bá֥r ha⁠zė֖h ʼarĕbȧ֣ʻ pĕ̇ʻámi֑ym wá⁠ʼáşǐ֥yb ʼwòţá֖⁠m kȧ⁠dá̇bá֥r ha⁠zėֽh׃s"],[6,5,"וַ⁠יִּשְׁלַח֩ אֵלַ֨⁠י סַנְבַלַּ֜ט כַּ⁠דָּבָ֥ר הַ⁠זֶּ֛ה פַּ֥עַם חֲמִישִׁ֖ית אֶֽת־נַעֲר֑⁠וֹ וְ⁠אִגֶּ֥רֶת פְּתוּחָ֖ה בְּ⁠יָדֽ⁠וֹ׃","wa⁠yi̇şĕ̌laẖ֩ ʼéla֨⁠y sanĕbalȧ֜t kȧ⁠dá̇bá֥r ha⁠zė֛h pȧ֥ʻam ẖàmiyşǐ֖yţ ʼeֽţ-naʻàr֑⁠wò wĕ⁠ʼigė֥reţ pĕ̇ţẇẖá֖h bĕ̇⁠yádֽ⁠wò׃"],[6,6,"כָּת֣וּב בָּ֗⁠הּ בַּ⁠גּוֹיִ֤ם נִשְׁמָע֙ וְ⁠גַשְׁמ֣וּ אֹמֵ֔ר אַתָּ֤ה וְ⁠הַ⁠יְּהוּדִים֙ חֹשְׁבִ֣ים לִ⁠מְר֔וֹד עַל־כֵּ֛ן אַתָּ֥ה בוֹנֶ֖ה הַ⁠חוֹמָ֑ה וְ⁠אַתָּ֗ה הֹוֶ֤ה לָ⁠הֶם֙ לְ⁠מֶ֔לֶךְ כַּ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","ká̇ţ֣ẇb bá̇֗⁠ḣ bȧ⁠ġwòyi֤m nişĕ̌máʻ֙ wĕ⁠gaşĕ̌m֣ẇ ʼòmé֔r ʼaţá֤̇h wĕ⁠ha⁠yĕ̇hẇdiym֙ ẖòşĕ̌bi֣ym li⁠mĕr֔wòd ʻal-ké֛̇n ʼaţá֥̇h bwòne֖h ha⁠ẖwòmá֑h wĕ⁠ʼaţá̇֗h hòwe֤h lá⁠hem֙ lĕ⁠me֔lekĕ kȧ⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[6,7,"וְ⁠גַם־נְבִיאִ֡ים הֶעֱמַ֣דְתָּ לִ⁠קְרֹא֩ עָלֶ֨י⁠ךָ בִֽ⁠ירוּשָׁלִַ֜ם לֵ⁠אמֹ֗ר מֶ֚לֶךְ בִּֽ⁠יהוּדָ֔ה וְ⁠עַתָּה֙ יִשָּׁמַ֣ע לַ⁠מֶּ֔לֶךְ כַּ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה וְ⁠עַתָּ֣ה לְכָ֔⁠ה וְ⁠נִֽוָּעֲצָ֖ה יַחְדָּֽו׃ס","wĕ⁠gam-nĕbiyʼi֡ym heʻèma֣dĕţá̇ li⁠qĕròʼ֩ ʻále֨y⁠ká biֽ⁠yrẇşá̌lia֜m lé⁠ʼmò֗r me֚lekĕ biֽ̇⁠yhẇdá֔h wĕ⁠ʻaţá̇h֙ yişá̇̌ma֣ʻ la⁠mė֔lekĕ kȧ⁠dĕ̇bári֣ym há⁠ʼé֑lėh wĕ⁠ʻaţá֣̇h lĕká֔⁠h wĕ⁠niֽwá̇ʻàẕá֖h yaẖĕdáֽ̇w׃s"],[6,8,"וָ⁠אֶשְׁלְחָ֤⁠ה אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר לֹ֤א נִֽהְיָה֙ כַּ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁ֖ר אַתָּ֣ה אוֹמֵ֑ר כִּ֥י מִֽ⁠לִּבְּ⁠ךָ֖ אַתָּ֥ה בוֹדָֽא⁠ם׃","wá⁠ʼeşĕ̌lĕẖá֤⁠h ʼéláy⁠w֙ lé⁠ʼmò֔r lò֤ʼ niֽhĕyáh֙ kȧ⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʼàşě֖r ʼaţá֣̇h ʼwòmé֑r ki֥̇y miֽ⁠li̇bĕ̇⁠ká֖ ʼaţá֥̇h bwòdáֽʼ⁠m׃"],[6,9,"כִּ֣י כֻלָּ֗⁠ם מְיָֽרְאִ֤ים אוֹתָ֨⁠נוּ֙ לֵ⁠אמֹ֔ר יִרְפּ֧וּ יְדֵי⁠הֶ֛ם מִן־הַ⁠מְּלָאכָ֖ה וְ⁠לֹ֣א תֵעָשֶׂ֑ה וְ⁠עַתָּ֖ה חַזֵּ֥ק אֶת־יָדָֽ⁠י׃","ki֣̇y kulá̇֗⁠m mĕyáֽrĕʼi֤ym ʼwòţá֨⁠nẇ֙ lé⁠ʼmò֔r yirĕṗ֧ẇ yĕdéy⁠he֛m min-ha⁠mĕ̇láʼká֖h wĕ⁠lò֣ʼ ţéʻáşê֑h wĕ⁠ʻaţá֖̇h ẖazé֥̇q ʼeţ-yádáֽ⁠y׃"],[6,10,"וַ⁠אֲנִי־בָ֗אתִי בֵּ֣ית שְֽׁמַֽעְיָ֧ה בֶן־דְּלָיָ֛ה בֶּן־מְהֵֽיטַבְאֵ֖ל וְ⁠ה֣וּא עָצ֑וּר וַ⁠יֹּ֡אמֶר נִוָּעֵד֩ אֶל־בֵּ֨ית הָ⁠אֱלֹהִ֜ים אֶל־תּ֣וֹךְ הַֽ⁠הֵיכָ֗ל וְ⁠נִסְגְּרָה֙ דַּלְת֣וֹת הַ⁠הֵיכָ֔ל כִּ֚י בָּאִ֣ים לְ⁠הָרְגֶ֔⁠ךָ וְ⁠לַ֖יְלָה בָּאִ֥ים לְ⁠הָרְגֶֽ⁠ךָ׃","wa⁠ʼàniy-bá֗ʼţiy bé֣̇yţ şĕֽ̌maֽʻĕyá֧h ben-dĕ̇láyá֛h bėn-mĕhéֽytabĕʼé֖l wĕ⁠h֣ẇʼ ʻáẕ֑ẇr wa⁠yò̇֡ʼmer niwá̇ʻéd֩ ʼel-bé̇֨yţ há⁠ʼèlòhi֜ym ʼel-ţ֣̇wòkĕ haֽ⁠héyká֗l wĕ⁠nisĕgĕ̇ráh֙ dȧlĕţ֣wòţ ha⁠héyká֔l ki֚̇y bá̇ʼi֣ym lĕ⁠hárĕge֔⁠ká wĕ⁠la֖yĕláh bá̇ʼi֥ym lĕ⁠hárĕgeֽ⁠ká׃"],[6,11,"וָ⁠אֹמְרָ֗⁠ה הַ⁠אִ֤ישׁ כָּמ֨וֹ⁠נִי֙ יִבְרָ֔ח וּ⁠מִ֥י כָמ֛וֹ⁠נִי אֲשֶׁר־יָב֥וֹא אֶל־הַ⁠הֵיכָ֖ל וָ⁠חָ֑י לֹ֖א אָבֽוֹא׃","wá⁠ʼòmĕrá֗⁠h ha⁠ʼi֤yş̌ ká̇m֨wò⁠niy֙ yibĕrá֔ẖ ẇ⁠mi֥y kám֛wò⁠niy ʼàşěr-yáb֥wòʼ ʼel-ha⁠héyká֖l wá⁠ẖá֑y lò֖ʼ ʼábֽwòʼ׃"],[6,12,"וָ⁠אַכִּ֕ירָ⁠ה וְ⁠הִנֵּ֥ה לֹֽא־אֱלֹהִ֖ים שְׁלָח֑⁠וֹ כִּ֤י הַ⁠נְּבוּאָה֙ דִּבֶּ֣ר עָלַ֔⁠י וְ⁠טוֹבִיָּ֥ה וְ⁠סַנְבַלַּ֖ט שְׂכָרֽ⁠וֹ׃","wá⁠ʼaki̇֕yrá⁠h wĕ⁠hiné֥̇h lòֽʼ-ʼèlòhi֖ym şĕ̌láẖ֑⁠wò ki֤̇y ha⁠nĕ̇bẇʼáh֙ di̇bė֣r ʻála֔⁠y wĕ⁠twòbiyá֥̇h wĕ⁠sanĕbalȧ֖t şĕ̂kárֽ⁠wò׃"],[6,13,"לְמַ֤עַן שָׂכוּר֙ ה֔וּא לְמַֽעַן־אִירָ֥א וְ⁠אֶֽעֱשֶׂה־כֵּ֖ן וְ⁠חָטָ֑אתִי וְ⁠הָיָ֤ה לָ⁠הֶם֙ לְ⁠שֵׁ֣ם רָ֔ע לְמַ֖עַן יְחָֽרְפֽוּ⁠נִי׃פ","lĕma֤ʻan şá̂kẇr֙ h֔ẇʼ lĕmaֽʻan-ʼiyrá֥ʼ wĕ⁠ʼeֽʻèşêh-ké֖̇n wĕ⁠ẖátá֑ʼţiy wĕ⁠háyá֤h lá⁠hem֙ lĕ⁠şé֣̌m rá֔ʻ lĕma֖ʻan yĕẖáֽrĕpֽẇ⁠niy׃p"],[6,14,"זָכְרָ֧⁠ה אֱלֹהַ֛⁠י לְ⁠טוֹבִיָּ֥ה וּ⁠לְ⁠סַנְבַלַּ֖ט כְּ⁠מַעֲשָׂ֣י⁠ו אֵ֑לֶּה וְ⁠גַ֨ם לְ⁠נוֹעַדְיָ֤ה הַ⁠נְּבִיאָה֙ וּ⁠לְ⁠יֶ֣תֶר הַ⁠נְּבִיאִ֔ים אֲשֶׁ֥ר הָי֖וּ מְיָֽרְאִ֥ים אוֹתִֽ⁠י׃","zákĕrá֧⁠h ʼèlòha֛⁠y lĕ⁠twòbiyá֥̇h ẇ⁠lĕ⁠sanĕbalȧ֖t kĕ̇⁠maʻàşá֣̂y⁠w ʼé֑lėh wĕ⁠ga֨m lĕ⁠nwòʻadĕyá֤h ha⁠nĕ̇biyʼáh֙ ẇ⁠lĕ⁠ye֣ţer ha⁠nĕ̇biyʼi֔ym ʼàşě֥r háy֖ẇ mĕyáֽrĕʼi֥ym ʼwòţiֽ⁠y׃"],[6,15,"וַ⁠תִּשְׁלַם֙ הַֽ⁠חוֹמָ֔ה בְּ⁠עֶשְׂרִ֥ים וַ⁠חֲמִשָּׁ֖ה לֶ⁠אֱל֑וּל לַ⁠חֲמִשִּׁ֥ים וּ⁠שְׁנַ֖יִם יֽוֹם׃פ","wa⁠ţi̇şĕ̌lam֙ haֽ⁠ẖwòmá֔h bĕ̇⁠ʻeşĕ̂ri֥ym wa⁠ẖàmişá֖̇̌h le⁠ʼèl֑ẇl la⁠ẖàmişi֥̇̌ym ẇ⁠şĕ̌na֖yim yֽwòm׃p"],[6,16,"וַ⁠יְהִ֗י כַּ⁠אֲשֶׁ֤ר שָֽׁמְעוּ֙ כָּל־א֣וֹיְבֵ֔י⁠נוּ וַ⁠יִּֽרְא֗וּ כָּל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר סְבִֽיבֹתֵ֔י⁠נוּ וַ⁠יִּפְּל֥וּ מְאֹ֖ד בְּ⁠עֵינֵי⁠הֶ֑ם וַ⁠יֵּ֣דְע֔וּ כִּ֚י מֵ⁠אֵ֣ת אֱלֹהֵ֔י⁠נוּ נֶעֶשְׂתָ֖ה הַ⁠מְּלָאכָ֥ה הַ⁠זֹּֽאת׃","wa⁠yĕhi֗y kȧ⁠ʼàşě֤r şáֽ̌mĕʻẇ֙ ká̇l-ʼ֣wòyĕbé֔y⁠nẇ wa⁠yiֽ̇rĕʼ֗ẇ ká̇l-ha⁠ġwòyim֙ ʼàşě֣r sĕbiֽybòţé֔y⁠nẇ wa⁠yi̇pĕ̇l֥ẇ mĕʼò֖d bĕ̇⁠ʻéynéy⁠he֑m wa⁠yé֣̇dĕʻ֔ẇ ki֚̇y mé⁠ʼé֣ţ ʼèlòhé֔y⁠nẇ neʻeşĕ̂ţá֖h ha⁠mĕ̇láʼká֥h ha⁠zòֽ̇ʼţ׃"],[6,17,"גַּ֣ם ׀ בַּ⁠יָּמִ֣ים הָ⁠הֵ֗ם מַרְבִּ֞ים חֹרֵ֤י יְהוּדָה֙ אִגְּרֹ֣תֵי⁠הֶ֔ם הוֹלְכ֖וֹת עַל־טוֹבִיָּ֑ה וַ⁠אֲשֶׁ֥ר לְ⁠טוֹבִיָּ֖ה בָּא֥וֹת אֲלֵי⁠הֶֽם׃","gȧ֣m ׀ bȧ⁠yá̇mi֣ym há⁠hé֗m marĕbi̇֞ym ẖòré֤y yĕhẇdáh֙ ʼigĕ̇rò֣ţéy⁠he֔m hwòlĕk֖wòţ ʻal-twòbiyá֑̇h wa⁠ʼàşě֥r lĕ⁠twòbiyá֖̇h bá̇ʼ֥wòţ ʼàléy⁠heֽm׃"],[6,18,"כִּי־רַבִּ֣ים בִּֽ⁠יהוּדָ֗ה בַּעֲלֵ֤י שְׁבוּעָה֙ ל֔⁠וֹ כִּי־חָתָ֥ן ה֖וּא לִ⁠שְׁכַנְיָ֣ה בֶן־אָרַ֑ח וִֽ⁠יהוֹחָנָ֣ן בְּנ֔⁠וֹ לָקַ֕ח אֶת־בַּת־מְשֻׁלָּ֖ם בֶּ֥ן בֶּֽרֶכְיָֽה׃","ki̇y-rabi֣̇ym biֽ̇⁠yhẇdá֗h bȧʻàlé֤y şĕ̌bẇʻáh֙ l֔⁠wò ki̇y-ẖáţá֥n h֖ẇʼ li⁠şĕ̌kanĕyá֣h ben-ʼára֑ẖ wiֽ⁠yhwòẖáná֣n bĕ̇n֔⁠wò láqa֕ẖ ʼeţ-bȧţ-mĕşǔlá֖̇m bė֥n bėֽrekĕyáֽh׃"],[6,19,"גַּ֣ם טוֹבֹתָ֗י⁠ו הָי֤וּ אֹמְרִים֙ לְ⁠פָנַ֔⁠י וּ⁠דְבָרַ֕⁠י הָי֥וּ מוֹצִיאִ֖ים ל֑⁠וֹ אִגְּר֛וֹת שָׁלַ֥ח טוֹבִיָּ֖ה לְ⁠יָֽרְאֵֽ⁠נִי׃","gȧ֣m twòbòţá֗y⁠w háy֤ẇ ʼòmĕriym֙ lĕ⁠pána֔⁠y ẇ⁠dĕbára֕⁠y háy֥ẇ mwòẕiyʼi֖ym l֑⁠wò ʼigĕ̇r֛wòţ şá̌la֥ẖ twòbiyá֖̇h lĕ⁠yáֽrĕʼéֽ⁠niy׃"],[7,1,"וַ⁠יְהִ֗י כַּ⁠אֲשֶׁ֤ר נִבְנְתָה֙ הַ⁠חוֹמָ֔ה וָ⁠אַעֲמִ֖יד הַ⁠דְּלָת֑וֹת וַ⁠יִּפָּֽקְד֛וּ הַ⁠שּׁוֹעֲרִ֥ים וְ⁠הַ⁠מְשֹׁרְרִ֖ים וְ⁠הַ⁠לְוִיִּֽם׃","wa⁠yĕhi֗y kȧ⁠ʼàşě֤r nibĕnĕţáh֙ ha⁠ẖwòmá֔h wá⁠ʼaʻàmi֖yd ha⁠dĕ̇láţ֑wòţ wa⁠yi̇páֽ̇qĕd֛ẇ ha⁠ş̇̌wòʻàri֥ym wĕ⁠ha⁠mĕşò̌rĕri֖ym wĕ⁠ha⁠lĕwiyiֽ̇m׃"],[7,2,"וָ⁠אֲצַוֶּ֞ה אֶת־חֲנָ֣נִי אָחִ֗⁠י וְ⁠אֶת־חֲנַנְיָ֛ה שַׂ֥ר הַ⁠בִּירָ֖ה עַל־יְרוּשָׁלִָ֑ם כִּי־הוּא֙ כְּ⁠אִ֣ישׁ אֱמֶ֔ת וְ⁠יָרֵ֥א אֶת־הָ⁠אֱלֹהִ֖ים מֵ⁠רַבִּֽים׃","wá⁠ʼàẕawė֞h ʼeţ-ẖàná֣niy ʼáẖi֗⁠y wĕ⁠ʼeţ-ẖànanĕyá֛h şâ֥r ha⁠bi̇yrá֖h ʻal-yĕrẇşá̌liá֑m ki̇y-hẇʼ֙ kĕ̇⁠ʼi֣yş̌ ʼème֔ţ wĕ⁠yáré֥ʼ ʼeţ-há⁠ʼèlòhi֖ym mé⁠rabiֽ̇ym׃"],[7,3,"ו⁠יאמר לָ⁠הֶ֗ם לֹ֣א יִפָּֽתְח֞וּ שַׁעֲרֵ֤י יְרוּשָׁלִַ֨ם֙ עַד־חֹ֣ם הַ⁠שֶּׁ֔מֶשׁ וְ⁠עַ֨ד הֵ֥ם עֹמְדִ֛ים יָגִ֥יפוּ הַ⁠דְּלָת֖וֹת וֶ⁠אֱחֹ֑זוּ וְ⁠הַעֲמֵ֗יד מִשְׁמְרוֹת֙ יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם אִ֚ישׁ בְּ⁠מִשְׁמָר֔⁠וֹ וְ⁠אִ֖ישׁ נֶ֥גֶד בֵּיתֽ⁠וֹ׃","w⁠yʼmr lá⁠he֗m lò֣ʼ yipáֽ̇ţĕẖ֞ẇ şǎʻàré֤y yĕrẇşá̌lia֨m֙ ʻad-ẖò֣m ha⁠şė̌֔meş̌ wĕ⁠ʻa֨d hé֥m ʻòmĕdi֛ym yági֥ypẇ ha⁠dĕ̇láţ֖wòţ we⁠ʼèẖò֑zẇ wĕ⁠haʻàmé֗yd mişĕ̌mĕrwòţ֙ yòşĕ̌bé֣y yĕrẇşá̌lia֔m ʼi֚yş̌ bĕ̇⁠mişĕ̌már֔⁠wò wĕ⁠ʼi֖yş̌ ne֥ged bé̇yţֽ⁠wò׃"],[7,4,"וְ⁠הָ⁠עִ֞יר רַחֲבַ֤ת יָדַ֨יִם֙ וּ⁠גְדוֹלָ֔ה וְ⁠הָ⁠עָ֥ם מְעַ֖ט בְּ⁠תוֹכָ֑⁠הּ וְ⁠אֵ֥ין בָּתִּ֖ים בְּנוּיִֽם׃","wĕ⁠há⁠ʻi֞yr raẖàba֤ţ yáda֨yim֙ ẇ⁠gĕdwòlá֔h wĕ⁠há⁠ʻá֥m mĕʻa֖t bĕ̇⁠ţwòká֑⁠ḣ wĕ⁠ʼé֥yn bá̇ţi֖̇ym bĕ̇nẇyiֽm׃"],[7,5,"וַ⁠יִּתֵּ֤ן אֱלֹהַ⁠י֙ אֶל־לִבִּ֔⁠י וָ⁠אֶקְבְּצָ֞⁠ה אֶת־הַ⁠חֹרִ֧ים וְ⁠אֶת־הַ⁠סְּגָנִ֛ים וְ⁠אֶת־הָ⁠עָ֖ם לְ⁠הִתְיַחֵ֑שׂ וָֽ⁠אֶמְצָ֗א סֵ֤פֶר הַ⁠יַּ֨חַשׂ֙ הָ⁠עוֹלִ֣ים בָּ⁠רִאשׁוֹנָ֔ה וָ⁠אֶמְצָ֖א כָּת֥וּב בּֽ⁠וֹ׃פ","wa⁠yi̇ţé֤̇n ʼèlòha⁠y֙ ʼel-libi̇֔⁠y wá⁠ʼeqĕbĕ̇ẕá֞⁠h ʼeţ-ha⁠ẖòri֧ym wĕ⁠ʼeţ-ha⁠sĕ̇gáni֛ym wĕ⁠ʼeţ-há⁠ʻá֖m lĕ⁠hiţĕyaẖé֑ş̂ wáֽ⁠ʼemĕẕá֗ʼ sé֤per ha⁠yȧ֨ẖaş̂֙ há⁠ʻwòli֣ym bá̇⁠riʼş̌wòná֔h wá⁠ʼemĕẕá֖ʼ ká̇ţ֥ẇb ḃֽ⁠wò׃p"],[7,6,"אֵ֣לֶּה ׀ בְּנֵ֣י הַ⁠מְּדִינָ֗ה הָ⁠עֹלִים֙ מִ⁠שְּׁבִ֣י הַ⁠גּוֹלָ֔ה אֲשֶׁ֣ר הֶגְלָ֔ה נְבוּכַדְנֶצַּ֖ר מֶ֣לֶךְ בָּבֶ֑ל וַ⁠יָּשׁ֧וּבוּ לִֽ⁠ירוּשָׁלִַ֛ם וְ⁠לִ⁠יהוּדָ֖ה אִ֥ישׁ לְ⁠עִירֽ⁠וֹ׃","ʼé֣lėh ׀ bĕ̇né֣y ha⁠mĕ̇diyná֗h há⁠ʻòliym֙ mi⁠şĕ̇̌bi֣y ha⁠ġwòlá֔h ʼàşě֣r hegĕlá֔h nĕbẇkadĕneẕȧ֖r me֣lekĕ bá̇be֑l wa⁠yá̇ş֧̌ẇbẇ liֽ⁠yrẇşá̌lia֛m wĕ⁠li⁠yhẇdá֖h ʼi֥yş̌ lĕ⁠ʻiyrֽ⁠wò׃"],[7,7,"הַ⁠בָּאִ֣ים עִם־זְרֻבָּבֶ֗ל יֵשׁ֡וּעַ נְחֶמְיָ֡ה עֲ֠זַרְיָה רַֽעַמְיָ֨ה נַחֲמָ֜נִי מָרְדֳּכַ֥י בִּלְשָׁ֛ן מִסְפֶּ֥רֶת בִּגְוַ֖י נְח֣וּם בַּעֲנָ֑ה מִסְפַּ֕ר אַנְשֵׁ֖י עַ֥ם יִשְׂרָאֵֽל׃ס","ha⁠bá̇ʼi֣ym ʻim-zĕrubá̇be֗l yéş̌֡ẇʻa nĕẖemĕyá֡h ʻà֠zarĕyáh raֽʻamĕyá֨h naẖàmá֜niy márĕdȯka֥y bi̇lĕşá֛̌n misĕpė֥reţ bi̇gĕwa֖y nĕẖ֣ẇm bȧʻàná֑h misĕpȧ֕r ʼanĕşé֖̌y ʻa֥m yişĕ̂ráʼéֽl׃s"],[7,8,"בְּנֵ֣י פַרְעֹ֔שׁ אַלְפַּ֕יִם מֵאָ֖ה וְ⁠שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y parĕʻò֔ş̌ ʼalĕpȧ֕yim méʼá֖h wĕ⁠şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,9,"בְּנֵ֣י שְׁפַטְיָ֔ה שְׁלֹ֥שׁ מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y şĕ̌patĕyá֔h şĕ̌lò֥ş̌ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,10,"בְּנֵ֣י אָרַ֔ח שֵׁ֥שׁ מֵא֖וֹת חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʼára֔ẖ şé֥̌ş̌ méʼ֖wòţ ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[7,11,"בְּנֵֽי־פַחַ֥ת מוֹאָ֛ב לִ⁠בְנֵ֥י יֵשׁ֖וּעַ וְ⁠יוֹאָ֑ב אַלְפַּ֕יִם וּ⁠שְׁמֹנֶ֥ה מֵא֖וֹת שְׁמֹנָ֥ה עָשָֽׂר׃ס","bĕ̇néֽy-paẖa֥ţ mwòʼá֛b li⁠bĕné֥y yéş֖̌ẇʻa wĕ⁠ywòʼá֑b ʼalĕpȧ֕yim ẇ⁠şĕ̌mòne֥h méʼ֖wòţ şĕ̌mòná֥h ʻáşáֽ̂r׃s"],[7,12,"בְּנֵ֣י עֵילָ֔ם אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y ʻéylá֔m ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[7,13,"בְּנֵ֣י זַתּ֔וּא שְׁמֹנֶ֥ה מֵא֖וֹת אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y zaţ̇֔ẇʼ şĕ̌mòne֥h méʼ֖wòţ ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[7,14,"בְּנֵ֣י זַכָּ֔י שְׁבַ֥ע מֵא֖וֹת וְ⁠שִׁשִּֽׁים׃ס","bĕ̇né֣y zaká̇֔y şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠şǐşiֽ̇̌ym׃s"],[7,15,"בְּנֵ֣י בִנּ֔וּי שֵׁ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇né֣y biṅ֔ẇy şé֥̌ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,16,"בְּנֵ֣י בֵבָ֔י שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇né֣y bébá֔y şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,17,"בְּנֵ֣י עַזְגָּ֔ד אַלְפַּ֕יִם שְׁלֹ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʻazĕgá̇֔d ʼalĕpȧ֕yim şĕ̌lò֥ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,18,"בְּנֵי֙ אֲדֹ֣נִיקָ֔ם שֵׁ֥שׁ מֵא֖וֹת שִׁשִּׁ֥ים וְ⁠שִׁבְעָֽה׃ס","bĕ̇néy֙ ʼàdò֣niyqá֔m şé֥̌ş̌ méʼ֖wòţ şǐşi֥̇̌ym wĕ⁠şǐbĕʻáֽh׃s"],[7,19,"בְּנֵ֣י בִגְוָ֔י אַלְפַּ֖יִם שִׁשִּׁ֥ים וְ⁠שִׁבְעָֽה׃ס","bĕ̇né֣y bigĕwá֔y ʼalĕpȧ֖yim şǐşi֥̇̌ym wĕ⁠şǐbĕʻáֽh׃s"],[7,20,"בְּנֵ֣י עָדִ֔ין שֵׁ֥שׁ מֵא֖וֹת חֲמִשִּׁ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y ʻádi֔yn şé֥̌ş̌ méʼ֖wòţ ẖàmişi֥̇̌ym wa⁠ẖàmişáֽ̇̌h׃s"],[7,21,"בְּנֵֽי־אָטֵ֥ר לְ⁠חִזְקִיָּ֖ה תִּשְׁעִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇néֽy-ʼáté֥r lĕ⁠ẖizĕqiyá֖̇h ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,22,"בְּנֵ֣י חָשֻׁ֔ם שְׁלֹ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃ס","bĕ̇né֣y ẖáşǔ֔m şĕ̌lò֥ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,23,"בְּנֵ֣י בֵצָ֔י שְׁלֹ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇né֣y béẕá֔y şĕ̌lò֥ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[7,24,"בְּנֵ֣י חָרִ֔יף מֵאָ֖ה שְׁנֵ֥ים עָשָֽׂר׃ס","bĕ̇né֣y ẖári֔yp méʼá֖h şĕ̌né֥ym ʻáşáֽ̂r׃s"],[7,25,"בְּנֵ֥י גִבְע֖וֹן תִּשְׁעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֥y gibĕʻ֖wòn ţi̇şĕ̌ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[7,26,"אַנְשֵׁ֤י בֵֽית־לֶ֨חֶם֙ וּ⁠נְטֹפָ֔ה מֵאָ֖ה שְׁמֹנִ֥ים וּ⁠שְׁמֹנָֽה׃ס","ʼanĕşé֤̌y béֽyţ-le֨ẖem֙ ẇ⁠nĕtòpá֔h méʼá֖h şĕ̌mòni֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,27,"אַנְשֵׁ֣י עֲנָת֔וֹת מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃ס","ʼanĕşé֣̌y ʻànáţ֔wòţ méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,28,"אַנְשֵׁ֥י בֵית־עַזְמָ֖וֶת אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","ʼanĕşé֥̌y béyţ-ʻazĕmá֖weţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,29,"אַנְשֵׁ֨י קִרְיַ֤ת יְעָרִים֙ כְּפִירָ֣ה וּ⁠בְאֵר֔וֹת שְׁבַ֥ע מֵא֖וֹת אַרְבָּעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","ʼanĕşé̌֨y qirĕya֤ţ yĕʻáriym֙ kĕ̇piyrá֣h ẇ⁠bĕʼér֔wòţ şĕ̌ba֥ʻ méʼ֖wòţ ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[7,30,"אַנְשֵׁ֤י הָֽ⁠רָמָה֙ וָ⁠גָ֔בַע שֵׁ֥שׁ מֵא֖וֹת עֶשְׂרִ֥ים וְ⁠אֶחָֽד׃ס","ʼanĕşé֤̌y háֽ⁠rámáh֙ wá⁠gá֔baʻ şé֥̌ş̌ méʼ֖wòţ ʻeşĕ̂ri֥ym wĕ⁠ʼeẖáֽd׃s"],[7,31,"אַנְשֵׁ֣י מִכְמָ֔ס מֵאָ֖ה וְ⁠עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","ʼanĕşé֣̌y mikĕmá֔s méʼá֖h wĕ⁠ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,32,"אַנְשֵׁ֤י בֵֽית־אֵל֙ וְ⁠הָ⁠עָ֔י מֵאָ֖ה עֶשְׂרִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","ʼanĕşé֤̌y béֽyţ-ʼél֙ wĕ⁠há⁠ʻá֔y méʼá֖h ʻeşĕ̂ri֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[7,33,"אַנְשֵׁ֥י נְב֛וֹ אַחֵ֖ר חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","ʼanĕşé֥̌y nĕb֛wò ʼaẖé֖r ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[7,34,"בְּנֵי֙ עֵילָ֣ם אַחֵ֔ר אֶ֕לֶף מָאתַ֖יִם חֲמִשִּׁ֥ים וְ⁠אַרְבָּעָֽה׃ס","bĕ̇néy֙ ʻéylá֣m ʼaẖé֔r ʼe֕lep máʼţa֖yim ẖàmişi֥̇̌ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[7,35,"בְּנֵ֣י חָרִ֔ם שְׁלֹ֥שׁ מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃ס","bĕ̇né֣y ẖári֔m şĕ̌lò֥ş̌ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃s"],[7,36,"בְּנֵ֣י יְרֵח֔וֹ שְׁלֹ֥שׁ מֵא֖וֹת אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","bĕ̇né֣y yĕréẖ֔wò şĕ̌lò֥ş̌ méʼ֖wòţ ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[7,37,"בְּנֵי־לֹד֙ חָדִ֣יד וְ⁠אוֹנ֔וֹ שְׁבַ֥ע מֵא֖וֹת וְ⁠עֶשְׂרִ֥ים וְ⁠אֶחָֽד׃ס","bĕ̇néy-lòd֙ ẖádi֣yd wĕ⁠ʼwòn֔wò şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʻeşĕ̂ri֥ym wĕ⁠ʼeẖáֽd׃s"],[7,38,"בְּנֵ֣י סְנָאָ֔ה שְׁלֹ֣שֶׁת אֲלָפִ֔ים תְּשַׁ֥ע מֵא֖וֹת וּ⁠שְׁלֹשִֽׁים׃פ","bĕ̇né֣y sĕnáʼá֔h şĕ̌lò֣şěţ ʼàlápi֔ym ţĕ̇şǎ֥ʻ méʼ֖wòţ ẇ⁠şĕ̌lòşǐֽym׃p"],[7,39,"הַֽ⁠כֹּהֲנִ֑ים בְּנֵ֤י יְדַֽעְיָה֙ לְ⁠בֵ֣ית יֵשׁ֔וּעַ תְּשַׁ֥ע מֵא֖וֹת שִׁבְעִ֥ים וּ⁠שְׁלֹשָֽׁה׃ס","haֽ⁠kò̇hàni֑ym bĕ̇né֤y yĕdaֽʻĕyáh֙ lĕ⁠bé֣yţ yéş̌֔ẇʻa ţĕ̇şǎ֥ʻ méʼ֖wòţ şǐbĕʻi֥ym ẇ⁠şĕ̌lòşáֽ̌h׃s"],[7,40,"בְּנֵ֣י אִמֵּ֔ר אֶ֖לֶף חֲמִשִּׁ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇né֣y ʼimé̇֔r ʼe֖lep ẖàmişi֥̇̌ym ẇ⁠şĕ̌náֽyim׃s"],[7,41,"בְּנֵ֣י פַשְׁח֔וּר אֶ֕לֶף מָאתַ֖יִם אַרְבָּעִ֥ים וְ⁠שִׁבְעָֽה׃ס","bĕ̇né֣y paşĕ̌ẖ֔ẇr ʼe֕lep máʼţa֖yim ʼarĕbá̇ʻi֥ym wĕ⁠şǐbĕʻáֽh׃s"],[7,42,"בְּנֵ֣י חָרִ֔ם אֶ֖לֶף שִׁבְעָ֥ה עָשָֽׂר׃פ","bĕ̇né֣y ẖári֔m ʼe֖lep şǐbĕʻá֥h ʻáşáֽ̂r׃p"],[7,43,"הַ⁠לְוִיִּ֑ם בְּנֵֽי־יֵשׁ֧וּעַ לְ⁠קַדְמִיאֵ֛ל לִ⁠בְנֵ֥י לְ⁠הוֹדְוָ֖ה שִׁבְעִ֥ים וְ⁠אַרְבָּעָֽה׃ס","ha⁠lĕwiyi֑̇m bĕ̇néֽy-yéş֧̌ẇʻa lĕ⁠qadĕmiyʼé֛l li⁠bĕné֥y lĕ⁠hwòdĕwá֖h şǐbĕʻi֥ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[7,44,"הַֽ⁠מְשֹׁרְרִ֑ים בְּנֵ֣י אָסָ֔ף מֵאָ֖ה אַרְבָּעִ֥ים וּ⁠שְׁמֹנָֽה׃ס","haֽ⁠mĕşò̌rĕri֑ym bĕ̇né֣y ʼásá֔p méʼá֖h ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,45,"הַ⁠שֹּֽׁעֲרִ֗ים בְּנֵֽי־שַׁלּ֤וּם בְּנֵֽי־אָטֵר֙ בְּנֵֽי־טַלְמֹ֣ן בְּנֵֽי־עַקּ֔וּב בְּנֵ֥י חֲטִיטָ֖א בְּנֵ֣י שֹׁבָ֑י מֵאָ֖ה שְׁלֹשִׁ֥ים וּ⁠שְׁמֹנָֽה׃ס","ha⁠şòֽ̇̌ʻàri֗ym bĕ̇néֽy-şǎl֤̇ẇm bĕ̇néֽy-ʼátér֙ bĕ̇néֽy-talĕmò֣n bĕ̇néֽy-ʻaq̇֔ẇb bĕ̇né֥y ẖàtiytá֖ʼ bĕ̇né֣y şò̌bá֑y méʼá֖h şĕ̌lòşǐ֥ym ẇ⁠şĕ̌mònáֽh׃s"],[7,46,"הַ⁠נְּתִינִ֑ים בְּנֵי־צִחָ֥א בְנֵי־חֲשֻׂפָ֖א בְּנֵ֥י טַבָּעֽוֹת׃","ha⁠nĕ̇ţiyni֑ym bĕ̇néy-ẕiẖá֥ʼ bĕnéy-ẖàşûpá֖ʼ bĕ̇né֥y tabá̇ʻֽwòţ׃"],[7,47,"בְּנֵי־קֵירֹ֥ס בְּנֵי־סִיעָ֖א בְּנֵ֥י פָדֽוֹן׃","bĕ̇néy-qéyrò֥s bĕ̇néy-siyʻá֖ʼ bĕ̇né֥y pádֽwòn׃"],[7,48,"בְּנֵי־לְבָנָ֥ה בְנֵי־חֲגָבָ֖ה בְּנֵ֥י שַׁלְמָֽי׃","bĕ̇néy-lĕbáná֥h bĕnéy-ẖàgábá֖h bĕ̇né֥y şǎlĕmáֽy׃"],[7,49,"בְּנֵי־חָנָ֥ן בְּנֵי־גִדֵּ֖ל בְּנֵי־גָֽחַר׃","bĕ̇néy-ẖáná֥n bĕ̇néy-gidé֖̇l bĕ̇néy-gáֽẖar׃"],[7,50,"בְּנֵי־רְאָיָ֥ה בְנֵי־רְצִ֖ין בְּנֵ֥י נְקוֹדָֽא׃","bĕ̇néy-rĕʼáyá֥h bĕnéy-rĕẕi֖yn bĕ̇né֥y nĕqwòdáֽʼ׃"],[7,51,"בְּנֵי־גַזָּ֥ם בְּנֵי־עֻזָּ֖א בְּנֵ֥י פָסֵֽחַ׃","bĕ̇néy-gazá֥̇m bĕ̇néy-ʻuzá֖̇ʼ bĕ̇né֥y páséֽẖa׃"],[7,52,"בְּנֵי־בֵסַ֥י בְּנֵי־מְעוּנִ֖ים בְּנֵ֥י נפושסים׃","bĕ̇néy-bésa֥y bĕ̇néy-mĕʻẇni֖ym bĕ̇né֥y npwşsym׃"],[7,53,"בְּנֵי־בַקְבּ֥וּק בְּנֵֽי־חֲקוּפָ֖א בְּנֵ֥י חַרְחֽוּר׃","bĕ̇néy-baqĕḃ֥ẇq bĕ̇néֽy-ẖàqẇpá֖ʼ bĕ̇né֥y ẖarĕẖֽẇr׃"],[7,54,"בְּנֵי־בַצְלִ֥ית בְּנֵֽי־מְחִידָ֖א בְּנֵ֥י חַרְשָֽׁא׃","bĕ̇néy-baẕĕli֥yţ bĕ̇néֽy-mĕẖiydá֖ʼ bĕ̇né֥y ẖarĕşáֽ̌ʼ׃"],[7,55,"בְּנֵי־בַרְק֥וֹס בְּֽנֵי־סִֽיסְרָ֖א בְּנֵי־תָֽמַח׃","bĕ̇néy-barĕq֥wòs bĕֽ̇néy-siֽysĕrá֖ʼ bĕ̇néy-ţáֽmaẖ׃"],[7,56,"בְּנֵ֥י נְצִ֖יחַ בְּנֵ֥י חֲטִיפָֽא׃","bĕ̇né֥y nĕẕi֖yẖa bĕ̇né֥y ẖàtiypáֽʼ׃"],[7,57,"בְּנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה בְּנֵי־סוֹטַ֥י בְּנֵי־סוֹפֶ֖רֶת בְּנֵ֥י פְרִידָֽא׃","bĕ̇né֖y ʻabĕdé֣y şĕ̌lòmò֑h bĕ̇néy-swòta֥y bĕ̇néy-swòpe֖reţ bĕ̇né֥y pĕriydáֽʼ׃"],[7,58,"בְּנֵי־יַעְלָ֥א בְנֵי־דַרְק֖וֹן בְּנֵ֥י גִדֵּֽל׃","bĕ̇néy-yaʻĕlá֥ʼ bĕnéy-darĕq֖wòn bĕ̇né֥y gidéֽ̇l׃"],[7,59,"בְּנֵ֧י שְׁפַטְיָ֣ה בְנֵֽי־חַטִּ֗יל בְּנֵ֛י פֹּכֶ֥רֶת הַצְּבָיִ֖ים בְּנֵ֥י אָמֽוֹן׃","bĕ̇né֧y şĕ̌patĕyá֣h bĕnéֽy-ẖati̇֗yl bĕ̇né֛y pò̇ke֥reţ haẕĕ̇báyi֖ym bĕ̇né֥y ʼámֽwòn׃"],[7,60,"כָּל־הַ֨⁠נְּתִינִ֔ים וּ⁠בְנֵ֖י עַבְדֵ֣י שְׁלֹמֹ֑ה שְׁלֹ֥שׁ מֵא֖וֹת תִּשְׁעִ֥ים וּ⁠שְׁנָֽיִם׃פ","ká̇l-ha֨⁠nĕ̇ţiyni֔ym ẇ⁠bĕné֖y ʻabĕdé֣y şĕ̌lòmò֑h şĕ̌lò֥ş̌ méʼ֖wòţ ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌náֽyim׃p"],[7,61,"וְ⁠אֵ֗לֶּה הָֽ⁠עוֹלִים֙ מִ⁠תֵּ֥ל מֶ֨לַח֙ תֵּ֣ל חַרְשָׁ֔א כְּר֥וּב אַדּ֖וֹן וְ⁠אִמֵּ֑ר וְ⁠לֹ֣א יָכְל֗וּ לְ⁠הַגִּ֤יד בֵּית־אֲבוֹתָ⁠ם֙ וְ⁠זַרְעָ֔⁠ם אִ֥ם מִ⁠יִּשְׂרָאֵ֖ל הֵֽם׃","wĕ⁠ʼé֗lėh háֽ⁠ʻwòliym֙ mi⁠ţé֥̇l me֨laẖ֙ ţé֣̇l ẖarĕşá̌֔ʼ kĕ̇r֥ẇb ʼaḋ֖wòn wĕ⁠ʼimé֑̇r wĕ⁠lò֣ʼ yákĕl֗ẇ lĕ⁠hagi֤̇yd bé̇yţ-ʼàbwòţá⁠m֙ wĕ⁠zarĕʻá֔⁠m ʼi֥m mi⁠yi̇şĕ̂ráʼé֖l héֽm׃"],[7,62,"בְּנֵי־דְלָיָ֥ה בְנֵֽי־טוֹבִיָּ֖ה בְּנֵ֣י נְקוֹדָ֑א שֵׁ֥שׁ מֵא֖וֹת וְ⁠אַרְבָּעִ֥ים וּ⁠שְׁנָֽיִם׃ס","bĕ̇néy-dĕláyá֥h bĕnéֽy-twòbiyá֖̇h bĕ̇né֣y nĕqwòdá֑ʼ şé֥̌ş̌ méʼ֖wòţ wĕ⁠ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌náֽyim׃s"],[7,63,"וּ⁠מִן־הַ⁠כֹּ֣הֲנִ֔ים בְּנֵ֥י חֳבַיָּ֖ה בְּנֵ֣י הַקּ֑וֹץ בְּנֵ֣י בַרְזִלַּ֗י אֲשֶׁ֣ר לָ֠קַח מִ⁠בְּנ֞וֹת בַּרְזִלַּ֤י הַ⁠גִּלְעָדִי֙ אִשָּׁ֔ה וַ⁠יִּקָּרֵ֖א עַל־שְׁמָֽ⁠ם׃","ẇ⁠min-ha⁠kò֣̇hàni֔ym bĕ̇né֥y ẖobayá֖̇h bĕ̇né֣y haq֑̇wòẕ bĕ̇né֣y barĕzilȧ֗y ʼàşě֣r lá֠qaẖ mi⁠bĕ̇n֞wòţ bȧrĕzilȧ֤y ha⁠gi̇lĕʻádiy֙ ʼişá̇̌֔h wa⁠yi̇qá̇ré֖ʼ ʻal-şĕ̌máֽ⁠m׃"],[7,64,"אֵ֗לֶּה בִּקְשׁ֧וּ כְתָבָ֛⁠ם הַ⁠מִּתְיַחְשִׂ֖ים וְ⁠לֹ֣א נִמְצָ֑א וַ⁠יְגֹֽאֲל֖וּ מִן־הַ⁠כְּהֻנָּֽה׃","ʼé֗lėh bi̇qĕş֧̌ẇ kĕţábá֛⁠m ha⁠mi̇ţĕyaẖĕşî֖ym wĕ⁠lò֣ʼ nimĕẕá֑ʼ wa⁠yĕgòֽʼàl֖ẇ min-ha⁠kĕ̇hunáֽ̇h׃"],[7,65,"וַ⁠יֹּ֤אמֶר הַ⁠תִּרְשָׁ֨תָא֙ לָ⁠הֶ֔ם אֲשֶׁ֥ר לֹא־יֹאכְל֖וּ מִ⁠קֹּ֣דֶשׁ הַ⁠קֳּדָשִׁ֑ים עַ֛ד עֲמֹ֥ד הַ⁠כֹּהֵ֖ן לְ⁠אוּרִ֥ים וְ⁠תוּמִּֽים׃","wa⁠yò֤̇ʼmer ha⁠ţi̇rĕşá̌֨ţáʼ֙ lá⁠he֔m ʼàşě֥r lòʼ-yòʼkĕl֖ẇ mi⁠qò֣̇deş̌ ha⁠qȯdáşǐ֑ym ʻa֛d ʻàmò֥d ha⁠kò̇hé֖n lĕ⁠ʼẇri֥ym wĕ⁠ţẇmiֽ̇ym׃"],[7,66,"כָּל־הַ⁠קָּהָ֖ל כְּ⁠אֶחָ֑ד אַרְבַּ֣ע רִבּ֔וֹא אַלְפַּ֖יִם שְׁלֹשׁ־מֵא֥וֹת וְ⁠שִׁשִּֽׁים׃","ká̇l-ha⁠qá̇há֖l kĕ̇⁠ʼeẖá֑d ʼarĕbȧ֣ʻ riḃ֔wòʼ ʼalĕpȧ֖yim şĕ̌lòş̌-méʼ֥wòţ wĕ⁠şǐşiֽ̇̌ym׃"],[7,67,"מִ֠⁠לְּ⁠בַד עַבְדֵי⁠הֶ֤ם וְ⁠אַמְהֹֽתֵי⁠הֶם֙ אֵ֔לֶּה שִׁבְעַ֣ת אֲלָפִ֔ים שְׁלֹ֥שׁ מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁבְעָ֑ה וְ⁠לָ⁠הֶ֗ם מְשֹֽׁרֲרִים֙ וּ⁠מְשֹׁ֣רֲר֔וֹת מָאתַ֖יִם וְ⁠אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃ס","mi֠⁠lĕ̇⁠bad ʻabĕdéy⁠he֤m wĕ⁠ʼamĕhòֽţéy⁠hem֙ ʼé֔lėh şǐbĕʻa֣ţ ʼàlápi֔ym şĕ̌lò֥ş̌ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐbĕʻá֑h wĕ⁠lá⁠he֗m mĕşòֽ̌ràriym֙ ẇ⁠mĕşò֣̌ràr֔wòţ máʼţa֖yim wĕ⁠ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃s"],[7,68,"[סוּסֵי⁠הֶ֕ם שְׁבַ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וְ⁠שִׁשָּׁ֑ה פִּרְדֵי⁠הֶ֕ם מָאתַ֖יִם אַרְבָּעִ֥ים וַ⁠חֲמִשָּֽׁה׃]","[sẇséy⁠he֕m şĕ̌ba֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wĕ⁠şǐşá֑̇̌h pi̇rĕdéy⁠he֕m máʼţa֖yim ʼarĕbá̇ʻi֥ym wa⁠ẖàmişáֽ̇̌h׃]"],[7,69,"גְּמַלִּ֕ים אַרְבַּ֥ע מֵא֖וֹת שְׁלֹשִׁ֣ים וַ⁠חֲמִשָּׁ֑ה ס חֲמֹרִ֕ים שֵׁ֣שֶׁת אֲלָפִ֔ים שְׁבַ֥ע מֵא֖וֹת וְ⁠עֶשְׂרִֽים׃","gĕ̇mali̇֕ym ʼarĕbȧ֥ʻ méʼ֖wòţ şĕ̌lòşǐ֣ym wa⁠ẖàmişá֑̇̌h s ẖàmòri֕ym şé֣̌şěţ ʼàlápi֔ym şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠ʻeşĕ̂riֽym׃"],[7,70,"וּ⁠מִ⁠קְצָת֙ רָאשֵׁ֣י הָֽ⁠אָב֔וֹת נָתְנ֖וּ לַ⁠מְּלָאכָ֑ה הַ⁠תִּרְשָׁ֜תָא נָתַ֣ן לָ⁠אוֹצָ֗ר זָהָ֞ב דַּרְכְּמֹנִ֥ים אֶ֨לֶף֙ מִזְרָק֣וֹת חֲמִשִּׁ֔ים כָּתְנוֹת֙ כֹּֽהֲנִ֔ים שְׁלֹשִׁ֖ים וַ⁠חֲמֵ֥שׁ מֵאֽוֹת׃","ẇ⁠mi⁠qĕẕáţ֙ ráʼşé֣̌y hֽá⁠ʼáb֔wòţ náţĕn֖ẇ la⁠mĕ̇láʼká֑h ha⁠ţi̇rĕşá̌֜ţáʼ náţa֣n lá⁠ʼwòẕá֗r záhá֞b dȧrĕkĕ̇mòni֥ym ʼe֨lep֙ mizĕráq֣wòţ ẖàmişi̇̌֔ym ká̇ţĕnwòţ֙ kòֽ̇hàni֔ym şĕ̌lòşǐ֖ym wa⁠ẖàmé֥ş̌ méʼֽwòţ׃"],[7,71,"וּ⁠מֵֽ⁠רָאשֵׁ֣י הָֽ⁠אָב֗וֹת נָֽתְנוּ֙ לְ⁠אוֹצַ֣ר הַ⁠מְּלָאכָ֔ה זָהָ֕ב דַּרְכְּמוֹנִ֖ים שְׁתֵּ֣י רִבּ֑וֹת וְ⁠כֶ֕סֶף מָנִ֖ים אַלְפַּ֥יִם וּ⁠מָאתָֽיִם׃","ẇ⁠méֽ⁠ráʼşé֣̌y háֽ⁠ʼáb֗wòţ náֽţĕnẇ֙ lĕ⁠ʼwòẕa֣r ha⁠mĕ̇láʼká֔h záhá֕b dȧrĕkĕ̇mwòni֖ym şĕ̌ţé֣̇y riḃ֑wòţ wĕ⁠ke֕sep máni֖ym ʼalĕpȧ֥yim ẇ⁠máʼţáֽyim׃"],[7,72,"וַ⁠אֲשֶׁ֣ר נָתְנוּ֮ שְׁאֵרִ֣ית הָ⁠עָם֒ זָהָ֗ב דַּרְכְּמוֹנִים֙ שְׁתֵּ֣י רִבּ֔וֹא וְ⁠כֶ֖סֶף מָנִ֣ים אַלְפָּ֑יִם וְ⁠כָתְנֹ֥ת כֹּֽהֲנִ֖ים שִׁשִּׁ֥ים וְ⁠שִׁבְעָֽה׃פ","wa⁠ʼàşě֣r náţĕnẇ֮ şĕ̌ʼéri֣yţ há⁠ʻám֒ záhá֗b dȧrĕkĕ̇mwòniym֙ şĕ̌ţé֣̇y riḃ֔wòʼ wĕ⁠ke֖sep máni֣ym ʼalĕpá֑̇yim wĕ⁠káţĕnò֥ţ kòֽ̇hàni֖ym şǐşi֥̇̌ym wĕ⁠şǐbĕʻáֽh׃p"],[7,73,"וַ⁠יֵּשְׁב֣וּ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֡ם וְ⁠הַ⁠שּׁוֹעֲרִים֩ וְ⁠הַ⁠מְשֹׁרְרִ֨ים וּ⁠מִן־הָ⁠עָ֧ם וְ⁠הַ⁠נְּתִינִ֛ים וְ⁠כָל־יִשְׂרָאֵ֖ל בְּ⁠עָרֵי⁠הֶ֑ם וַ⁠יִּגַּע֙ הַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י וּ⁠בְנֵ֥י יִשְׂרָאֵ֖ל בְּ⁠עָרֵי⁠הֶֽם׃","wa⁠yé̇şĕ̌b֣ẇ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֡m wĕ⁠ha⁠ş̇̌wòʻàriym֩ wĕ⁠ha⁠mĕşò̌rĕri֨ym ẇ⁠min-há⁠ʻá֧m wĕ⁠ha⁠nĕ̇ţiyni֛ym wĕ⁠kál-yişĕ̂ráʼé֖l bĕ̇⁠ʻáréy⁠he֑m wa⁠yi̇gȧʻ֙ ha⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y ẇ⁠bĕné֥y yişĕ̂ráʼé֖l bĕ̇⁠ʻáréy⁠heֽm׃"],[8,1,"וַ⁠יֵּאָסְפ֤וּ כָל־הָ⁠עָם֙ כְּ⁠אִ֣ישׁ אֶחָ֔ד אֶל־הָ֣⁠רְח֔וֹב אֲשֶׁ֖ר לִ⁠פְנֵ֣י שַֽׁעַר־הַ⁠מָּ֑יִם וַ⁠יֹּֽאמְרוּ֙ לְ⁠עֶזְרָ֣א הַ⁠סֹּפֵ֔ר לְ⁠הָבִ֗יא אֶת־סֵ֨פֶר֙ תּוֹרַ֣ת מֹשֶׁ֔ה אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶת־יִשְׂרָאֵֽל׃","wa⁠yé̇ʼásĕp֤ẇ kál-há⁠ʻám֙ kĕ̇⁠ʼi֣yş̌ ʼeẖá֔d ʼel-há֣⁠rĕẖ֔wòb ʼàşě֖r li⁠pĕné֣y şǎֽʻar-ha⁠má֑̇yim wa⁠yòֽ̇ʼmĕrẇ֙ lĕ⁠ʻezĕrá֣ʼ ha⁠sò̇pé֔r lĕ⁠hábi֗yʼ ʼeţ-sé֨per֙ ţ̇wòra֣ţ mòşě֔h ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţ-yişĕ̂ráʼéֽl׃"],[8,2,"וַ⁠יָּבִ֣יא עֶזְרָ֣א הַ֠⁠כֹּהֵן אֶֽת־הַ⁠תּוֹרָ֞ה לִ⁠פְנֵ֤י הַ⁠קָּהָל֙ מֵ⁠אִ֣ישׁ וְ⁠עַד־אִשָּׁ֔ה וְ⁠כֹ֖ל מֵבִ֣ין לִ⁠שְׁמֹ֑עַ בְּ⁠י֥וֹם אֶחָ֖ד לַ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִיעִֽי׃","wa⁠yá̇bi֣yʼ ʻezĕrá֣ʼ ha֠⁠kò̇hén ʼeֽţ-ha⁠ţ̇wòrá֞h li⁠pĕné֤y ha⁠qá̇hál֙ mé⁠ʼi֣yş̌ wĕ⁠ʻad-ʼişá̇̌֔h wĕ⁠kò֖l mébi֣yn li⁠şĕ̌mò֑ʻa bĕ̇⁠y֥wòm ʼeẖá֖d la⁠ẖò֥deş̌ ha⁠şĕ̇̌biyʻiֽy׃"],[8,3,"וַ⁠יִּקְרָא־ב⁠וֹ֩ לִ⁠פְנֵ֨י הָ⁠רְח֜וֹב אֲשֶׁ֣ר ׀ לִ⁠פְנֵ֣י שַֽׁעַר־הַ⁠מַּ֗יִם מִן־הָ⁠אוֹר֙ עַד־מַחֲצִ֣ית הַ⁠יּ֔וֹם נֶ֛גֶד הָ⁠אֲנָשִׁ֥ים וְ⁠הַ⁠נָּשִׁ֖ים וְ⁠הַ⁠מְּבִינִ֑ים וְ⁠אָזְנֵ֥י כָל־הָ⁠עָ֖ם אֶל־סֵ֥פֶר הַ⁠תּוֹרָֽה׃","wa⁠yi̇qĕráʼ-b⁠wò֩ li⁠pĕné֨y há⁠rĕẖ֜wòb ʼàşě֣r ׀ li⁠pĕné֣y şǎֽʻar-ha⁠mȧ֗yim min-há⁠ʼwòr֙ ʻad-maẖàẕi֣yţ ha⁠ẏ֔wòm ne֛ged há⁠ʼànáşǐ֥ym wĕ⁠ha⁠ná̇şǐ֖ym wĕ⁠ha⁠mĕ̇biyni֑ym wĕ⁠ʼázĕné֥y kál-há⁠ʻá֖m ʼel-sé֥per ha⁠ţ̇wòráֽh׃"],[8,4,"וַֽ⁠יַּעֲמֹ֞ד עֶזְרָ֣א הַ⁠סֹּפֵ֗ר עַֽל־מִגְדַּל־עֵץ֮ אֲשֶׁ֣ר עָשׂ֣וּ לַ⁠דָּבָר֒ וַ⁠יַּֽעֲמֹ֣ד אֶצְל֡⁠וֹ מַתִּתְיָ֡ה וְ⁠שֶׁ֡מַע וַ֠⁠עֲנָיָה וְ⁠אוּרִיָּ֧ה וְ⁠חִלְקִיָּ֛ה וּ⁠מַעֲשֵׂיָ֖ה עַל־יְמִינ֑⁠וֹ וּ⁠מִ⁠שְּׂמֹאל֗⁠וֹ פְּ֠דָיָה וּ⁠מִֽישָׁאֵ֧ל וּ⁠מַלְכִּיָּ֛ה וְ⁠חָשֻׁ֥ם וְ⁠חַשְׁבַּדָּ֖נָה זְכַרְיָ֥ה מְשֻׁלָּֽם׃פ","wֽa⁠yȧʻàmò֞d ʻezĕrá֣ʼ ha⁠sò̇pé֗r ʻaֽl-migĕdȧl-ʻéẕ֮ ʼàşě֣r ʻáş֣̂ẇ la⁠dá̇bár֒ wa⁠yȧֽʻàmò֣d ʼeẕĕl֡⁠wò maţi̇ţĕyá֡h wĕ⁠şě֡maʻ wa֠⁠ʻànáyáh wĕ⁠ʼẇriyá֧̇h wĕ⁠ẖilĕqiyá֛̇h ẇ⁠maʻàşé̂yá֖h ʻal-yĕmiyn֑⁠wò ẇ⁠mi⁠şĕ̇̂mòʼl֗⁠wò pĕ̇֠dáyáh ẇ⁠miֽyşá̌ʼé֧l ẇ⁠malĕki̇yá֛̇h wĕ⁠ẖáşǔ֥m wĕ⁠ẖaşĕ̌bȧdá֖̇náh zĕkarĕyá֥h mĕşǔláֽ̇m׃p"],[8,5,"וַ⁠יִּפְתַּ֨ח עֶזְרָ֤א הַ⁠סֵּ֨פֶר֙ לְ⁠עֵינֵ֣י כָל־הָ⁠עָ֔ם כִּֽי־מֵ⁠עַ֥ל כָּל־הָ⁠עָ֖ם הָיָ֑ה וּ⁠כְ⁠פִתְח֖⁠וֹ עָֽמְד֥וּ כָל־הָ⁠עָֽם׃","wa⁠yi̇pĕţȧ֨ẖ ʻezĕrá֤ʼ ha⁠sé̇֨per֙ lĕ⁠ʻéyné֣y kál-há⁠ʻá֔m kiֽ̇y-mé⁠ʻa֥l ká̇l-há⁠ʻá֖m háyá֑h ẇ⁠kĕ⁠piţĕẖ֖⁠wò ʻáֽmĕd֥ẇ kál-há⁠ʻáֽm׃"],[8,6,"וַ⁠יְבָ֣רֶךְ עֶזְרָ֔א אֶת־יְהוָ֥ה הָ⁠אֱלֹהִ֖ים הַ⁠גָּד֑וֹל וַ⁠יַּֽעֲנ֨וּ כָל־הָ⁠עָ֜ם אָמֵ֤ן ׀ אָמֵן֙ בְּ⁠מֹ֣עַל יְדֵי⁠הֶ֔ם וַ⁠יִּקְּד֧וּ וַ⁠יִּשְׁתַּחֲוֻּ֛ לַ⁠יהוָ֖ה אַפַּ֥יִם אָֽרְצָ⁠ה׃","wa⁠yĕbá֣rekĕ ʻezĕrá֔ʼ ʼeţ-yĕhwá֥h há⁠ʼèlòhi֖ym ha⁠gá̇d֑wòl wa⁠yȧֽʻàn֨ẇ kál-há⁠ʻá֜m ʼámé֤n ׀ ʼámén֙ bĕ̇⁠mò֣ʻal yĕdéy⁠he֔m wa⁠yi̇qĕ̇d֧ẇ wa⁠yi̇şĕ̌ţȧẖàwu֛̇ la⁠yhwá֖h ʼapȧ֥yim ʼáֽrĕẕá⁠h׃"],[8,7,"וְ⁠יֵשׁ֡וּעַ וּ⁠בָנִ֡י וְ⁠שֵׁרֵ֥בְיָ֣ה ׀ יָמִ֡ין עַקּ֡וּב שַׁבְּתַ֣י ׀ הֽוֹדִיָּ֡ה מַעֲשֵׂיָ֡ה קְלִיטָ֣א עֲזַרְיָה֩ יוֹזָבָ֨ד חָנָ֤ן פְּלָאיָה֙ וְ⁠הַ⁠לְוִיִּ֔ם מְבִינִ֥ים אֶת־הָ⁠עָ֖ם לַ⁠תּוֹרָ֑ה וְ⁠הָ⁠עָ֖ם עַל־עָמְדָֽ⁠ם׃","wĕ⁠yéş̌֡ẇʻa ẇ⁠báni֡y wĕ⁠şé̌ré֥bĕyá֣h ׀ yámi֡yn ʻaq̇֡ẇb şǎbĕ̇ţa֣y ׀ hֽwòdiyá̇֡h maʻàşé̂yá֡h qĕliytá֣ʼ ʻàzarĕyáh֩ ywòzábá֨d ẖáná֤n pĕ̇láʼyáh֙ wĕ⁠ha⁠lĕwiyi̇֔m mĕbiyni֥ym ʼeţ-há⁠ʻá֖m la⁠ţ̇wòrá֑h wĕ⁠há⁠ʻá֖m ʻal-ʻámĕdáֽ⁠m׃"],[8,8,"וַֽ⁠יִּקְרְא֥וּ בַ⁠סֵּ֛פֶר בְּ⁠תוֹרַ֥ת הָ⁠אֱלֹהִ֖ים מְפֹרָ֑שׁ וְ⁠שׂ֣וֹם שֶׂ֔כֶל וַ⁠יָּבִ֖ינוּ בַּ⁠מִּקְרָֽא׃ס","waֽ⁠yi̇qĕrĕʼ֥ẇ ba⁠sé֛̇per bĕ̇⁠ţwòra֥ţ há⁠ʼèlòhi֖ym mĕpòrá֑ş̌ wĕ⁠ş֣̂wòm şê֔kel wa⁠yá̇bi֖ynẇ bȧ⁠mi̇qĕráֽʼ׃s"],[8,9,"וַ⁠יֹּ֣אמֶר נְחֶמְיָ֣ה ה֣וּא הַ⁠תִּרְשָׁ֡תָא וְ⁠עֶזְרָ֣א הַ⁠כֹּהֵ֣ן ׀ הַ⁠סֹּפֵ֡ר וְ⁠הַ⁠לְוִיִּם֩ הַ⁠מְּבִינִ֨ים אֶת־הָ⁠עָ֜ם לְ⁠כָל־הָ⁠עָ֗ם הַ⁠יּ֤וֹם קָדֹֽשׁ־הוּא֙ לַ⁠יהוָ֣ה אֱלֹהֵי⁠כֶ֔ם אַל־תִּֽתְאַבְּל֖וּ וְ⁠אַל־תִּבְכּ֑וּ כִּ֤י בוֹכִים֙ כָּל־הָ⁠עָ֔ם כְּ⁠שָׁמְעָ֖⁠ם אֶת־דִּבְרֵ֥י הַ⁠תּוֹרָֽה׃","wa⁠yò֣̇ʼmer nĕẖemĕyá֣h h֣ẇʼ ha⁠ţi̇rĕşá̌֡ţáʼ wĕ⁠ʻezĕrá֣ʼ ha⁠kò̇hé֣n ׀ ha⁠sò̇pé֡r wĕ⁠ha⁠lĕwiyi̇m֩ ha⁠mĕ̇biyni֨ym ʼeţ-há⁠ʻá֜m lĕ⁠kál-há⁠ʻá֗m ha⁠ẏ֤wòm qádòֽş̌-hẇʼ֙ la⁠yhwá֣h ʼèlòhéy⁠ke֔m ʼal-ţiֽ̇ţĕʼabĕ̇l֖ẇ wĕ⁠ʼal-ţi̇bĕk֑̇ẇ ki֤̇y bwòkiym֙ ká̇l-há⁠ʻá֔m kĕ̇⁠şá̌mĕʻá֖⁠m ʼeţ-di̇bĕré֥y ha⁠ţ̇wòráֽh׃"],[8,10,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֡ם לְכוּ֩ אִכְל֨וּ מַשְׁמַנִּ֜ים וּ⁠שְׁת֣וּ מַֽמְתַקִּ֗ים וְ⁠שִׁלְח֤וּ מָנוֹת֙ לְ⁠אֵ֣ין נָכ֣וֹן ל֔⁠וֹ כִּֽי־קָד֥וֹשׁ הַ⁠יּ֖וֹם לַ⁠אֲדֹנֵ֑י⁠נוּ וְ⁠אַל־תֵּ֣עָצֵ֔בוּ כִּֽי־חֶדְוַ֥ת יְהוָ֖ה הִ֥יא מָֽעֻזְּ⁠כֶֽם׃","wa⁠yò֣̇ʼmer lá⁠he֡m lĕkẇ֩ ʼikĕl֨ẇ maşĕ̌mani̇֜ym ẇ⁠şĕ̌ţ֣ẇ maֽmĕţaqi̇֗ym wĕ⁠şǐlĕẖ֤ẇ mánwòţ֙ lĕ⁠ʼé֣yn nák֣wòn l֔⁠wò kiֽ̇y-qád֥wòş̌ ha⁠ẏ֖wòm la⁠ʼàdòné֑y⁠nẇ wĕ⁠ʼal-ţé֣̇ʻáẕé֔bẇ kiֽ̇y-ẖedĕwa֥ţ yĕhwá֖h hi֥yʼ máֽʻuzĕ̇⁠keֽm׃"],[8,11,"וְ⁠הַ⁠לְוִיִּ֞ם מַחְשִׁ֤ים לְ⁠כָל־הָ⁠עָם֙ לֵ⁠אמֹ֣ר הַ֔סּוּ כִּ֥י הַ⁠יּ֖וֹם קָדֹ֑שׁ וְ⁠אַל־תֵּעָצֵֽבוּ׃","wĕ⁠ha⁠lĕwiyi̇֞m maẖĕşǐ֤ym lĕ⁠kál-há⁠ʻám֙ lé⁠ʼmò֣r ha֔ṡẇ ki֥̇y ha⁠ẏ֖wòm qádò֑ş̌ wĕ⁠ʼal-ţé̇ʻáẕéֽbẇ׃"],[8,12,"וַ⁠יֵּלְכ֨וּ כָל־הָ⁠עָ֜ם לֶ⁠אֱכֹ֤ל וְ⁠לִ⁠שְׁתּוֹת֙ וּ⁠לְ⁠שַׁלַּ֣ח מָנ֔וֹת וְ⁠לַ⁠עֲשׂ֖וֹת שִׂמְחָ֣ה גְדוֹלָ֑ה כִּ֤י הֵבִ֨ינוּ֙ בַּ⁠דְּבָרִ֔ים אֲשֶׁ֥ר הוֹדִ֖יעוּ לָ⁠הֶֽם׃ס","wa⁠yé̇lĕk֨ẇ kál-há⁠ʻá֜m le⁠ʼèkò֤l wĕ⁠li⁠şĕ̌ţ̇wòţ֙ ẇ⁠lĕ⁠şǎlȧ֣ẖ mán֔wòţ wĕ⁠la⁠ʻàş֖̂wòţ şîmĕẖá֣h gĕdwòlá֑h ki֤̇y hébi֨ynẇ֙ bȧ⁠dĕ̇bári֔ym ʼàşě֥r hwòdi֖yʻẇ lá⁠heֽm׃s"],[8,13,"וּ⁠בַ⁠יּ֣וֹם הַ⁠שֵּׁנִ֡י נֶאֶסְפוּ֩ רָאשֵׁ֨י הָ⁠אָב֜וֹת לְ⁠כָל־הָ⁠עָ֗ם הַ⁠כֹּֽהֲנִים֙ וְ⁠הַ⁠לְוִיִּ֔ם אֶל־עֶזְרָ֖א הַ⁠סֹּפֵ֑ר וּ⁠לְ⁠הַשְׂכִּ֖יל אֶל־דִּבְרֵ֥י הַ⁠תּוֹרָֽה׃","ẇ⁠ba⁠ẏ֣wòm ha⁠şé̇̌ni֡y neʼesĕpẇ֩ ráʼşé̌֨y há⁠ʼáb֜wòţ lĕ⁠kál-há⁠ʻá֗m ha⁠kòֽ̇hàniym֙ wĕ⁠ha⁠lĕwiyi̇֔m ʼel-ʻezĕrá֖ʼ ha⁠sò̇pé֑r ẇ⁠lĕ⁠haşĕ̂ki֖̇yl ʼel-di̇bĕré֥y ha⁠ţ̇wòráֽh׃"],[8,14,"וַֽ⁠יִּמְצְא֖וּ כָּת֣וּב בַּ⁠תּוֹרָ֑ה אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ בְּ⁠יַד־מֹשֶׁ֔ה אֲשֶׁר֩ יֵשְׁב֨וּ בְנֵֽי־יִשְׂרָאֵ֧ל בַּ⁠סֻּכּ֛וֹת בֶּ⁠חָ֖ג בַּ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִיעִֽי׃","waֽ⁠yi̇mĕẕĕʼ֖ẇ ká̇ţ֣ẇb bȧ⁠ţ̇wòrá֑h ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ bĕ̇⁠yad-mòşě֔h ʼàşěr֩ yéşĕ̌b֨ẇ bĕnéֽy-yişĕ̂ráʼé֧l bȧ⁠su̇k֛̇wòţ bė⁠ẖá֖g bȧ⁠ẖò֥deş̌ ha⁠şĕ̇̌biyʻiֽy׃"],[8,15,"וַ⁠אֲשֶׁ֣ר יַשְׁמִ֗יעוּ וְ⁠יַעֲבִ֨ירוּ ק֥וֹל בְּ⁠כָל־עָרֵי⁠הֶם֮ וּ⁠בִ⁠ירוּשָׁלִַ֣ם לֵ⁠אמֹר֒ צְא֣וּ הָ⁠הָ֗ר וְ⁠הָבִ֨יאוּ֙ עֲלֵי־זַ֨יִת֙ וַ⁠עֲלֵי־עֵ֣ץ שֶׁ֔מֶן וַ⁠עֲלֵ֤י הֲדַס֙ וַ⁠עֲלֵ֣י תְמָרִ֔ים וַ⁠עֲלֵ֖י עֵ֣ץ עָבֹ֑ת לַ⁠עֲשֹׂ֥ת סֻכֹּ֖ת כַּ⁠כָּתֽוּב׃פ","wa⁠ʼàşě֣r yaşĕ̌mi֗yʻẇ wĕ⁠yaʻàbi֨yrẇ q֥wòl bĕ̇⁠kál-ʻáréy⁠hem֮ ẇ⁠bi⁠yrẇşá̌lia֣m lé⁠ʼmòr֒ ẕĕʼ֣ẇ há⁠há֗r wĕ⁠hábi֨yʼẇ֙ ʻàléy-za֨yiţ֙ wa⁠ʻàléy-ʻé֣ẕ şě֔men wa⁠ʻàlé֤y hàdas֙ wa⁠ʻàlé֣y ţĕmári֔ym wa⁠ʻàlé֖y ʻé֣ẕ ʻábò֑ţ la⁠ʻàşò֥̂ţ sukò֖̇ţ kȧ⁠ká̇ţֽẇb׃p"],[8,16,"וַ⁠יֵּצְא֣וּ הָ⁠עָם֮ וַ⁠יָּבִיאוּ֒ וַ⁠יַּעֲשׂוּ֩ לָ⁠הֶ֨ם סֻכּ֜וֹת אִ֤ישׁ עַל־גַּגּ⁠וֹ֙ וּ⁠בְ⁠חַצְרֹ֣תֵי⁠הֶ֔ם וּ⁠בְ⁠חַצְר֖וֹת בֵּ֣ית הָ⁠אֱלֹהִ֑ים וּ⁠בִ⁠רְחוֹב֙ שַׁ֣עַר הַ⁠מַּ֔יִם וּ⁠בִ⁠רְח֖וֹב שַׁ֥עַר אֶפְרָֽיִם׃","wa⁠yé̇ẕĕʼ֣ẇ há⁠ʻám֮ wa⁠yá̇biyʼẇ֒ wa⁠yȧʻàş̂ẇ֩ lá⁠he֨m suk̇֜wòţ ʼi֤yş̌ ʻal-gȧġ⁠wò֙ ẇ⁠bĕ⁠ẖaẕĕrò֣ţéy⁠he֔m ẇ⁠bĕ⁠ẖaẕĕr֖wòţ bé֣̇yţ há⁠ʼèlòhi֑ym ẇ⁠bi⁠rĕẖwòb֙ şǎ֣ʻar ha⁠mȧ֔yim ẇ⁠bi⁠rĕẖ֖wòb şǎ֥ʻar ʼepĕráֽyim׃"],[8,17,"וַ⁠יַּֽעֲשׂ֣וּ כָֽל־הַ֠⁠קָּהָל הַ⁠שָּׁבִ֨ים מִן־הַ⁠שְּׁבִ֥י ׀ סֻכּוֹת֮ וַ⁠יֵּשְׁב֣וּ בַ⁠סֻּכּוֹת֒ כִּ֣י לֹֽא־עָשׂ֡וּ מִ⁠ימֵי֩ יֵשׁ֨וּעַ בִּן־נ֥וּן כֵּן֙ בְּנֵ֣י יִשְׂרָאֵ֔ל עַ֖ד הַ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠תְּהִ֥י שִׂמְחָ֖ה גְּדוֹלָ֥ה מְאֹֽד׃","wa⁠yȧֽʻàş֣̂ẇ káֽl-ha֠⁠qá̇hál ha⁠şá̇̌bi֨ym min-ha⁠şĕ̇̌bi֥y ׀ suk̇wòţ֮ wa⁠yé̇şĕ̌b֣ẇ ba⁠su̇k̇wòţ֒ ki֣̇y lòֽʼ-ʻáş̂֡ẇ mi⁠yméy֩ yéş̌֨ẇʻa bi̇n-n֥ẇn ké̇n֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʻa֖d ha⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠ţĕ̇hi֥y şîmĕẖá֖h gĕ̇dwòlá֥h mĕʼòֽd׃"],[8,18,"וַ֠⁠יִּקְרָא בְּ⁠סֵ֨פֶר תּוֹרַ֤ת הָ⁠אֱלֹהִים֙ י֣וֹם ׀ בְּ⁠י֔וֹם מִן־הַ⁠יּוֹם֙ הָֽ⁠רִאשׁ֔וֹן עַ֖ד הַ⁠יּ֣וֹם הָ⁠אַחֲר֑וֹן וַ⁠יַּֽעֲשׂוּ־חָג֙ שִׁבְעַ֣ת יָמִ֔ים וּ⁠בַ⁠יּ֧וֹם הַ⁠שְּׁמִינִ֛י עֲצֶ֖רֶת כַּ⁠מִּשְׁפָּֽט׃פ","wa֠⁠yi̇qĕráʼ bĕ̇⁠sé֨per ţ̇wòra֤ţ há⁠ʼèlòhiym֙ y֣wòm ׀ bĕ̇⁠y֔wòm min-ha⁠ẏwòm֙ háֽ⁠riʼş̌֔wòn ʻa֖d ha⁠ẏ֣wòm há⁠ʼaẖàr֑wòn wa⁠yȧֽʻàş̂ẇ-ẖág֙ şǐbĕʻa֣ţ yámi֔ym ẇ⁠ba⁠ẏ֧wòm ha⁠şĕ̇̌miyni֛y ʻàẕe֖reţ kȧ⁠mi̇şĕ̌páֽ̇t׃p"],[9,1,"וּ⁠בְ⁠יוֹם֩ עֶשְׂרִ֨ים וְ⁠אַרְבָּעָ֜ה לַ⁠חֹ֣דֶשׁ הַ⁠זֶּ֗ה נֶאֶסְפ֤וּ בְנֵֽי־יִשְׂרָאֵל֙ בְּ⁠צ֣וֹם וּ⁠בְ⁠שַׂקִּ֔ים וַ⁠אֲדָמָ֖ה עֲלֵי⁠הֶֽם׃","ẇ⁠bĕ⁠ywòm֩ ʻeşĕ̂ri֨ym wĕ⁠ʼarĕbá̇ʻá֜h la⁠ẖò֣deş̌ ha⁠zė֗h neʼesĕp֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ bĕ̇⁠ẕ֣wòm ẇ⁠bĕ⁠şâqi̇֔ym wa⁠ʼàdámá֖h ʻàléy⁠heֽm׃"],[9,2,"וַ⁠יִּבָּֽדְלוּ֙ זֶ֣רַע יִשְׂרָאֵ֔ל מִ⁠כֹּ֖ל בְּנֵ֣י נֵכָ֑ר וַ⁠יַּעַמְד֗וּ וַ⁠יִּתְוַדּוּ֙ עַל־חַטֹּ֣אתֵי⁠הֶ֔ם וַ⁠עֲוֺנ֖וֹת אֲבֹתֵי⁠הֶֽם׃","wa⁠yi̇báֽ̇dĕlẇ֙ ze֣raʻ yişĕ̂ráʼé֔l mi⁠kò֖̇l bĕ̇né֣y néká֑r wa⁠yȧʻamĕd֗ẇ wa⁠yi̇ţĕwaḋẇ֙ ʻal-ẖatò֣̇ʼţéy⁠he֔m wa⁠ʻàwֺn֖wòţ ʼàbòţéy⁠heֽm׃"],[9,3,"וַ⁠יָּק֨וּמוּ֙ עַל־עָמְדָ֔⁠ם וַֽ⁠יִּקְרְא֗וּ בְּ⁠סֵ֨פֶר תּוֹרַ֧ת יְהוָ֛ה אֱלֹהֵי⁠הֶ֖ם רְבִעִ֣ית הַ⁠יּ֑וֹם וּ⁠רְבִעִית֙ מִתְוַדִּ֣ים וּ⁠מִֽשְׁתַּחֲוִ֔ים לַ⁠יהוָ֖ה אֱלֹהֵי⁠הֶֽם׃פ","wa⁠yá̇q֨ẇmẇ֙ ʻal-ʻámĕdá֔⁠m waֽ⁠yi̇qĕrĕʼ֗ẇ bĕ̇⁠sé֨per ţ̇wòra֧ţ yĕhwá֛h ʼèlòhéy⁠he֖m rĕbiʻi֣yţ ha⁠ẏ֑wòm ẇ⁠rĕbiʻiyţ֙ miţĕwadi֣̇ym ẇ⁠miֽşĕ̌ţȧẖàwi֔ym la⁠yhwá֖h ʼèlòhéy⁠heֽm׃p"],[9,4,"וַ⁠יָּ֜קָם עַֽל־מַֽעֲלֵ֣ה הַ⁠לְוִיִּ֗ם יֵשׁ֨וּעַ וּ⁠בָנִ֜י קַדְמִיאֵ֧ל שְׁבַנְיָ֛ה בֻּנִּ֥י שֵׁרֵבְיָ֖ה בָּנִ֣י כְנָ֑נִי וַֽ⁠יִּזְעֲקוּ֙ בְּ⁠ק֣וֹל גָּד֔וֹל אֶל־יְהוָ֖ה אֱלֹהֵי⁠הֶֽם׃","wa⁠yá̇֜qám ʻaֽl-maֽʻàlé֣h ha⁠lĕwiyi̇֗m yéş̌֨ẇʻa ẇ⁠báni֜y qadĕmiyʼé֧l şĕ̌banĕyá֛h bu̇ni֥̇y şé̌rébĕyá֖h bá̇ni֣y kĕná֑niy waֽ⁠yi̇zĕʻàqẇ֙ bĕ̇⁠q֣wòl gá̇d֔wòl ʼel-yĕhwá֖h ʼèlòhéy⁠heֽm׃"],[9,5,"וַ⁠יֹּאמְר֣וּ הַ⁠לְוִיִּ֡ם יֵשׁ֣וּעַ וְ֠⁠קַדְמִיאֵל בָּנִ֨י חֲשַׁבְנְיָ֜ה שֵׁרֵֽבְיָ֤ה הֽוֹדִיָּה֙ שְׁבַנְיָ֣ה פְתַֽחְיָ֔ה ק֗וּמוּ בָּרֲכוּ֙ אֶת־יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם מִן־הָ⁠עוֹלָ֖ם עַד־הָ⁠עוֹלָ֑ם וִ⁠יבָֽרְכוּ֙ שֵׁ֣ם כְּבוֹדֶ֔⁠ךָ וּ⁠מְרוֹמַ֥ם עַל־כָּל־בְּרָכָ֖ה וּ⁠תְהִלָּֽה׃","wa⁠yò̇ʼmĕr֣ẇ ha⁠lĕwiyi̇֡m yéş֣̌ẇʻa wĕ֠⁠qadĕmiyʼél bá̇ni֨y ẖàşǎbĕnĕyá֜h şé̌réֽbĕyá֤h hֽwòdiyá̇h֙ şĕ̌banĕyá֣h pĕţaֽẖĕyá֔h q֗ẇmẇ bá̇ràkẇ֙ ʼeţ-yĕhwá֣h ʼèlòֽhéy⁠ke֔m min-há⁠ʻwòlá֖m ʻad-há⁠ʻwòlá֑m wi⁠ybáֽrĕkẇ֙ şé֣̌m kĕ̇bwòde֔⁠ká ẇ⁠mĕrwòma֥m ʻal-ká̇l-bĕ̇ráká֖h ẇ⁠ţĕhiláֽ̇h׃"],[9,6,"אַתָּה־ה֣וּא יְהוָה֮ לְ⁠בַדֶּ⁠ךָ֒ את עָשִׂ֡יתָ אֶֽת־הַ⁠שָּׁמַיִם֩ שְׁמֵ֨י הַ⁠שָּׁמַ֜יִם וְ⁠כָל־צְבָאָ֗⁠ם הָ⁠אָ֜רֶץ וְ⁠כָל־אֲשֶׁ֤ר עָלֶ֨י⁠הָ֙ הַ⁠יַּמִּים֙ וְ⁠כָל־אֲשֶׁ֣ר בָּ⁠הֶ֔ם וְ⁠אַתָּ֖ה מְחַיֶּ֣ה אֶת־כֻּלָּ֑⁠ם וּ⁠צְבָ֥א הַ⁠שָּׁמַ֖יִם לְ⁠ךָ֥ מִשְׁתַּחֲוִֽים׃","ʼaţá̇h-h֣ẇʼ yĕhwáh֮ lĕ⁠badė⁠ká֒ ʼţ ʻáşî֡yţá ʼeֽţ-ha⁠şá̇̌mayim֩ şĕ̌mé֨y ha⁠şá̇̌ma֜yim wĕ⁠kál-ẕĕbáʼá֗⁠m há⁠ʼá֜reẕ wĕ⁠kál-ʼàşě֤r ʻále֨y⁠há֙ ha⁠yȧmi̇ym֙ wĕ⁠kál-ʼàşě֣r bá̇⁠he֔m wĕ⁠ʼaţá֖̇h mĕẖayė֣h ʼeţ-ku̇lá֑̇⁠m ẇ⁠ẕĕbá֥ʼ ha⁠şá̇̌ma֖yim lĕ⁠ká֥ mişĕ̌ţȧẖàwiֽym׃"],[9,7,"אַתָּה־הוּא֙ יְהוָ֣ה הָ⁠אֱלֹהִ֔ים אֲשֶׁ֤ר בָּחַ֨רְתָּ֙ בְּ⁠אַבְרָ֔ם וְ⁠הוֹצֵאת֖⁠וֹ מֵ⁠א֣וּר כַּשְׂדִּ֑ים וְ⁠שַׂ֥מְתָּ שְּׁמ֖⁠וֹ אַבְרָהָֽם׃","ʼaţá̇h-hẇʼ֙ yĕhwá֣h há⁠ʼèlòhi֔ym ʼàşě֤r bá̇ẖa֨rĕţá̇֙ bĕ̇⁠ʼabĕrá֔m wĕ⁠hwòẕéʼţ֖⁠wò mé⁠ʼ֣ẇr kȧşĕ̂di֑̇ym wĕ⁠şâ֥mĕţá̇ şĕ̇̌m֖⁠wò ʼabĕráháֽm׃"],[9,8,"וּ⁠מָצָ֣אתָ אֶת־לְבָב⁠וֹ֮ נֶאֱמָ֣ן לְ⁠פָנֶי⁠ךָ֒ וְ⁠כָר֨וֹת עִמּ֜⁠וֹ הַ⁠בְּרִ֗ית לָ⁠תֵ֡ת אֶת־אֶרֶץ֩ הַ⁠כְּנַעֲנִ֨י הַ⁠חִתִּ֜י הָ⁠אֱמֹרִ֧י וְ⁠הַ⁠פְּרִזִּ֛י וְ⁠הַ⁠יְבוּסִ֥י וְ⁠הַ⁠גִּרְגָּשִׁ֖י לָ⁠תֵ֣ת לְ⁠זַרְע֑⁠וֹ וַ⁠תָּ֨קֶם֙ אֶת־דְּבָרֶ֔י⁠ךָ כִּ֥י צַדִּ֖יק אָֽתָּה׃","ẇ⁠máẕá֣ʼţá ʼeţ-lĕbáb⁠wò֮ neʼèmá֣n lĕ⁠páney⁠ká֒ wĕ⁠kár֨wòţ ʻiṁ֜⁠wò ha⁠bĕ̇ri֗yţ lá⁠ţé֡ţ ʼeţ-ʼereẕ֩ ha⁠kĕ̇naʻàni֨y ha⁠ẖiţi̇֜y há⁠ʼèmòri֧y wĕ⁠ha⁠pĕ̇rizi֛̇y wĕ⁠ha⁠yĕbẇsi֥y wĕ⁠ha⁠gi̇rĕgá̇şǐ֖y lá⁠ţé֣ţ lĕ⁠zarĕʻ֑⁠wò wa⁠ţá̇֨qem֙ ʼeţ-dĕ̇báre֔y⁠ká ki֥̇y ẕadi֖̇yq ʼáֽţá̇h׃"],[9,9,"וַ⁠תֵּ֛רֶא אֶת־עֳנִ֥י אֲבֹתֵ֖י⁠נוּ בְּ⁠מִצְרָ֑יִם וְ⁠אֶת־זַעֲקָתָ֥⁠ם שָׁמַ֖עְתָּ עַל־יַם־סֽוּף׃","wa⁠ţé֛̇reʼ ʼeţ-ʻoni֥y ʼàbòţé֖y⁠nẇ bĕ̇⁠miẕĕrá֑yim wĕ⁠ʼeţ-zaʻàqáţá֥⁠m şá̌ma֖ʻĕţá̇ ʻal-yam-sֽẇp׃"],[9,10,"וַ֠⁠תִּתֵּן אֹתֹ֨ת וּ⁠מֹֽפְתִ֜ים בְּ⁠פַרְעֹ֤ה וּ⁠בְ⁠כָל־עֲבָדָי⁠ו֙ וּ⁠בְ⁠כָל־עַ֣ם אַרְצ֔⁠וֹ כִּ֣י יָדַ֔עְתָּ כִּ֥י הֵזִ֖ידוּ עֲלֵי⁠הֶ֑ם וַ⁠תַּֽעַשׂ־לְ⁠ךָ֥ שֵׁ֖ם כְּ⁠הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa֠⁠ţi̇ţé̇n ʼòţò֨ţ ẇ⁠mòֽpĕţi֜ym bĕ̇⁠parĕʻò֤h ẇ⁠bĕ⁠kál-ʻàbádáy⁠w֙ ẇ⁠bĕ⁠kál-ʻa֣m ʼarĕẕ֔⁠wò ki֣̇y yáda֔ʻĕţá̇ ki֥̇y hézi֖ydẇ ʻàléy⁠he֑m wa⁠ţȧֽʻaş̂-lĕ⁠ká֥ şé֖̌m kĕ̇⁠ha⁠ẏ֥wòm ha⁠zėֽh׃"],[9,11,"וְ⁠הַ⁠יָּם֙ בָּקַ֣עְתָּ לִ⁠פְנֵי⁠הֶ֔ם וַ⁠יַּֽעַבְר֥וּ בְ⁠תוֹךְ־הַ⁠יָּ֖ם בַּ⁠יַּבָּשָׁ֑ה וְֽ⁠אֶת־רֹ֨דְפֵי⁠הֶ֜ם הִשְׁלַ֧כְתָּ בִ⁠מְצוֹלֹ֛ת כְּמוֹ־אֶ֖בֶן בְּ⁠מַ֥יִם עַזִּֽים׃","wĕ⁠ha⁠yá̇m֙ bá̇qa֣ʻĕţá̇ li⁠pĕnéy⁠he֔m wa⁠yȧֽʻabĕr֥ẇ bĕ⁠ţwòkĕ-ha⁠yá֖̇m bȧ⁠yȧbá̇şá֑̌h wĕֽ⁠ʼeţ-rò֨dĕpéy⁠he֜m hişĕ̌la֧kĕţá̇ bi⁠mĕẕwòlò֛ţ kĕ̇mwò-ʼe֖ben bĕ̇⁠ma֥yim ʻaziֽ̇ym׃"],[9,12,"וּ⁠בְ⁠עַמּ֣וּד עָנָ֔ן הִנְחִיתָ֖⁠ם יוֹמָ֑ם וּ⁠בְ⁠עַמּ֥וּד אֵשׁ֙ לַ֔יְלָה לְ⁠הָאִ֣יר לָ⁠הֶ֔ם אֶת־הַ⁠דֶּ֖רֶךְ אֲשֶׁ֥ר יֵֽלְכוּ־בָֽ⁠הּ׃","ẇ⁠bĕ⁠ʻaṁ֣ẇd ʻáná֔n hinĕẖiyţá֖⁠m ywòmá֑m ẇ⁠bĕ⁠ʻaṁ֥ẇd ʼéş̌֙ la֔yĕláh lĕ⁠háʼi֣yr lá⁠he֔m ʼeţ-ha⁠dė֖rekĕ ʼàşě֥r yéֽlĕkẇ-báֽ⁠ḣ׃"],[9,13,"וְ⁠עַ֤ל הַר־סִינַי֙ יָרַ֔דְתָּ וְ⁠דַבֵּ֥ר עִמָּ⁠הֶ֖ם מִ⁠שָּׁמָ֑יִם וַ⁠תִּתֵּ֨ן לָ⁠הֶ֜ם מִשְׁפָּטִ֤ים יְשָׁרִים֙ וְ⁠תוֹר֣וֹת אֱמֶ֔ת חֻקִּ֥ים וּ⁠מִצְוֺ֖ת טוֹבִֽים׃","wĕ⁠ʻa֤l har-siynay֙ yára֔dĕţá̇ wĕ⁠dabé֥̇r ʻimá̇⁠he֖m mi⁠şá̇̌má֑yim wa⁠ţi̇ţé̇֨n lá⁠he֜m mişĕ̌pá̇ti֤ym yĕşá̌riym֙ wĕ⁠ţwòr֣wòţ ʼème֔ţ ẖuqi֥̇ym ẇ⁠miẕĕwֺ֖ţ twòbiֽym׃"],[9,14,"וְ⁠אֶת־שַׁבַּ֥ת קָדְשְׁ⁠ךָ֖ הוֹדַ֣עַתָ לָ⁠הֶ֑ם וּ⁠מִצְו֤וֹת וְ⁠חֻקִּים֙ וְ⁠תוֹרָ֔ה צִוִּ֣יתָ לָ⁠הֶ֔ם בְּ⁠יַ֖ד מֹשֶׁ֥ה עַבְדֶּֽ⁠ךָ׃","wĕ⁠ʼeţ-şǎbȧ֥ţ qádĕşĕ̌⁠ká֖ hwòda֣ʻaţá lá⁠he֑m ẇ⁠miẕĕw֤wòţ wĕ⁠ẖuqi̇ym֙ wĕ⁠ţwòrá֔h ẕiwi֣̇yţá lá⁠he֔m bĕ̇⁠ya֖d mòşě֥h ʻabĕdėֽ⁠ká׃"],[9,15,"וְ֠⁠לֶחֶם מִ⁠שָּׁמַ֜יִם נָתַ֤תָּה לָ⁠הֶם֙ לִ⁠רְעָבָ֔⁠ם וּ⁠מַ֗יִם מִ⁠סֶּ֛לַע הוֹצֵ֥אתָ לָ⁠הֶ֖ם לִ⁠צְמָאָ֑⁠ם וַ⁠תֹּ֣אמֶר לָ⁠הֶ֗ם לָ⁠בוֹא֙ לָ⁠רֶ֣שֶׁת אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר־נָשָׂ֥אתָ אֶת־יָדְ⁠ךָ֖ לָ⁠תֵ֥ת לָ⁠הֶֽם׃","wĕ֠⁠leẖem mi⁠şá̇̌ma֜yim náţa֤ţá̇h lá⁠hem֙ li⁠rĕʻábá֔⁠m ẇ⁠ma֗yim mi⁠sė֛laʻ hwòẕé֥ʼţá lá⁠he֖m li⁠ẕĕmáʼá֑⁠m wa⁠ţò֣̇ʼmer lá⁠he֗m lá⁠bwòʼ֙ lá⁠re֣şěţ ʼeţ-há⁠ʼá֔reẕ ʼàşěr-náşá֥̂ʼţá ʼeţ-yádĕ⁠ká֖ lá⁠ţé֥ţ lá⁠heֽm׃"],[9,16,"וְ⁠הֵ֥ם וַ⁠אֲבֹתֵ֖י⁠נוּ הֵזִ֑ידוּ וַ⁠יַּקְשׁוּ֙ אֶת־עָרְפָּ֔⁠ם וְ⁠לֹ֥א שָׁמְע֖וּ אֶל־מִצְוֺתֶֽי⁠ךָ׃","wĕ⁠hé֥m wa⁠ʼàbòţé֖y⁠nẇ hézi֑ydẇ wa⁠yȧqĕş̌ẇ֙ ʼeţ-ʻárĕpá̇֔⁠m wĕ⁠lò֥ʼ şá̌mĕʻ֖ẇ ʼel-miẕĕwֺţeֽy⁠ká׃"],[9,17,"וַ⁠יְמָאֲנ֣וּ לִ⁠שְׁמֹ֗עַ וְ⁠לֹא־זָכְר֤וּ נִפְלְאֹתֶ֨י⁠ךָ֙ אֲשֶׁ֣ר עָשִׂ֣יתָ עִמָּ⁠הֶ֔ם וַ⁠יַּקְשׁוּ֙ אֶת־עָרְפָּ֔⁠ם וַ⁠יִּתְּנוּ־רֹ֛אשׁ לָ⁠שׁ֥וּב לְ⁠עַבְדֻתָ֖⁠ם בְּ⁠מִרְיָ֑⁠ם וְ⁠אַתָּה֩ אֱל֨וֹהַּ סְלִיח֜וֹת חַנּ֧וּן וְ⁠רַח֛וּם אֶֽרֶךְ־אַפַּ֥יִם וְ⁠רַב־ו⁠חסד וְ⁠לֹ֥א עֲזַבְתָּֽ⁠ם׃","wa⁠yĕmáʼàn֣ẇ li⁠şĕ̌mò֗ʻa wĕ⁠lòʼ-zákĕr֤ẇ nipĕlĕʼòţe֨y⁠ká֙ ʼàşě֣r ʻáşî֣yţá ʻimá̇⁠he֔m wa⁠yȧqĕş̌ẇ֙ ʼeţ-ʻárĕpá̇֔⁠m wa⁠yi̇ţĕ̇nẇ-rò֛ʼş̌ lá⁠ş֥̌ẇb lĕ⁠ʻabĕduţá֖⁠m bĕ̇⁠mirĕyá֑⁠m wĕ⁠ʼaţá̇h֩ ʼèl֨wòhȧ sĕliyẖ֜wòţ ẖaṅ֧ẇn wĕ⁠raẖ֛ẇm ʼeֽrekĕ-ʼapȧ֥yim wĕ⁠rab-w⁠ẖsd wĕ⁠lò֥ʼ ʻàzabĕţáֽ̇⁠m׃"],[9,18,"אַ֗ף כִּֽי־עָשׂ֤וּ לָ⁠הֶם֙ עֵ֣גֶל מַסֵּכָ֔ה וַ⁠יֹּ֣אמְר֔וּ זֶ֣ה אֱלֹהֶ֔י⁠ךָ אֲשֶׁ֥ר הֶעֶלְ⁠ךָ֖ מִ⁠מִּצְרָ֑יִם וַֽ⁠יַּעֲשׂ֔וּ נֶאָצ֖וֹת גְּדֹלֽוֹת׃","ʼa֗p kiֽ̇y-ʻáş֤̂ẇ lá⁠hem֙ ʻé֣gel masé̇ká֔h wa⁠yò֣̇ʼmĕr֔ẇ ze֣h ʼèlòhe֔y⁠ká ʼàşě֥r heʻelĕ⁠ká֖ mi⁠mi̇ẕĕrá֑yim wֽa⁠yȧʻàş̂֔ẇ neʼáẕ֖wòţ gĕ̇dòlֽwòţ׃"],[9,19,"וְ⁠אַתָּה֙ בְּ⁠רַחֲמֶ֣י⁠ךָ הָֽ⁠רַבִּ֔ים לֹ֥א עֲזַבְתָּ֖⁠ם בַּ⁠מִּדְבָּ֑ר אֶת־עַמּ֣וּד הֶ֠⁠עָנָן לֹא־סָ֨ר מֵ⁠עֲלֵי⁠הֶ֤ם בְּ⁠יוֹמָם֙ לְ⁠הַנְחֹתָ֣⁠ם בְּ⁠הַ⁠דֶּ֔רֶךְ וְ⁠אֶת־עַמּ֨וּד הָ⁠אֵ֤שׁ בְּ⁠לַ֨יְלָה֙ לְ⁠הָאִ֣יר לָ⁠הֶ֔ם וְ⁠אֶת־הַ⁠דֶּ֖רֶךְ אֲשֶׁ֥ר יֵֽלְכוּ־בָֽ⁠הּ׃","wĕ⁠ʼaţá̇h֙ bĕ̇⁠raẖàme֣y⁠ká háֽ⁠rabi̇֔ym lò֥ʼ ʻàzabĕţá֖̇⁠m bȧ⁠mi̇dĕbá֑̇r ʼeţ-ʻaṁ֣ẇd he֠⁠ʻánán lòʼ-sá֨r mé⁠ʻàléy⁠he֤m bĕ̇⁠ywòmám֙ lĕ⁠hanĕẖòţá֣⁠m bĕ̇⁠ha⁠dė֔rekĕ wĕ⁠ʼeţ-ʻaṁ֨ẇd há⁠ʼé֤ş̌ bĕ̇⁠la֨yĕláh֙ lĕ⁠háʼi֣yr lá⁠he֔m wĕ⁠ʼeţ-ha⁠dė֖rekĕ ʼàşě֥r yéֽlĕkẇ-báֽ⁠ḣ׃"],[9,20,"וְ⁠רוּחֲ⁠ךָ֨ הַ⁠טּוֹבָ֔ה נָתַ֖תָּ לְ⁠הַשְׂכִּילָ֑⁠ם וּ⁠מַנְ⁠ךָ֙ לֹא־מָנַ֣עְתָּ מִ⁠פִּי⁠הֶ֔ם וּ⁠מַ֛יִם נָתַ֥תָּה לָ⁠הֶ֖ם לִ⁠צְמָאָֽ⁠ם׃","wĕ⁠rẇẖà⁠ká֨ ha⁠ṫwòbá֔h náţa֖ţá̇ lĕ⁠haşĕ̂ki̇ylá֑⁠m ẇ⁠manĕ⁠ká֙ lòʼ-mána֣ʻĕţá̇ mi⁠pi̇y⁠he֔m ẇ⁠ma֛yim náţa֥ţá̇h lá⁠he֖m li⁠ẕĕmáʼáֽ⁠m׃"],[9,21,"וְ⁠אַרְבָּעִ֥ים שָׁנָ֛ה כִּלְכַּלְתָּ֥⁠ם בַּ⁠מִּדְבָּ֖ר לֹ֣א חָסֵ֑רוּ שַׂלְמֹֽתֵי⁠הֶם֙ לֹ֣א בָל֔וּ וְ⁠רַגְלֵי⁠הֶ֖ם לֹ֥א בָצֵֽקוּ׃","wĕ⁠ʼarĕbá̇ʻi֥ym şá̌ná֛h ki̇lĕkȧlĕţá֥̇⁠m bȧ⁠mi̇dĕbá֖̇r lò֣ʼ ẖásé֑rẇ şâlĕmòֽţéy⁠hem֙ lò֣ʼ bál֔ẇ wĕ⁠ragĕléy⁠he֖m lò֥ʼ báẕéֽqẇ׃"],[9,22,"וַ⁠תִּתֵּ֨ן לָ⁠הֶ֤ם מַמְלָכוֹת֙ וַ⁠עֲמָמִ֔ים וַֽ⁠תַּחְלְקֵ֖⁠ם לְ⁠פֵאָ֑ה וַ⁠יִּֽירְשׁ֞וּ אֶת־אֶ֣רֶץ סִיח֗וֹן וְ⁠אֶת־אֶ֨רֶץ֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן וְ⁠אֶת־אֶ֖רֶץ ע֥וֹג מֶֽלֶךְ־הַ⁠בָּשָֽׁן׃","wa⁠ţi̇ţé̇֨n lá⁠he֤m mamĕlákwòţ֙ wa⁠ʻàmámi֔ym waֽ⁠ţȧẖĕlĕqé֖⁠m lĕ⁠péʼá֑h wa⁠yiֽ̇yrĕş̌֞ẇ ʼeţ-ʼe֣reẕ siyẖ֗wòn wĕ⁠ʼeţ-ʼe֨reẕ֙ me֣lekĕ ẖeşĕ̌ḃ֔wòn wĕ⁠ʼeţ-ʼe֖reẕ ʻ֥wòg meֽlekĕ-ha⁠bá̇şáֽ̌n׃"],[9,23,"וּ⁠בְנֵי⁠הֶ֣ם הִרְבִּ֔יתָ כְּ⁠כֹכְבֵ֖י הַ⁠שָּׁמָ֑יִם וַ⁠תְּבִיאֵ⁠ם֙ אֶל־הָ⁠אָ֔רֶץ אֲשֶׁר־אָמַ֥רְתָּ לַ⁠אֲבֹתֵי⁠הֶ֖ם לָ⁠ב֥וֹא לָ⁠רָֽשֶׁת׃","ẇ⁠bĕnéy⁠he֣m hirĕbi̇֔yţá kĕ̇⁠kòkĕbé֖y ha⁠şá̇̌má֑yim wa⁠ţĕ̇biyʼé⁠m֙ ʼel-há⁠ʼá֔reẕ ʼàşěr-ʼáma֥rĕţá̇ la⁠ʼàbòţéy⁠he֖m lá⁠b֥wòʼ lá⁠ráֽşěţ׃"],[9,24,"וַ⁠יָּבֹ֤אוּ הַ⁠בָּנִים֙ וַ⁠יִּֽירְשׁ֣וּ אֶת־הָ⁠אָ֔רֶץ וַ⁠תַּכְנַ֨ע לִ⁠פְנֵי⁠הֶ֜ם אֶת־יֹשְׁבֵ֤י הָ⁠אָ֨רֶץ֙ הַ⁠כְּנַ֣עֲנִ֔ים וַֽ⁠תִּתְּנֵ֖⁠ם בְּ⁠יָדָ֑⁠ם וְ⁠אֶת־מַלְכֵי⁠הֶם֙ וְ⁠אֶת־עַֽמְמֵ֣י הָ⁠אָ֔רֶץ לַ⁠עֲשׂ֥וֹת בָּ⁠הֶ֖ם כִּ⁠רְצוֹנָֽ⁠ם׃","wa⁠yá̇bò֤ʼẇ ha⁠bá̇niym֙ wa⁠yiֽ̇yrĕş֣̌ẇ ʼeţ-há⁠ʼá֔reẕ wa⁠ţȧkĕna֨ʻ li⁠pĕnéy⁠he֜m ʼeţ-yòşĕ̌bé֤y há⁠ʼá֨reẕ֙ ha⁠kĕ̇na֣ʻàni֔ym waֽ⁠ţi̇ţĕ̇né֖⁠m bĕ̇⁠yádá֑⁠m wĕ⁠ʼeţ-malĕkéy⁠hem֙ wĕ⁠ʼeţ-ʻaֽmĕmé֣y há⁠ʼá֔reẕ la⁠ʻàş֥̂wòţ bá̇⁠he֖m ki̇⁠rĕẕwònáֽ⁠m׃"],[9,25,"וַֽ⁠יִּלְכְּד֞וּ עָרִ֣ים בְּצֻרוֹת֮ וַ⁠אֲדָמָ֣ה שְׁמֵנָה֒ וַ⁠יִּֽירְשׁ֡וּ בָּתִּ֣ים מְלֵֽאִים־כָּל־ט֠וּב בֹּר֨וֹת חֲצוּבִ֜ים כְּרָמִ֧ים וְ⁠זֵיתִ֛ים וְ⁠עֵ֥ץ מַאֲכָ֖ל לָ⁠רֹ֑ב וַ⁠יֹּאכְל֤וּ וַֽ⁠יִּשְׂבְּעוּ֙ וַ⁠יַּשְׁמִ֔ינוּ וַ⁠יִּֽתְעַדְּנ֖וּ בְּ⁠טוּבְ⁠ךָ֥ הַ⁠גָּדֽוֹל׃","waֽ⁠yi̇lĕkĕ̇d֞ẇ ʻári֣ym bĕ̇ẕurwòţ֮ wa⁠ʼàdámá֣h şĕ̌ménáh֒ wa⁠yiֽ̇yrĕş̌֡ẇ bá̇ţi֣̇ym mĕléֽʼiym-ká̇l-t֠ẇb bò̇r֨wòţ ẖàẕẇbi֜ym kĕ̇rámi֧ym wĕ⁠zéyţi֛ym wĕ⁠ʻé֥ẕ maʼàká֖l lá⁠rò֑b wa⁠yò̇ʼkĕl֤ẇ waֽ⁠yi̇şĕ̂bĕ̇ʻẇ֙ wa⁠yȧşĕ̌mi֔ynẇ wa⁠yiֽ̇ţĕʻadĕ̇n֖ẇ bĕ̇⁠tẇbĕ⁠ká֥ ha⁠gá̇dֽwòl׃"],[9,26,"וַ⁠יַּמְר֨וּ וַֽ⁠יִּמְרְד֜וּ בָּ֗⁠ךְ וַ⁠יַּשְׁלִ֤כוּ אֶת־תּוֹרָֽתְ⁠ךָ֙ אַחֲרֵ֣י גַוָּ֔⁠ם וְ⁠אֶת־נְבִיאֶ֣י⁠ךָ הָרָ֔גוּ אֲשֶׁר־הֵעִ֥ידוּ בָ֖⁠ם לַ⁠הֲשִׁיבָ֣⁠ם אֵלֶ֑י⁠ךָ וַֽ⁠יַּעֲשׂ֔וּ נֶאָצ֖וֹת גְּדוֹלֹֽת׃","wa⁠yȧmĕr֨ẇ waֽ⁠yi̇mĕrĕd֜ẇ bá̇֗⁠kĕ wa⁠yȧşĕ̌li֤kẇ ʼeţ-ţ̇wòráֽţĕ⁠ká֙ ʼaẖàré֣y gawá̇֔⁠m wĕ⁠ʼeţ-nĕbiyʼe֣y⁠ká hárá֔gẇ ʼàşěr-héʻi֥ydẇ bá֖⁠m la⁠hàşǐybá֣⁠m ʼéle֑y⁠ká wֽa⁠yȧʻàş̂֔ẇ neʼáẕ֖wòţ gĕ̇dwòlòֽţ׃"],[9,27,"וַֽ⁠תִּתְּנֵ⁠ם֙ בְּ⁠יַ֣ד צָֽרֵי⁠הֶ֔ם וַ⁠יָּצֵ֖רוּ לָ⁠הֶ֑ם וּ⁠בְ⁠עֵ֤ת צָֽרָתָ⁠ם֙ יִצְעֲק֣וּ אֵלֶ֔י⁠ךָ וְ⁠אַתָּה֙ מִ⁠שָּׁמַ֣יִם תִּשְׁמָ֔ע וּֽ⁠כְ⁠רַחֲמֶ֣י⁠ךָ הָֽ⁠רַבִּ֗ים תִּתֵּ֤ן לָ⁠הֶם֙ מֽוֹשִׁיעִ֔ים וְ⁠יוֹשִׁיע֖וּ⁠ם מִ⁠יַּ֥ד צָרֵי⁠הֶֽם׃","waֽ⁠ţi̇ţĕ̇né⁠m֙ bĕ̇⁠ya֣d ẕáֽréy⁠he֔m wa⁠yá̇ẕé֖rẇ lá⁠he֑m ẇ⁠bĕ⁠ʻé֤ţ ẕáֽráţá⁠m֙ yiẕĕʻàq֣ẇ ʼéle֔y⁠ká wĕ⁠ʼaţá̇h֙ mi⁠şá̇̌ma֣yim ţi̇şĕ̌má֔ʻ ẇֽ⁠kĕ⁠raẖàme֣y⁠ká háֽ⁠rabi̇֗ym ţi̇ţé֤̇n lá⁠hem֙ mֽwòşǐyʻi֔ym wĕ⁠ywòşǐyʻ֖ẇ⁠m mi⁠yȧ֥d ẕáréy⁠heֽm׃"],[9,28,"וּ⁠כְ⁠נ֣וֹחַ לָ⁠הֶ֔ם יָשׁ֕וּבוּ לַ⁠עֲשׂ֥וֹת רַ֖ע לְ⁠פָנֶ֑י⁠ךָ וַ⁠תַּֽעַזְבֵ֞⁠ם בְּ⁠יַ֤ד אֹֽיְבֵי⁠הֶם֙ וַ⁠יִּרְדּ֣וּ בָ⁠הֶ֔ם וַ⁠יָּשׁ֨וּבוּ֙ וַ⁠יִּזְעָק֔וּ⁠ךָ וְ⁠אַתָּ֞ה מִ⁠שָּׁמַ֧יִם תִּשְׁמַ֛ע וְ⁠תַצִּילֵ֥⁠ם כְּֽ⁠רַחֲמֶ֖י⁠ךָ רַבּ֥וֹת עִתִּֽים׃","ẇ⁠kĕ⁠n֣wòẖa lá⁠he֔m yáş̌֕ẇbẇ la⁠ʻàş֥̂wòţ ra֖ʻ lĕ⁠páne֑y⁠ká wa⁠ţȧֽʻazĕbé֞⁠m bĕ̇⁠ya֤d ʼòֽyĕbéy⁠hem֙ wa⁠yi̇rĕḋ֣ẇ bá⁠he֔m wa⁠yá̇ş̌֨ẇbẇ֙ wa⁠yi̇zĕʻáq֔ẇ⁠ká wĕ⁠ʼaţá̇֞h mi⁠şá̇̌ma֧yim ţi̇şĕ̌ma֛ʻ wĕ⁠ţaẕi̇ylé֥⁠m kĕֽ̇⁠raẖàme֖y⁠ká raḃ֥wòţ ʻiţiֽ̇ym׃"],[9,29,"וַ⁠תָּ֨עַד בָּ⁠הֶ֜ם לַ⁠הֲשִׁיבָ֣⁠ם אֶל־תּוֹרָתֶ֗⁠ךָ וְ⁠הֵ֨מָּה הֵזִ֜ידוּ וְ⁠לֹא־שָׁמְע֤וּ לְ⁠מִצְוֺתֶ֨י⁠ךָ֙ וּ⁠בְ⁠מִשְׁפָּטֶ֣י⁠ךָ חָֽטְאוּ־בָ֔⁠ם אֲשֶׁר־יַעֲשֶׂ֥ה אָדָ֖ם וְ⁠חָיָ֣ה בָ⁠הֶ֑ם וַ⁠יִּתְּנ֤וּ כָתֵף֙ סוֹרֶ֔רֶת וְ⁠עָרְפָּ֥⁠ם הִקְשׁ֖וּ וְ⁠לֹ֥א שָׁמֵֽעוּ׃","wa⁠ţá̇֨ʻad bá̇⁠he֜m la⁠hàşǐybá֣⁠m ʼel-ţ̇wòráţe֗⁠ká wĕ⁠hé֨má̇h hézi֜ydẇ wĕ⁠lòʼ-şá̌mĕʻ֤ẇ lĕ⁠miẕĕwֺţe֨y⁠ká֙ ẇ⁠bĕ⁠mişĕ̌pá̇te֣y⁠ká ẖáֽtĕʼẇ-bá֔⁠m ʼàşěr-yaʻàşê֥h ʼádá֖m wĕ⁠ẖáyá֣h bá⁠he֑m wa⁠yi̇ţĕ̇n֤ẇ káţép֙ swòre֔reţ wĕ⁠ʻárĕpá֥̇⁠m hiqĕş֖̌ẇ wĕ⁠lò֥ʼ şá̌méֽʻẇ׃"],[9,30,"וַ⁠תִּמְשֹׁ֤ךְ עֲלֵי⁠הֶם֙ שָׁנִ֣ים רַבּ֔וֹת וַ⁠תָּ֨עַד בָּ֧⁠ם בְּ⁠רוּחֲ⁠ךָ֛ בְּ⁠יַד־נְבִיאֶ֖י⁠ךָ וְ⁠לֹ֣א הֶאֱזִ֑ינוּ וַֽ⁠תִּתְּנֵ֔⁠ם בְּ⁠יַ֖ד עַמֵּ֥י הָ⁠אֲרָצֹֽת׃","wa⁠ţi̇mĕşò֤̌kĕ ʻàléy⁠hem֙ şá̌ni֣ym raḃ֔wòţ wa⁠ţá̇֨ʻad bá֧̇⁠m bĕ̇⁠rẇẖà⁠ká֛ bĕ̇⁠yad-nĕbiyʼe֖y⁠ká wĕ⁠lò֣ʼ heʼèzi֑ynẇ waֽ⁠ţi̇ţĕ̇né֔⁠m bĕ̇⁠ya֖d ʻamé֥̇y há⁠ʼàráẕòֽţ׃"],[9,31,"וּֽ⁠בְ⁠רַחֲמֶ֧י⁠ךָ הָ⁠רַבִּ֛ים לֹֽא־עֲשִׂיתָ֥⁠ם כָּלָ֖ה וְ⁠לֹ֣א עֲזַבְתָּ֑⁠ם כִּ֛י אֵֽל־חַנּ֥וּן וְ⁠רַח֖וּם אָֽתָּה׃","ẇֽ⁠bĕ⁠raẖàme֧y⁠ká há⁠rabi֛̇ym lòֽʼ-ʻàşîyţá֥⁠m ká̇lá֖h wĕ⁠lò֣ʼ ʻàzabĕţá֑̇⁠m ki֛̇y ʼéֽl-ẖaṅ֥ẇn wĕ⁠raẖ֖ẇm ʼáֽţá̇h׃"],[9,32,"וְ⁠עַתָּ֣ה אֱ֠לֹהֵי⁠נוּ הָ⁠אֵ֨ל הַ⁠גָּד֜וֹל הַ⁠גִּבּ֣וֹר וְ⁠הַ⁠נּוֹרָא֮ שׁוֹמֵ֣ר הַ⁠בְּרִ֣ית וְ⁠הַ⁠חֶסֶד֒ אַל־יִמְעַ֣ט לְ⁠פָנֶ֡י⁠ךָ אֵ֣ת כָּל־הַ⁠תְּלָאָ֣ה אֲֽשֶׁר־מְ֠צָאַתְ⁠נוּ לִ⁠מְלָכֵ֨י⁠נוּ לְ⁠שָׂרֵ֧י⁠נוּ וּ⁠לְ⁠כֹהֲנֵ֛י⁠נוּ וְ⁠לִ⁠נְבִיאֵ֥⁠נוּ וְ⁠לַ⁠אֲבֹתֵ֖י⁠נוּ וּ⁠לְ⁠כָל־עַמֶּ֑⁠ךָ מִ⁠ימֵי֙ מַלְכֵ֣י אַשּׁ֔וּר עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠ʻaţá֣̇h ʼè֠lòhéy⁠nẇ há⁠ʼé֨l ha⁠gá̇d֜wòl ha⁠gi̇ḃ֣wòr wĕ⁠ha⁠ṅwòráʼ֮ ş̌wòmé֣r ha⁠bĕ̇ri֣yţ wĕ⁠ha⁠ẖesed֒ ʼal-yimĕʻa֣t lĕ⁠páne֡y⁠ká ʼé֣ţ ká̇l-ha⁠ţĕ̇láʼá֣h ʼֽàşěr-mĕ֠ẕáʼaţĕ⁠nẇ li⁠mĕláké֨y⁠nẇ lĕ⁠şá̂ré֧y⁠nẇ ẇ⁠lĕ⁠kòhàné֛y⁠nẇ wĕ⁠li⁠nĕbiyʼé֥⁠nẇ wĕ⁠la⁠ʼàbòţé֖y⁠nẇ ẇ⁠lĕ⁠kál-ʻamė֑⁠ká mi⁠yméy֙ malĕké֣y ʼaş̇̌֔ẇr ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[9,33,"וְ⁠אַתָּ֣ה צַדִּ֔יק עַ֖ל כָּל־הַ⁠בָּ֣א עָלֵ֑י⁠נוּ כִּֽי־אֱמֶ֥ת עָשִׂ֖יתָ וַ⁠אֲנַ֥חְנוּ הִרְשָֽׁעְנוּ׃","wĕ⁠ʼaţá֣̇h ẕadi̇֔yq ʻa֖l ká̇l-ha⁠bá֣̇ʼ ʻálé֑y⁠nẇ kiֽ̇y-ʼème֥ţ ʻáşî֖yţá wa⁠ʼàna֥ẖĕnẇ hirĕşáֽ̌ʻĕnẇ׃"],[9,34,"וְ⁠אֶת־מְלָכֵ֤י⁠נוּ שָׂרֵ֨י⁠נוּ֙ כֹּהֲנֵ֣י⁠נוּ וַ⁠אֲבֹתֵ֔י⁠נוּ לֹ֥א עָשׂ֖וּ תּוֹרָתֶ֑⁠ךָ וְ⁠לֹ֤א הִקְשִׁ֨יבוּ֙ אֶל־מִצְוֺתֶ֔י⁠ךָ וּ⁠לְ⁠עֵ֣דְוֺתֶ֔י⁠ךָ אֲשֶׁ֥ר הַעִידֹ֖תָ בָּ⁠הֶֽם׃","wĕ⁠ʼeţ-mĕláké֤y⁠nẇ şá̂ré֨y⁠nẇ֙ kò̇hàné֣y⁠nẇ wa⁠ʼàbòţé֔y⁠nẇ lò֥ʼ ʻáş֖̂ẇ ţ̇wòráţe֑⁠ká wĕ⁠lò֤ʼ hiqĕşǐ֨ybẇ֙ ʼel-miẕĕwֺţe֔y⁠ká ẇ⁠lĕ⁠ʻé֣dĕwֺţe֔y⁠ká ʼàşě֥r haʻiydò֖ţá bá̇⁠heֽm׃"],[9,35,"וְ⁠הֵ֣ם בְּ⁠מַלְכוּתָ⁠ם֩ וּ⁠בְ⁠טוּבְ⁠ךָ֨ הָ⁠רָ֜ב אֲשֶׁר־נָתַ֣תָּ לָ⁠הֶ֗ם וּ⁠בְ⁠אֶ֨רֶץ הָ⁠רְחָבָ֧ה וְ⁠הַ⁠שְּׁמֵנָ֛ה אֲשֶׁר־נָתַ֥תָּ לִ⁠פְנֵי⁠הֶ֖ם לֹ֣א עֲבָד֑וּ⁠ךָ וְֽ⁠לֹא־שָׁ֔בוּ מִ⁠מַּֽעַלְלֵי⁠הֶ֖ם הָ⁠רָעִֽים׃","wĕ⁠hé֣m bĕ̇⁠malĕkẇţá⁠m֩ ẇ⁠bĕ⁠tẇbĕ⁠ká֨ há⁠rá֜b ʼàşěr-náţa֣ţá̇ lá⁠he֗m ẇ⁠bĕ⁠ʼe֨reẕ há⁠rĕẖábá֧h wĕ⁠ha⁠şĕ̇̌méná֛h ʼàşěr-náţa֥ţá̇ li⁠pĕnéy⁠he֖m lò֣ʼ ʻàbád֑ẇ⁠ká wĕֽ⁠lòʼ-şá̌֔bẇ mi⁠mȧֽʻalĕléy⁠he֖m há⁠ráʻiֽym׃"],[9,36,"הִנֵּ֛ה אֲנַ֥חְנוּ הַ⁠יּ֖וֹם עֲבָדִ֑ים וְ⁠הָ⁠אָ֜רֶץ אֲשֶׁר־נָתַ֣תָּה לַ⁠אֲבֹתֵ֗י⁠נוּ לֶ⁠אֱכֹ֤ל אֶת־פִּרְיָ⁠הּ֙ וְ⁠אֶת־טוּבָ֔⁠הּ הִנֵּ֛ה אֲנַ֥חְנוּ עֲבָדִ֖ים עָלֶֽי⁠הָ׃","hiné֛̇h ʼàna֥ẖĕnẇ ha⁠ẏ֖wòm ʻàbádi֑ym wĕ⁠há⁠ʼá֜reẕ ʼàşěr-náţa֣ţá̇h la⁠ʼàbòţé֗y⁠nẇ le⁠ʼèkò֤l ʼeţ-pi̇rĕyá⁠ḣ֙ wĕ⁠ʼeţ-tẇbá֔⁠ḣ hiné֛̇h ʼàna֥ẖĕnẇ ʻàbádi֖ym ʻáleֽy⁠há׃"],[9,37,"וּ⁠תְבוּאָתָ֣⁠הּ מַרְבָּ֗ה לַ⁠מְּלָכִ֛ים אֲשֶׁר־נָתַ֥תָּה עָלֵ֖י⁠נוּ בְּ⁠חַטֹּאותֵ֑י⁠נוּ וְ⁠עַ֣ל גְּ֠וִיֹּתֵי⁠נוּ מֹשְׁלִ֤ים וּ⁠בִ⁠בְהֶמְתֵּ֨⁠נוּ֙ כִּ⁠רְצוֹנָ֔⁠ם וּ⁠בְ⁠צָרָ֥ה גְדוֹלָ֖ה אֲנָֽחְנוּ׃פ","ẇ⁠ţĕbẇʼáţá֣⁠ḣ marĕbá̇֗h la⁠mĕ̇láki֛ym ʼàşěr-náţa֥ţá̇h ʻálé֖y⁠nẇ bĕ̇⁠ẖatò̇ʼwţé֑y⁠nẇ wĕ⁠ʻa֣l gĕ̇֠wiyò̇ţéy⁠nẇ mòşĕ̌li֤ym ẇ⁠bi⁠bĕhemĕţé̇֨⁠nẇ֙ ki̇⁠rĕẕwòná֔⁠m ẇ⁠bĕ⁠ẕárá֥h gĕdwòlá֖h ʼànáֽẖĕnẇ׃p"],[9,38,"וּ⁠בְ⁠כָל־זֹ֕את אֲנַ֛חְנוּ כֹּרְתִ֥ים אֲמָנָ֖ה וְ⁠כֹתְבִ֑ים וְ⁠עַל֙ הֶֽ⁠חָת֔וּם שָׂרֵ֥י⁠נוּ לְוִיֵּ֖⁠נוּ כֹּהֲנֵֽי⁠נוּ׃","ẇ⁠bĕ⁠kál-zò֕ʼţ ʼàna֛ẖĕnẇ kò̇rĕţi֥ym ʼàmáná֖h wĕ⁠kòţĕbi֑ym wĕ⁠ʻal֙ heֽ⁠ẖáţ֔ẇm şá̂ré֥y⁠nẇ lĕwiyé֖̇⁠nẇ kò̇hànéֽy⁠nẇ׃"],[10,1,"וְ⁠עַ֖ל הַ⁠חֲתוּמִ֑ים נְחֶמְיָ֧ה הַ⁠תִּרְשָׁ֛תָא בֶּן־חֲכַלְיָ֖ה וְ⁠צִדְקִיָּֽה׃","wĕ⁠ʻa֖l ha⁠ẖàţẇmi֑ym nĕẖemĕyá֧h ha⁠ţi̇rĕşá֛̌ţáʼ bėn-ẖàkalĕyá֖h wĕ⁠ẕidĕqiyáֽ̇h׃"],[10,2,"שְׂרָיָ֥ה עֲזַרְיָ֖ה יִרְמְיָֽה׃","şĕ̂ráyá֥h ʻàzarĕyá֖h yirĕmĕyáֽh׃"],[10,3,"פַּשְׁח֥וּר אֲמַרְיָ֖ה מַלְכִּיָּֽה׃","pȧşĕ̌ẖ֥ẇr ʼàmarĕyá֖h malĕki̇yáֽ̇h׃"],[10,4,"חַטּ֥וּשׁ שְׁבַנְיָ֖ה מַלּֽוּךְ׃","ẖaṫ֥ẇş̌ şĕ̌banĕyá֖h malֽ̇ẇkĕ׃"],[10,5,"חָרִ֥ם מְרֵמ֖וֹת עֹֽבַדְיָֽה׃","ẖári֥m mĕrém֖wòţ ʻòֽbadĕyáֽh׃"],[10,6,"דָּנִיֵּ֥אל גִּנְּת֖וֹן בָּרֽוּךְ׃","dá̇niyé֥̇ʼl gi̇nĕ̇ţ֖wòn bá̇rֽẇkĕ׃"],[10,7,"מְשֻׁלָּ֥ם אֲבִיָּ֖ה מִיָּמִֽן׃","mĕşǔlá֥̇m ʼàbiyá֖̇h miyá̇miֽn׃"],[10,8,"מַֽעַזְיָ֥ה בִלְגַּ֖י שְׁמַֽעְיָ֑ה אֵ֖לֶּה הַ⁠כֹּהֲנִֽים׃ס","maֽʻazĕyá֥h bilĕgȧ֖y şĕ̌maֽʻĕyá֑h ʼé֖lėh ha⁠kò̇hàniֽym׃s"],[10,9,"וְֽ⁠הַ⁠לְוִיִּ֑ם וְ⁠יֵשׁ֨וּעַ֙ בֶּן־אֲזַנְיָ֔ה בִּנּ֕וּי מִ⁠בְּנֵ֥י חֵנָדָ֖ד קַדְמִיאֵֽל׃","wĕֽ⁠ha⁠lĕwiyi֑̇m wĕ⁠yéş̌֨ẇʻa֙ bėn-ʼàzanĕyá֔h bi̇ṅ֕ẇy mi⁠bĕ̇né֥y ẖénádá֖d qadĕmiyʼéֽl׃"],[10,10,"וַ⁠אֲחֵי⁠הֶ֑ם שְׁבַנְיָ֧ה הֽוֹדִיָּ֛ה קְלִיטָ֖א פְּלָאיָ֥ה חָנָֽן׃","wa⁠ʼàẖéy⁠he֑m şĕ̌banĕyá֧h hֽwòdiyá֛̇h qĕliytá֖ʼ pĕ̇láʼyá֥h ẖánáֽn׃"],[10,11,"מִיכָ֥א רְח֖וֹב חֲשַׁבְיָֽה׃","miyká֥ʼ rĕẖ֖wòb ẖàşǎbĕyáֽh׃"],[10,12,"זַכּ֥וּר שֵׁרֵֽבְיָ֖ה שְׁבַנְיָֽה׃","zak֥̇ẇr şé̌réֽbĕyá֖h şĕ̌banĕyáֽh׃"],[10,13,"הוֹדִיָּ֥ה בָנִ֖י בְּנִֽינוּ׃ס","hwòdiyá֥̇h báni֖y bĕ̇niֽynẇ׃s"],[10,14,"רָאשֵׁ֖י הָ⁠עָ֑ם פַּרְעֹשׁ֙ פַּחַ֣ת מוֹאָ֔ב עֵילָ֥ם זַתּ֖וּא בָּנִֽי׃","ráʼşé֖̌y há⁠ʻá֑m pȧrĕʻòş̌֙ pȧẖa֣ţ mwòʼá֔b ʻéylá֥m zaţ֖̇ẇʼ bá̇niֽy׃"],[10,15,"בֻּנִּ֥י עַזְגָּ֖ד בֵּבָֽי׃","bu̇ni֥̇y ʻazĕgá֖̇d bé̇báֽy׃"],[10,16,"אֲדֹנִיָּ֥ה בִגְוַ֖י עָדִֽין׃","ʼàdòniyá֥̇h bigĕwa֖y ʻádiֽyn׃"],[10,17,"אָטֵ֥ר חִזְקִיָּ֖ה עַזּֽוּר׃","ʼáté֥r ẖizĕqiyá֖̇h ʻażֽẇr׃"],[10,18,"הוֹדִיָּ֥ה חָשֻׁ֖ם בֵּצָֽי׃","hwòdiyá֥̇h ẖáşǔ֖m bé̇ẕáֽy׃"],[10,19,"חָרִ֥יף עֲנָת֖וֹת נובי׃","ẖári֥yp ʻànáţ֖wòţ nwby׃"],[10,20,"מַגְפִּיעָ֥שׁ מְשֻׁלָּ֖ם חֵזִֽיר׃","magĕpi̇yʻá֥ş̌ mĕşǔlá֖̇m ẖéziֽyr׃"],[10,21,"מְשֵׁיזַבְאֵ֥ל צָד֖וֹק יַדּֽוּעַ׃","mĕşé̌yzabĕʼé֥l ẕád֖wòq yaḋֽẇʻa׃"],[10,22,"פְּלַטְיָ֥ה חָנָ֖ן עֲנָיָֽה׃","pĕ̇latĕyá֥h ẖáná֖n ʻànáyáֽh׃"],[10,23,"הוֹשֵׁ֥עַ חֲנַנְיָ֖ה חַשּֽׁוּב׃","hwòşé֥̌ʻa ẖànanĕyá֖h ẖaşֽ̇̌ẇb׃"],[10,24,"הַלּוֹחֵ֥שׁ פִּלְחָ֖א שׁוֹבֵֽק׃","hal̇wòẖé֥ş̌ pi̇lĕẖá֖ʼ ş̌wòbéֽq׃"],[10,25,"רְח֥וּם חֲשַׁבְנָ֖ה מַעֲשֵׂיָֽה׃","rĕẖ֥ẇm ẖàşǎbĕná֖h maʻàşé̂yáֽh׃"],[10,26,"וַ⁠אֲחִיָּ֥ה חָנָ֖ן עָנָֽן׃","wa⁠ʼàẖiyá֥̇h ẖáná֖n ʻánáֽn׃"],[10,27,"מַלּ֥וּךְ חָרִ֖ם בַּעֲנָֽה׃","mal֥̇ẇkĕ ẖári֖m bȧʻànáֽh׃"],[10,28,"וּ⁠שְׁאָ֣ר הָ⁠עָ֡ם הַ⁠כֹּהֲנִ֣ים הַ֠⁠לְוִיִּם הַ⁠שּׁוֹעֲרִ֨ים הַ⁠מְשֹׁרְרִ֜ים הַ⁠נְּתִינִ֗ים וְֽ⁠כָל־הַ⁠נִּבְדָּ֞ל מֵ⁠עַמֵּ֤י הָ⁠אֲרָצוֹת֙ אֶל־תּוֹרַ֣ת הָ⁠אֱלֹהִ֔ים נְשֵׁי⁠הֶ֖ם בְּנֵי⁠הֶ֣ם וּ⁠בְנֹתֵי⁠הֶ֑ם כֹּ֖ל יוֹדֵ֥עַ מֵבִֽין׃","ẇ⁠şĕ̌ʼá֣r há⁠ʻá֡m ha⁠kò̇hàni֣ym ha֠⁠lĕwiyi̇m ha⁠ş̇̌wòʻàri֨ym ha⁠mĕşò̌rĕri֜ym ha⁠nĕ̇ţiyni֗ym wĕֽ⁠kál-ha⁠ni̇bĕdá̇֞l mé⁠ʻamé֤̇y há⁠ʼàráẕwòţ֙ ʼel-ţ̇wòra֣ţ há⁠ʼèlòhi֔ym nĕşé̌y⁠he֖m bĕ̇néy⁠he֣m ẇ⁠bĕnòţéy⁠he֑m kò֖̇l ywòdé֥ʻa mébiֽyn׃"],[10,29,"מַחֲזִיקִ֣ים עַל־אֲחֵי⁠הֶם֮ אַדִּירֵי⁠הֶם֒ וּ⁠בָאִ֞ים בְּ⁠אָלָ֣ה וּ⁠בִ⁠שְׁבוּעָ֗ה לָ⁠לֶ֨כֶת֙ בְּ⁠תוֹרַ֣ת הָ⁠אֱלֹהִ֔ים אֲשֶׁ֣ר נִתְּנָ֔ה בְּ⁠יַ֖ד מֹשֶׁ֣ה עֶֽבֶד־הָֽ⁠אֱלֹהִ֑ים וְ⁠לִ⁠שְׁמ֣וֹר וְ⁠לַ⁠עֲשׂ֗וֹת אֶת־כָּל־מִצְוֺת֙ יְהוָ֣ה אֲדֹנֵ֔י⁠נוּ וּ⁠מִשְׁפָּטָ֖י⁠ו וְ⁠חֻקָּֽי⁠ו׃","maẖàziyqi֣ym ʻal-ʼàẖéy⁠hem֮ ʼadi̇yréy⁠hem֒ ẇ⁠báʼi֞ym bĕ̇⁠ʼálá֣h ẇ⁠bi⁠şĕ̌bẇʻá֗h lá⁠le֨keţ֙ bĕ̇⁠ţwòra֣ţ há⁠ʼèlòhi֔ym ʼàşě֣r niţĕ̇ná֔h bĕ̇⁠ya֖d mòşě֣h ʻeֽbed-hֽá⁠ʼèlòhi֑ym wĕ⁠li⁠şĕ̌m֣wòr wĕ⁠la⁠ʻàş̂֗wòţ ʼeţ-ká̇l-miẕĕwֺţ֙ yĕhwá֣h ʼàdòné֔y⁠nẇ ẇ⁠mişĕ̌pá̇tá֖y⁠w wĕ⁠ẖuqáֽ̇y⁠w׃"],[10,30,"וַ⁠אֲשֶׁ֛ר לֹא־נִתֵּ֥ן בְּנֹתֵ֖י⁠נוּ לְ⁠עַמֵּ֣י הָ⁠אָ֑רֶץ וְ⁠אֶת־בְּנֹ֣תֵי⁠הֶ֔ם לֹ֥א נִקַּ֖ח לְ⁠בָנֵֽי⁠נוּ׃","wa⁠ʼàşě֛r lòʼ-niţé֥̇n bĕ̇nòţé֖y⁠nẇ lĕ⁠ʻamé֣̇y há⁠ʼá֑reẕ wĕ⁠ʼeţ-bĕ̇nò֣ţéy⁠he֔m lò֥ʼ niqȧ֖ẖ lĕ⁠bánéֽy⁠nẇ׃"],[10,31,"וְ⁠עַמֵּ֣י הָ⁠אָ֡רֶץ הַֽ⁠מְבִיאִים֩ אֶת־הַ⁠מַּקָּח֨וֹת וְ⁠כָל־שֶׁ֜בֶר בְּ⁠י֤וֹם הַ⁠שַּׁבָּת֙ לִ⁠מְכּ֔וֹר לֹא־נִקַּ֥ח מֵ⁠הֶ֛ם בַּ⁠שַּׁבָּ֖ת וּ⁠בְ⁠י֣וֹם קֹ֑דֶשׁ וְ⁠נִטֹּ֛שׁ אֶת־הַ⁠שָּׁנָ֥ה הַ⁠שְּׁבִיעִ֖ית וּ⁠מַשָּׁ֥א כָל־יָֽד׃","wĕ⁠ʻamé֣̇y há⁠ʼá֡reẕ haֽ⁠mĕbiyʼiym֩ ʼeţ-ha⁠mȧqá̇ẖ֨wòţ wĕ⁠kál-şě֜ber bĕ̇⁠y֤wòm ha⁠şȧ̌bá̇ţ֙ li⁠mĕk̇֔wòr lòʼ-niqȧ֥ẖ mé⁠he֛m bȧ⁠şȧ̌bá֖̇ţ ẇ⁠bĕ⁠y֣wòm qò֑deş̌ wĕ⁠nitò֛̇ş̌ ʼeţ-ha⁠şá̇̌ná֥h ha⁠şĕ̇̌biyʻi֖yţ ẇ⁠maşá֥̇̌ʼ kál-yáֽd׃"],[10,32,"וְ⁠הֶעֱמַ֤דְנוּ עָלֵ֨י⁠נוּ֙ מִצְוֺ֔ת לָ⁠תֵ֥ת עָלֵ֛י⁠נוּ שְׁלִשִׁ֥ית הַ⁠שֶּׁ֖קֶל בַּ⁠שָּׁנָ֑ה לַ⁠עֲבֹדַ֖ת בֵּ֥ית אֱלֹהֵֽי⁠נוּ׃","wĕ⁠heʻèma֤dĕnẇ ʻálé֨y⁠nẇ֙ miẕĕwֺ֔ţ lá⁠ţé֥ţ ʻálé֛y⁠nẇ şĕ̌lişǐ֥yţ ha⁠şė֖̌qel bȧ⁠şá̇̌ná֑h la⁠ʻàbòda֖ţ bé֥̇yţ ʼèlòhéֽy⁠nẇ׃"],[10,33,"לְ⁠לֶ֣חֶם הַֽ⁠מַּעֲרֶ֡כֶת וּ⁠מִנְחַ֣ת הַ⁠תָּמִ֣יד וּ⁠לְ⁠עוֹלַ֣ת הַ֠⁠תָּמִיד הַ⁠שַּׁבָּת֨וֹת הֶ⁠חֳדָשִׁ֜ים לַ⁠מּוֹעֲדִ֗ים וְ⁠לַ⁠קֳּדָשִׁים֙ וְ⁠לַ֣⁠חַטָּא֔וֹת לְ⁠כַפֵּ֖ר עַל־יִשְׂרָאֵ֑ל וְ⁠כֹ֖ל מְלֶ֥אכֶת בֵּית־אֱלֹהֵֽי⁠נוּ׃ס","lĕ⁠le֣ẖem haֽ⁠mȧʻàre֡keţ ẇ⁠minĕẖa֣ţ ha⁠ţá̇mi֣yd ẇ⁠lĕ⁠ʻwòla֣ţ ha֠⁠ţá̇miyd ha⁠şȧ̌bá̇ţ֨wòţ he⁠ẖodáşǐ֜ym la⁠ṁwòʻàdi֗ym wĕ⁠la⁠qȯdáşǐym֙ wĕ⁠la֣⁠ẖatá̇ʼ֔wòţ lĕ⁠kapé֖̇r ʻal-yişĕ̂ráʼé֑l wĕ⁠kò֖l mĕle֥ʼkeţ bé̇yţ-ʼèlòhéֽy⁠nẇ׃s"],[10,34,"וְ⁠הַ⁠גּוֹרָל֨וֹת הִפַּ֜לְנוּ עַל־קֻרְבַּ֣ן הָ⁠עֵצִ֗ים הַ⁠כֹּהֲנִ֣ים הַ⁠לְוִיִּם֮ וְ⁠הָ⁠עָם֒ לְ֠⁠הָבִיא לְ⁠בֵ֨ית אֱלֹהֵ֧י⁠נוּ לְ⁠בֵית־אֲבֹתֵ֛י⁠נוּ לְ⁠עִתִּ֥ים מְזֻמָּנִ֖ים שָׁנָ֣ה בְ⁠שָׁנָ֑ה לְ⁠בַעֵ֗ר עַל־מִזְבַּח֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ כַּ⁠כָּת֖וּב בַּ⁠תּוֹרָֽה׃","wĕ⁠ha⁠ġwòrál֨wòţ hipȧ֜lĕnẇ ʻal-qurĕbȧ֣n há⁠ʻéẕi֗ym ha⁠kò̇hàni֣ym ha⁠lĕwiyi̇m֮ wĕ⁠há⁠ʻám֒ lĕ֠⁠hábiyʼ lĕ⁠bé֨yţ ʼèlòhé֧y⁠nẇ lĕ⁠béyţ-ʼàbòţé֛y⁠nẇ lĕ⁠ʻiţi֥̇ym mĕzumá̇ni֖ym şá̌ná֣h bĕ⁠şá̌ná֑h lĕ⁠baʻé֗r ʻal-mizĕbȧẖ֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ kȧ⁠ká̇ţ֖ẇb bȧ⁠ţ̇wòráֽh׃"],[10,35,"וּ⁠לְ⁠הָבִ֞יא אֶת־בִּכּוּרֵ֣י אַדְמָתֵ֗⁠נוּ וּ⁠בִכּוּרֵ֛י כָּל־פְּרִ֥י כָל־עֵ֖ץ שָׁנָ֣ה בְ⁠שָׁנָ֑ה לְ⁠בֵ֖ית יְהוָֽה׃","ẇ⁠lĕ⁠hábi֞yʼ ʼeţ-bi̇k̇ẇré֣y ʼadĕmáţé֗⁠nẇ ẇ⁠bik̇ẇré֛y ká̇l-pĕ̇ri֥y kál-ʻé֖ẕ şá̌ná֣h bĕ⁠şá̌ná֑h lĕ⁠bé֖yţ yĕhwáֽh׃"],[10,36,"וְ⁠אֶת־בְּכֹר֤וֹת בָּנֵ֨י⁠נוּ֙ וּ⁠בְהֶמְתֵּ֔י⁠נוּ כַּ⁠כָּת֖וּב בַּ⁠תּוֹרָ֑ה וְ⁠אֶת־בְּכוֹרֵ֨י בְקָרֵ֜י⁠נוּ וְ⁠צֹאנֵ֗י⁠נוּ לְ⁠הָבִיא֙ לְ⁠בֵ֣ית אֱלֹהֵ֔י⁠נוּ לַ⁠כֹּ֣הֲנִ֔ים הַ⁠מְשָׁרְתִ֖ים בְּ⁠בֵ֥ית אֱלֹהֵֽי⁠נוּ׃","wĕ⁠ʼeţ-bĕ̇kòr֤wòţ bá̇né֨y⁠nẇ֙ ẇ⁠bĕhemĕţé̇֔y⁠nẇ kȧ⁠ká̇ţ֖ẇb bȧ⁠ţ̇wòrá֑h wĕ⁠ʼeţ-bĕ̇kwòré֨y bĕqáré֜y⁠nẇ wĕ⁠ẕòʼné֗y⁠nẇ lĕ⁠hábiyʼ֙ lĕ⁠bé֣yţ ʼèlòhé֔y⁠nẇ la⁠kò֣̇hàni֔ym ha⁠mĕşá̌rĕţi֖ym bĕ̇⁠bé֥yţ ʼèlòhéֽy⁠nẇ׃"],[10,37,"וְ⁠אֶת־רֵאשִׁ֣ית עֲרִיסֹתֵ֣י⁠נוּ וּ֠⁠תְרוּמֹתֵי⁠נוּ וּ⁠פְרִ֨י כָל־עֵ֜ץ תִּיר֣וֹשׁ וְ⁠יִצְהָ֗ר נָבִ֤יא לַ⁠כֹּהֲנִים֙ אֶל־לִשְׁכ֣וֹת בֵּית־אֱלֹהֵ֔י⁠נוּ וּ⁠מַעְשַׂ֥ר אַדְמָתֵ֖⁠נוּ לַ⁠לְוִיִּ֑ם וְ⁠הֵם֙ הַ⁠לְוִיִּ֔ם הַֽ⁠מְעַשְּׂרִ֔ים בְּ⁠כֹ֖ל עָרֵ֥י עֲבֹדָתֵֽ⁠נוּ׃","wĕ⁠ʼeţ-réʼşǐ֣yţ ʻàriysòţé֣y⁠nẇ ẇ֠⁠ţĕrẇmòţéy⁠nẇ ẇ⁠pĕri֨y kál-ʻé֜ẕ ţi̇yr֣wòş̌ wĕ⁠yiẕĕhá֗r nábi֤yʼ la⁠kò̇hàniym֙ ʼel-lişĕ̌k֣wòţ bé̇yţ-ʼèlòhé֔y⁠nẇ ẇ⁠maʻĕşâ֥r ʼadĕmáţé֖⁠nẇ la⁠lĕwiyi֑̇m wĕ⁠hém֙ ha⁠lĕwiyi̇֔m haֽ⁠mĕʻaşĕ̇̂ri֔ym bĕ̇⁠kò֖l ʻáré֥y ʻàbòdáţéֽ⁠nẇ׃"],[10,38,"וְ⁠הָיָ֨ה הַ⁠כֹּהֵ֧ן בֶּֽן־אַהֲרֹ֛ן עִם־הַ⁠לְוִיִּ֖ם בַּ⁠עְשֵׂ֣ר הַ⁠לְוִיִּ֑ם וְ⁠הַ⁠לְוִיִּ֞ם יַעֲל֨וּ אֶת־מַעֲשַׂ֤ר הַֽ⁠מַּעֲשֵׂר֙ לְ⁠בֵ֣ית אֱלֹהֵ֔י⁠נוּ אֶל־הַ⁠לְּשָׁכ֖וֹת לְ⁠בֵ֥ית הָ⁠אוֹצָֽר׃","wĕ⁠háyá֨h ha⁠kò̇hé֧n bėֽn-ʼahàrò֛n ʻim-ha⁠lĕwiyi֖̇m bȧ⁠ʻĕşé֣̂r ha⁠lĕwiyi֑̇m wĕ⁠ha⁠lĕwiyi̇֞m yaʻàl֨ẇ ʼeţ-maʻàşâ֤r haֽ⁠mȧʻàşé̂r֙ lĕ⁠bé֣yţ ʼèlòhé֔y⁠nẇ ʼel-ha⁠lĕ̇şá̌k֖wòţ lĕ⁠bé֥yţ há⁠ʼwòẕáֽr׃"],[10,39,"כִּ֣י אֶל־הַ֠⁠לְּשָׁכוֹת יָבִ֨יאוּ בְנֵי־יִשְׂרָאֵ֜ל וּ⁠בְנֵ֣י הַ⁠לֵּוִ֗י אֶת־תְּרוּמַ֣ת הַ⁠דָּגָן֮ הַ⁠תִּיר֣וֹשׁ וְ⁠הַ⁠יִּצְהָר֒ וְ⁠שָׁם֙ כְּלֵ֣י הַ⁠מִּקְדָּ֔שׁ וְ⁠הַ⁠כֹּהֲנִים֙ הַ⁠מְשָׁ֣רְתִ֔ים וְ⁠הַ⁠שּׁוֹעֲרִ֖ים וְ⁠הַ⁠מְשֹׁרְרִ֑ים וְ⁠לֹ֥א נַעֲזֹ֖ב אֶת־בֵּ֥ית אֱלֹהֵֽי⁠נוּ׃","ki֣̇y ʼel-ha֠⁠lĕ̇şá̌kwòţ yábi֨yʼẇ bĕnéy-yişĕ̂ráʼé֜l ẇ⁠bĕné֣y ha⁠lé̇wi֗y ʼeţ-ţĕ̇rẇma֣ţ ha⁠dá̇gán֮ ha⁠ţi̇yr֣wòş̌ wĕ⁠ha⁠yi̇ẕĕhár֒ wĕ⁠şá̌m֙ kĕ̇lé֣y ha⁠mi̇qĕdá̇֔ş̌ wĕ⁠ha⁠kò̇hàniym֙ ha⁠mĕşá֣̌rĕţi֔ym wĕ⁠ha⁠ş̇̌wòʻàri֖ym wĕ⁠ha⁠mĕşò̌rĕri֑ym wĕ⁠lò֥ʼ naʻàzò֖b ʼeţ-bé֥̇yţ ʼèlòhéֽy⁠nẇ׃"],[11,1,"וַ⁠יֵּשְׁב֥וּ שָׂרֵֽי־הָ⁠עָ֖ם בִּ⁠ירוּשָׁלִָ֑ם וּ⁠שְׁאָ֣ר הָ֠⁠עָם הִפִּ֨ילוּ גוֹרָל֜וֹת לְ⁠הָבִ֣יא ׀ אֶחָ֣ד מִן־הָ⁠עֲשָׂרָ֗ה לָ⁠שֶׁ֨בֶת֙ בִּֽ⁠ירוּשָׁלִַ֨ם֙ עִ֣יר הַ⁠קֹּ֔דֶשׁ וְ⁠תֵ֥שַׁע הַ⁠יָּד֖וֹת בֶּ⁠עָרִֽים׃","wa⁠yé̇şĕ̌b֥ẇ şá̂réֽy-há⁠ʻá֖m bi̇⁠yrẇşá̌liá֑m ẇ⁠şĕ̌ʼá֣r há֠⁠ʻám hipi̇֨ylẇ gwòrál֜wòţ lĕ⁠hábi֣yʼ ׀ ʼeẖá֣d min-há⁠ʻàşá̂rá֗h lá⁠şě֨beţ֙ biֽ̇⁠yrẇşá̌lia֨m֙ ʻi֣yr ha⁠qò̇֔deş̌ wĕ⁠ţé֥şǎʻ ha⁠yá̇d֖wòţ bė⁠ʻáriֽym׃"],[11,2,"וַֽ⁠יְבָרֲכ֖וּ הָ⁠עָ֑ם לְ⁠כֹל֙ הָֽ⁠אֲנָשִׁ֔ים הַ⁠מִּֽתְנַדְּבִ֔ים לָ⁠שֶׁ֖בֶת בִּ⁠ירוּשָׁלִָֽם׃פ","waֽ⁠yĕbáràk֖ẇ há⁠ʻá֑m lĕ⁠kòl֙ hֽá⁠ʼànáşǐ֔ym ha⁠miֽ̇ţĕnadĕ̇bi֔ym lá⁠şě֖beţ bi̇⁠yrẇşá̌liáֽm׃p"],[11,3,"וְ⁠אֵ֨לֶּה֙ רָאשֵׁ֣י הַ⁠מְּדִינָ֔ה אֲשֶׁ֥ר יָשְׁב֖וּ בִּ⁠ירוּשָׁלִָ֑ם וּ⁠בְ⁠עָרֵ֣י יְהוּדָ֗ה יָֽשְׁב֞וּ אִ֤ישׁ בַּ⁠אֲחֻזָּת⁠וֹ֙ בְּ⁠עָ֣רֵי⁠הֶ֔ם יִשְׂרָאֵ֤ל הַ⁠כֹּהֲנִים֙ וְ⁠הַ⁠לְוִיִּ֣ם וְ⁠הַ⁠נְּתִינִ֔ים וּ⁠בְנֵ֖י עַבְדֵ֥י שְׁלֹמֹֽה׃","wĕ⁠ʼé֨lėh֙ ráʼşé֣̌y ha⁠mĕ̇diyná֔h ʼàşě֥r yáşĕ̌b֖ẇ bi̇⁠yrẇşá̌liá֑m ẇ⁠bĕ⁠ʻáré֣y yĕhẇdá֗h yáֽşĕ̌b֞ẇ ʼi֤yş̌ bȧ⁠ʼàẖuzá̇ţ⁠wò֙ bĕ̇⁠ʻá֣réy⁠he֔m yişĕ̂ráʼé֤l ha⁠kò̇hàniym֙ wĕ⁠ha⁠lĕwiyi֣̇m wĕ⁠ha⁠nĕ̇ţiyni֔ym ẇ⁠bĕné֖y ʻabĕdé֥y şĕ̌lòmòֽh׃"],[11,4,"וּ⁠בִֽ⁠ירוּשָׁלִַ֨ם֙ יָֽשְׁב֔וּ מִ⁠בְּנֵ֥י יְהוּדָ֖ה וּ⁠מִ⁠בְּנֵ֣י בִנְיָמִ֑ן מִ⁠בְּנֵ֣י יְ֠הוּדָה עֲתָיָ֨ה בֶן־עֻזִּיָּ֜ה בֶּן־זְכַרְיָ֧ה בֶן־אֲמַרְיָ֛ה בֶּן־שְׁפַטְיָ֥ה בֶן־מַהֲלַלְאֵ֖ל מִ⁠בְּנֵי־פָֽרֶץ׃","ẇ⁠biֽ⁠yrẇşá̌lia֨m֙ yáֽşĕ̌b֔ẇ mi⁠bĕ̇né֥y yĕhẇdá֖h ẇ⁠mi⁠bĕ̇né֣y binĕyámi֑n mi⁠bĕ̇né֣y yĕ֠hẇdáh ʻàţáyá֨h ben-ʻuzi̇yá̇֜h bėn-zĕkarĕyá֧h ben-ʼàmarĕyá֛h bėn-şĕ̌patĕyá֥h ben-mahàlalĕʼé֖l mi⁠bĕ̇néy-páֽreẕ׃"],[11,5,"וּ⁠מַעֲשֵׂיָ֣ה בֶן־בָּר֣וּךְ בֶּן־כָּל־חֹ֠זֶה בֶּן־חֲזָיָ֨ה בֶן־עֲדָיָ֧ה בֶן־יוֹיָרִ֛יב בֶּן־זְכַרְיָ֖ה בֶּן־הַ⁠שִּׁלֹנִֽי׃","ẇ⁠maʻàşé̂yá֣h ben-bá̇r֣ẇkĕ bėn-ká̇l-ẖò֠zeh bėn-ẖàzáyá֨h ben-ʻàdáyá֧h ben-ywòyári֛yb bėn-zĕkarĕyá֖h bėn-ha⁠şi̇̌lòniֽy׃"],[11,6,"כָּל־בְּנֵי־פֶ֕רֶץ הַ⁠יֹּשְׁבִ֖ים בִּ⁠ירוּשָׁלִָ֑ם אַרְבַּ֥ע מֵא֛וֹת שִׁשִּׁ֥ים וּ⁠שְׁמֹנָ֖ה אַנְשֵׁי־חָֽיִל׃ס","ká̇l-bĕ̇néy-pe֕reẕ ha⁠yò̇şĕ̌bi֖ym bi̇⁠yrẇşá̌liá֑m ʼarĕbȧ֥ʻ méʼ֛wòţ şǐşi֥̇̌ym ẇ⁠şĕ̌mòná֖h ʼanĕşé̌y-ẖáֽyil׃s"],[11,7,"וְ⁠אֵ֖לֶּה בְּנֵ֣י בִנְיָמִ֑ן סַלֻּ֡א בֶּן־מְשֻׁלָּ֡ם בֶּן־יוֹעֵ֡ד בֶּן־פְּדָיָה֩ בֶן־ק֨וֹלָיָ֧ה בֶן־מַעֲשֵׂיָ֛ה בֶּן־אִֽיתִיאֵ֖ל בֶּן־יְשַֽׁעְיָֽה׃","wĕ⁠ʼé֖lėh bĕ̇né֣y binĕyámi֑n salu̇֡ʼ bėn-mĕşǔlá̇֡m bėn-ywòʻé֡d bėn-pĕ̇dáyáh֩ ben-q֨wòláyá֧h ben-maʻàşé̂yá֛h bėn-ʼiֽyţiyʼé֖l bėn-yĕşǎֽʻĕyáֽh׃"],[11,8,"וְ⁠אַחֲרָ֖י⁠ו גַּבַּ֣י סַלָּ֑י תְּשַׁ֥ע מֵא֖וֹת עֶשְׂרִ֥ים וּ⁠שְׁמֹנָֽה׃","wĕ⁠ʼaẖàrá֖y⁠w gȧbȧ֣y salá֑̇y ţĕ̇şǎ֥ʻ méʼ֖wòţ ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mònáֽh׃"],[11,9,"וְ⁠יוֹאֵ֥ל בֶּן־זִכְרִ֖י פָּקִ֣יד עֲלֵי⁠הֶ֑ם וִ⁠יהוּדָ֧ה בֶן־הַ⁠סְּנוּאָ֛ה עַל־הָ⁠עִ֖יר מִשְׁנֶֽה׃פ","wĕ⁠ywòʼé֥l bėn-zikĕri֖y pá̇qi֣yd ʻàléy⁠he֑m wi⁠yhẇdá֧h ben-ha⁠sĕ̇nẇʼá֛h ʻal-há⁠ʻi֖yr mişĕ̌neֽh׃p"],[11,10,"מִן־הַֽ⁠כֹּהֲנִ֑ים יְדַֽעְיָ֥ה בֶן־יוֹיָרִ֖יב יָכִֽין׃","min-haֽ⁠kò̇hàni֑ym yĕdaֽʻĕyá֥h ben-ywòyári֖yb yákiֽyn׃"],[11,11,"שְׂרָיָ֨ה בֶן־חִלְקִיָּ֜ה בֶּן־מְשֻׁלָּ֣ם בֶּן־צָד֗וֹק בֶּן־מְרָיוֹת֙ בֶּן־אֲחִיט֔וּב נְגִ֖ד בֵּ֥ית הָ⁠אֱלֹהִֽים׃","şĕ̂ráyá֨h ben-ẖilĕqiyá̇֜h bėn-mĕşǔlá֣̇m bėn-ẕád֗wòq bėn-mĕráywòţ֙ bėn-ʼàẖiyt֔ẇb nĕgi֖d bé֥̇yţ há⁠ʼèlòhiֽym׃"],[11,12,"וַ⁠אֲחֵי⁠הֶ֗ם עֹשֵׂ֤י הַ⁠מְּלָאכָה֙ לַ⁠בַּ֔יִת שְׁמֹנֶ֥ה מֵא֖וֹת עֶשְׂרִ֣ים וּ⁠שְׁנָ֑יִם וַ֠⁠עֲדָיָה בֶּן־יְרֹחָ֤ם בֶּן־פְּלַלְיָה֙ בֶּן־אַמְצִ֣י בֶן־זְכַרְיָ֔ה בֶּן־פַּשְׁח֖וּר בֶּן־מַלְכִּיָּֽה׃","wa⁠ʼàẖéy⁠he֗m ʻòşé֤̂y ha⁠mĕ̇láʼkáh֙ la⁠bȧ֔yiţ şĕ̌mòne֥h méʼ֖wòţ ʻeşĕ̂ri֣ym ẇ⁠şĕ̌ná֑yim wa֠⁠ʻàdáyáh bėn-yĕròẖá֤m bėn-pĕ̇lalĕyáh֙ bėn-ʼamĕẕi֣y ben-zĕkarĕyá֔h bėn-pȧşĕ̌ẖ֖ẇr bėn-malĕki̇yáֽ̇h׃"],[11,13,"וְ⁠אֶחָי⁠ו֙ רָאשִׁ֣ים לְ⁠אָב֔וֹת מָאתַ֖יִם אַרְבָּעִ֣ים וּ⁠שְׁנָ֑יִם וַ⁠עֲמַשְׁסַ֧י בֶּן־עֲזַרְאֵ֛ל בֶּן־אַחְזַ֥י בֶּן־מְשִׁלֵּמ֖וֹת בֶּן־אִמֵּֽר׃","wĕ⁠ʼeẖáy⁠w֙ ráʼşǐ֣ym lĕ⁠ʼáb֔wòţ máʼţa֖yim ʼarĕbá̇ʻi֣ym ẇ⁠şĕ̌ná֑yim wa⁠ʻàmaşĕ̌sa֧y bėn-ʻàzarĕʼé֛l bėn-ʼaẖĕza֥y bėn-mĕşǐlé̇m֖wòţ bėn-ʼiméֽ̇r׃"],[11,14,"וַ⁠אֲחֵי⁠הֶם֙ גִּבּ֣וֹרֵי חַ֔יִל מֵאָ֖ה עֶשְׂרִ֣ים וּ⁠שְׁמֹנָ֑ה וּ⁠פָקִ֣יד עֲלֵי⁠הֶ֔ם זַבְדִּיאֵ֖ל בֶּן־הַ⁠גְּדוֹלִֽים׃ס","wa⁠ʼàẖéy⁠hem֙ gi̇ḃ֣wòréy ẖa֔yil méʼá֖h ʻeşĕ̂ri֣ym ẇ⁠şĕ̌mòná֑h ẇ⁠páqi֣yd ʻàléy⁠he֔m zabĕdi̇yʼé֖l bėn-ha⁠gĕ̇dwòliֽym׃s"],[11,15,"וּ⁠מִֽן־הַ⁠לְוִיִּ֑ם שְׁמַעְיָ֧ה בֶן־חַשּׁ֛וּב בֶּן־עַזְרִיקָ֥ם בֶּן־חֲשַׁבְיָ֖ה בֶּן־בּוּנִּֽי׃","ẇ⁠miֽn-ha⁠lĕwiyi֑̇m şĕ̌maʻĕyá֧h ben-ẖaş֛̇̌ẇb bėn-ʻazĕriyqá֥m bėn-ẖàşǎbĕyá֖h bėn-ḃẇniֽ̇y׃"],[11,16,"וְ⁠שַׁבְּתַ֨י וְ⁠יוֹזָבָ֜ד עַל־הַ⁠מְּלָאכָ֤ה הַ⁠חִֽיצֹנָה֙ לְ⁠בֵ֣ית הָ⁠אֱלֹהִ֔ים מֵ⁠רָאשֵׁ֖י הַ⁠לְוִיִּֽם׃","wĕ⁠şǎbĕ̇ţa֨y wĕ⁠ywòzábá֜d ʻal-ha⁠mĕ̇láʼká֤h ha⁠ẖiֽyẕònáh֙ lĕ⁠bé֣yţ há⁠ʼèlòhi֔ym mé⁠ráʼşé֖̌y ha⁠lĕwiyiֽ̇m׃"],[11,17,"וּ⁠מַתַּנְיָ֣ה בֶן־מִ֠יכָה בֶּן־זַבְדִּ֨י בֶן־אָסָ֜ף רֹ֗אשׁ הַ⁠תְּחִלָּה֙ יְהוֹדֶ֣ה לַ⁠תְּפִלָּ֔ה וּ⁠בַקְבֻּקְיָ֖ה מִשְׁנֶ֣ה מֵ⁠אֶחָ֑י⁠ו וְ⁠עַבְדָּא֙ בֶּן־שַׁמּ֔וּעַ בֶּן־גָּלָ֖ל בֶּן־ידיתון׃","ẇ⁠maţȧnĕyá֣h ben-mi֠ykáh bėn-zabĕdi̇֨y ben-ʼásá֜p rò֗ʼş̌ ha⁠ţĕ̇ẖilá̇h֙ yĕhwòde֣h la⁠ţĕ̇pilá̇֔h ẇ⁠baqĕbu̇qĕyá֖h mişĕ̌ne֣h mé⁠ʼeẖá֑y⁠w wĕ⁠ʻabĕdá̇ʼ֙ bėn-şǎṁ֔ẇʻa bėn-gá̇lá֖l bėn-ydyţwn׃"],[11,18,"כָּל־הַ⁠לְוִיִּם֙ בְּ⁠עִ֣יר הַ⁠קֹּ֔דֶשׁ מָאתַ֖יִם שְׁמֹנִ֥ים וְ⁠אַרְבָּעָֽה׃פ","ká̇l-ha⁠lĕwiyi̇m֙ bĕ̇⁠ʻi֣yr ha⁠qò̇֔deş̌ máʼţa֖yim şĕ̌mòni֥ym wĕ⁠ʼarĕbá̇ʻáֽh׃p"],[11,19,"וְ⁠הַ⁠שּֽׁוֹעֲרִים֙ עַקּ֣וּב טַלְמ֔וֹן וַ⁠אֲחֵי⁠הֶ֖ם הַ⁠שֹּׁמְרִ֣ים בַּ⁠שְּׁעָרִ֑ים מֵאָ֖ה שִׁבְעִ֥ים וּ⁠שְׁנָֽיִם׃","wĕ⁠ha⁠şֽ̇̌wòʻàriym֙ ʻaq֣̇ẇb talĕm֔wòn wa⁠ʼàẖéy⁠he֖m ha⁠şò̇̌mĕri֣ym bȧ⁠şĕ̇̌ʻári֑ym méʼá֖h şǐbĕʻi֥ym ẇ⁠şĕ̌náֽyim׃"],[11,20,"וּ⁠שְׁאָ֨ר יִשְׂרָאֵ֜ל הַ⁠כֹּהֲנִ֤ים הַ⁠לְוִיִּם֙ בְּ⁠כָל־עָרֵ֣י יְהוּדָ֔ה אִ֖ישׁ בְּ⁠נַחֲלָתֽ⁠וֹ׃","ẇ⁠şĕ̌ʼá֨r yişĕ̂ráʼé֜l ha⁠kò̇hàni֤ym ha⁠lĕwiyi̇m֙ bĕ̇⁠kál-ʻáré֣y yĕhẇdá֔h ʼi֖yş̌ bĕ̇⁠naẖàláţֽ⁠wò׃"],[11,21,"וְ⁠הַ⁠נְּתִינִ֖ים יֹשְׁבִ֣ים בָּ⁠עֹ֑פֶל וְ⁠צִיחָ֥א וְ⁠גִשְׁפָּ֖א עַל־הַ⁠נְּתִינִֽים׃פ","wĕ⁠ha⁠nĕ̇ţiyni֖ym yòşĕ̌bi֣ym bá̇⁠ʻò֑pel wĕ⁠ẕiyẖá֥ʼ wĕ⁠gişĕ̌pá֖̇ʼ ʻal-ha⁠nĕ̇ţiyniֽym׃p"],[11,22,"וּ⁠פְקִ֤יד הַ⁠לְוִיִּם֙ בִּ⁠יר֣וּשָׁלִַ֔ם עֻזִּ֤י בֶן־בָּנִי֙ בֶּן־חֲשַׁבְיָ֔ה בֶּן־מַתַּנְיָ֖ה בֶּן־מִיכָ֑א מִ⁠בְּנֵ֤י אָסָף֙ הַ⁠מְשֹׁ֣רְרִ֔ים לְ⁠נֶ֖גֶד מְלֶ֥אכֶת בֵּית־הָ⁠אֱלֹהִֽים׃","ẇ⁠pĕqi֤yd ha⁠lĕwiyi̇m֙ bi̇⁠yr֣ẇşá̌lia֔m ʻuzi֤̇y ben-bá̇niy֙ bėn-ẖàşǎbĕyá֔h bėn-maţȧnĕyá֖h bėn-miyká֑ʼ mi⁠bĕ̇né֤y ʼásáp֙ ha⁠mĕşò֣̌rĕri֔ym lĕ⁠ne֖ged mĕle֥ʼkeţ bé̇yţ-há⁠ʼèlòhiֽym׃"],[11,23,"כִּֽי־מִצְוַ֥ת הַ⁠מֶּ֖לֶךְ עֲלֵי⁠הֶ֑ם וַ⁠אֲמָנָ֥ה עַל־הַ⁠מְשֹׁרְרִ֖ים דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","kiֽ̇y-miẕĕwa֥ţ ha⁠mė֖lekĕ ʻàléy⁠he֑m wa⁠ʼàmáná֥h ʻal-ha⁠mĕşò̌rĕri֖ym dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[11,24,"וּ⁠פְתַֽחְיָ֨ה בֶּן־מְשֵֽׁיזַבְאֵ֜ל מִ⁠בְּנֵי־זֶ֤רַח בֶּן־יְהוּדָה֙ לְ⁠יַ֣ד הַ⁠מֶּ֔לֶךְ לְ⁠כָל־דָּבָ֖ר לָ⁠עָֽם׃","ẇ⁠pĕţaֽẖĕyá֨h bėn-mĕşéֽ̌yzabĕʼé֜l mi⁠bĕ̇néy-ze֤raẖ bėn-yĕhẇdáh֙ lĕ⁠ya֣d ha⁠mė֔lekĕ lĕ⁠kál-dá̇bá֖r lá⁠ʻáֽm׃"],[11,25,"וְ⁠אֶל־הַ⁠חֲצֵרִ֖ים בִּ⁠שְׂדֹתָ֑⁠ם מִ⁠בְּנֵ֣י יְהוּדָ֗ה יָֽשְׁב֞וּ בְּ⁠קִרְיַ֤ת הָֽאַרְבַּע֙ וּ⁠בְנֹתֶ֔י⁠הָ וּ⁠בְ⁠דִיבֹן֙ וּ⁠בְנֹתֶ֔י⁠הָ וּ⁠בִֽ⁠יקַּבְצְאֵ֖ל וַ⁠חֲצֵרֶֽי⁠הָ׃","wĕ⁠ʼel-ha⁠ẖàẕéri֖ym bi̇⁠şĕ̂dòţá֑⁠m mi⁠bĕ̇né֣y yĕhẇdá֗h yáֽşĕ̌b֞ẇ bĕ̇⁠qirĕya֤ţ háֽʼarĕbȧʻ֙ ẇ⁠bĕnòţe֔y⁠há ẇ⁠bĕ⁠diybòn֙ ẇ⁠bĕnòţe֔y⁠há ẇ⁠biֽ⁠yqȧbĕẕĕʼé֖l wa⁠ẖàẕéreֽy⁠há׃"],[11,26,"וּ⁠בְ⁠יֵשׁ֥וּעַ וּ⁠בְ⁠מוֹלָדָ֖ה וּ⁠בְ⁠בֵ֥ית פָּֽלֶט׃","ẇ⁠bĕ⁠yéş֥̌ẇʻa ẇ⁠bĕ⁠mwòládá֖h ẇ⁠bĕ⁠bé֥yţ páֽ̇let׃"],[11,27,"וּ⁠בַ⁠חֲצַ֥ר שׁוּעָ֛ל וּ⁠בִ⁠בְאֵ֥ר שֶׁ֖בַע וּ⁠בְנֹתֶֽי⁠הָ׃","ẇ⁠ba⁠ẖàẕa֥r ş̌ẇʻá֛l ẇ⁠bi⁠bĕʼé֥r şě֖baʻ ẇ⁠bĕnòţeֽy⁠há׃"],[11,28,"וּ⁠בְ⁠צִֽקְלַ֥ג וּ⁠בִ⁠מְכֹנָ֖ה וּ⁠בִ⁠בְנֹתֶֽי⁠הָ׃","ẇ⁠bĕ⁠ẕiֽqĕla֥g ẇ⁠bi⁠mĕkòná֖h ẇ⁠bi⁠bĕnòţeֽy⁠há׃"],[11,29,"וּ⁠בְ⁠עֵ֥ין רִמּ֛וֹן וּ⁠בְ⁠צָרְעָ֖ה וּ⁠בְ⁠יַרְמֽוּת׃","ẇ⁠bĕ⁠ʻé֥yn riṁ֛wòn ẇ⁠bĕ⁠ẕárĕʻá֖h ẇ⁠bĕ⁠yarĕmֽẇţ׃"],[11,30,"זָנֹ֤חַ עֲדֻלָּם֙ וְ⁠חַצְרֵי⁠הֶ֔ם לָכִישׁ֙ וּ⁠שְׂדֹתֶ֔י⁠הָ עֲזֵקָ֖ה וּ⁠בְנֹתֶ֑י⁠הָ וַ⁠יַּחֲנ֥וּ מִ⁠בְּאֵֽר־שֶׁ֖בַע עַד־גֵּֽיא־הִנֹּֽם׃","zánò֤ẖa ʻàdulá̇m֙ wĕ⁠ẖaẕĕréy⁠he֔m lákiyş̌֙ ẇ⁠şĕ̂dòţe֔y⁠há ʻàzéqá֖h ẇ⁠bĕnòţe֑y⁠há wa⁠yȧẖàn֥ẇ mi⁠bĕ̇ʼéֽr-şě֖baʻ ʻad-géֽ̇yʼ-hinòֽ̇m׃"],[11,31,"וּ⁠בְנֵ֥י בִנְיָמִ֖ן מִ⁠גָּ֑בַע מִכְמָ֣שׂ וְ⁠עַיָּ֔ה וּ⁠בֵֽית־אֵ֖ל וּ⁠בְנֹתֶֽי⁠הָ׃","ẇ⁠bĕné֥y binĕyámi֖n mi⁠gá֑̇baʻ mikĕmá֣ş̂ wĕ⁠ʻayá̇֔h ẇ⁠béֽyţ-ʼé֖l ẇ⁠bĕnòţeֽy⁠há׃"],[11,32,"עֲנָת֥וֹת נֹ֖ב עֲנָֽנְיָֽה׃","ʻànáţ֥wòţ nò֖b ʻànáֽnĕyáֽh׃"],[11,33,"חָצ֥וֹר ׀ רָמָ֖ה גִּתָּֽיִם׃","ẖáẕ֥wòr ׀ rámá֖h gi̇ţáֽ̇yim׃"],[11,34,"חָדִ֥יד צְבֹעִ֖ים נְבַלָּֽט׃","ẖádi֥yd ẕĕbòʻi֖ym nĕbaláֽ̇t׃"],[11,35,"לֹ֥ד וְ⁠אוֹנ֖וֹ גֵּ֥י הַחֲרָשִֽׁים׃","lò֥d wĕ⁠ʼwòn֖wò gé֥̇y haẖàráşǐֽym׃"],[11,36,"וּ⁠מִן־הַ⁠לְוִיִּ֔ם מַחְלְק֥וֹת יְהוּדָ֖ה לְ⁠בִנְיָמִֽין׃פ","ẇ⁠min-ha⁠lĕwiyi̇֔m maẖĕlĕq֥wòţ yĕhẇdá֖h lĕ⁠binĕyámiֽyn׃p"],[12,1,"וְ⁠אֵ֨לֶּה֙ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם אֲשֶׁ֥ר עָל֛וּ עִם־זְרֻבָּבֶ֥ל בֶּן־שְׁאַלְתִּיאֵ֖ל וְ⁠יֵשׁ֑וּעַ שְׂרָיָ֥ה יִרְמְיָ֖ה עֶזְרָֽא׃","wĕ⁠ʼé֨lėh֙ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m ʼàşě֥r ʻál֛ẇ ʻim-zĕrubá̇be֥l bėn-şĕ̌ʼalĕţi̇yʼé֖l wĕ⁠yéş֑̌ẇʻa şĕ̂ráyá֥h yirĕmĕyá֖h ʻezĕráֽʼ׃"],[12,2,"אֲמַרְיָ֥ה מַלּ֖וּךְ חַטּֽוּשׁ׃","ʼàmarĕyá֥h mal֖̇ẇkĕ ẖaṫֽẇş̌׃"],[12,3,"שְׁכַנְיָ֥ה רְחֻ֖ם מְרֵמֹֽת׃","şĕ̌kanĕyá֥h rĕẖu֖m mĕrémòֽţ׃"],[12,4,"עִדּ֥וֹא גִנְּת֖וֹי אֲבִיָּֽה׃","ʻiḋ֥wòʼ ginĕ̇ţ֖wòy ʼàbiyáֽ̇h׃"],[12,5,"מִיָּמִ֥ין מַֽעַדְיָ֖ה בִּלְגָּֽה׃","miyá̇mi֥yn maֽʻadĕyá֖h bi̇lĕgáֽ̇h׃"],[12,6,"שְׁמַֽעְיָ֥ה וְ⁠יוֹיָרִ֖יב יְדַֽעְיָֽה׃","şĕ̌maֽʻĕyá֥h wĕ⁠ywòyári֖yb yĕdaֽʻĕyáֽh׃"],[12,7,"סַלּ֣וּ עָמ֔וֹק חִלְקִיָּ֖ה יְדַֽעְיָ֑ה אֵ֣לֶּה רָאשֵׁ֧י הַ⁠כֹּהֲנִ֛ים וַ⁠אֲחֵי⁠הֶ֖ם בִּ⁠ימֵ֥י יֵשֽׁוּעַ׃פ","sal֣̇ẇ ʻám֔wòq ẖilĕqiyá֖̇h yĕdaֽʻĕyá֑h ʼé֣lėh ráʼşé֧̌y ha⁠kò̇hàni֛ym wa⁠ʼàẖéy⁠he֖m bi̇⁠ymé֥y yéşֽ̌ẇʻa׃p"],[12,8,"וְ⁠הַ⁠לְוִיִּ֗ם יֵשׁ֧וּעַ בִּנּ֛וּי קַדְמִיאֵ֥ל שֵׁרֵבְיָ֖ה יְהוּדָ֣ה מַתַּנְיָ֑ה עַֽל־הֻיְּד֖וֹת ה֥וּא וְ⁠אֶחָֽי⁠ו׃","wĕ⁠ha⁠lĕwiyi̇֗m yéş֧̌ẇʻa bi̇ṅ֛ẇy qadĕmiyʼé֥l şé̌rébĕyá֖h yĕhẇdá֣h maţȧnĕyá֑h ʻaֽl-huyĕ̇d֖wòţ h֥ẇʼ wĕ⁠ʼeẖáֽy⁠w׃"],[12,9,"וּ⁠בַקְבֻּֽקְיָ֨ה ו⁠ענו אֲחֵי⁠הֶ֛ם לְ⁠נֶגְדָּ֖⁠ם לְ⁠מִשְׁמָרֽוֹת׃","ẇ⁠baqĕbuֽ̇qĕyá֨h w⁠ʻnw ʼàẖéy⁠he֛m lĕ⁠negĕdá֖̇⁠m lĕ⁠mişĕ̌márֽwòţ׃"],[12,10,"וְ⁠יֵשׁ֖וּעַ הוֹלִ֣יד אֶת־יֽוֹיָקִ֑ים וְ⁠יֽוֹיָקִים֙ הוֹלִ֣יד אֶת־אֶלְיָשִׁ֔יב וְ⁠אֶלְיָשִׁ֖יב אֶת־יוֹיָדָֽע׃","wĕ⁠yéş֖̌ẇʻa hwòli֣yd ʼeţ-yֽwòyáqi֑ym wĕ⁠yֽwòyáqiym֙ hwòli֣yd ʼeţ-ʼelĕyáşǐ֔yb wĕ⁠ʼelĕyáşǐ֖yb ʼeţ-ywòyádáֽʻ׃"],[12,11,"וְ⁠יוֹיָדָע֙ הוֹלִ֣יד אֶת־יוֹנָתָ֔ן וְ⁠יוֹנָתָ֖ן הוֹלִ֥יד אֶת־יַדּֽוּעַ׃","wĕ⁠ywòyádáʻ֙ hwòli֣yd ʼeţ-ywònáţá֔n wĕ⁠ywònáţá֖n hwòli֥yd ʼeţ-yaḋֽẇʻa׃"],[12,12,"וּ⁠בִ⁠ימֵי֙ יֽוֹיָקִ֔ים הָי֥וּ כֹהֲנִ֖ים רָאשֵׁ֣י הָ⁠אָב֑וֹת לִ⁠שְׂרָיָ֣ה מְרָיָ֔ה לְ⁠יִרְמְיָ֖ה חֲנַנְיָֽה׃","ẇ⁠bi⁠yméy֙ yֽwòyáqi֔ym háy֥ẇ kòhàni֖ym ráʼşé֣̌y há⁠ʼáb֑wòţ li⁠şĕ̂ráyá֣h mĕráyá֔h lĕ⁠yirĕmĕyá֖h ẖànanĕyáֽh׃"],[12,13,"לְ⁠עֶזְרָ֣א מְשֻׁלָּ֔ם לַ⁠אֲמַרְיָ֖ה יְהוֹחָנָֽן׃","lĕ⁠ʻezĕrá֣ʼ mĕşǔlá̇֔m la⁠ʼàmarĕyá֖h yĕhwòẖánáֽn׃"],[12,14,"ל⁠מלוכי יֽוֹנָתָ֔ן לִ⁠שְׁבַנְיָ֖ה יוֹסֵֽף׃","l⁠mlwky yֽwònáţá֔n li⁠şĕ̌banĕyá֖h ywòséֽp׃"],[12,15,"לְ⁠חָרִ֣ם עַדְנָ֔א לִ⁠מְרָי֖וֹת חֶלְקָֽי׃","lĕ⁠ẖári֣m ʻadĕná֔ʼ li⁠mĕráy֖wòţ ẖelĕqáֽy׃"],[12,16,"ל⁠עדיא זְכַרְיָ֖ה לְ⁠גִנְּת֥וֹן מְשֻׁלָּֽם׃","l⁠ʻdyʼ zĕkarĕyá֖h lĕ⁠ginĕ̇ţ֥wòn mĕşǔláֽ̇m׃"],[12,17,"לַ⁠אֲבִיָּ֖ה זִכְרִ֑י לְ⁠מִ֨נְיָמִ֔ין לְ⁠מוֹעַדְיָ֖ה פִּלְטָֽי׃","la⁠ʼàbiyá֖̇h zikĕri֑y lĕ⁠mi֨nĕyámi֔yn lĕ⁠mwòʻadĕyá֖h pi̇lĕtáֽy׃"],[12,18,"לְ⁠בִלְגָּ֣ה שַׁמּ֔וּעַ לִֽ⁠שְׁמַעְיָ֖ה יְהוֹנָתָֽן׃","lĕ⁠bilĕgá֣̇h şǎṁ֔ẇʻa liֽ⁠şĕ̌maʻĕyá֖h yĕhwònáţáֽn׃"],[12,19,"וּ⁠לְ⁠יוֹיָרִ֣יב מַתְּנַ֔י לִֽ⁠ידַֽעְיָ֖ה עֻזִּֽי׃","ẇ⁠lĕ⁠ywòyári֣yb maţĕ̇na֔y liֽ⁠ydaֽʻĕyá֖h ʻuziֽ̇y׃"],[12,20,"לְ⁠סַלַּ֥י קַלָּ֖י לְ⁠עָמ֥וֹק עֵֽבֶר׃","lĕ⁠salȧ֥y qalá֖̇y lĕ⁠ʻám֥wòq ʻéֽber׃"],[12,21,"לְ⁠חִלְקִיָּ֣ה חֲשַׁבְיָ֔ה לִֽ⁠ידַֽעְיָ֖ה נְתַנְאֵֽל׃","lĕ⁠ẖilĕqiyá֣̇h ẖàşǎbĕyá֔h liֽ⁠ydaֽʻĕyá֖h nĕţanĕʼéֽl׃"],[12,22,"הַ⁠לְוִיִּם֩ בִּ⁠ימֵ֨י אֶלְיָשִׁ֜יב יוֹיָדָ֤ע וְ⁠יוֹחָנָן֙ וְ⁠יַדּ֔וּעַ כְּתוּבִ֖ים רָאשֵׁ֣י אָב֑וֹת וְ⁠הַ⁠כֹּ֣הֲנִ֔ים עַל־מַלְכ֖וּת דָּרְיָ֥וֶשׁ הַ⁠פָּֽרְסִֽי׃פ","ha⁠lĕwiyi̇m֩ bi̇⁠ymé֨y ʼelĕyáşǐ֜yb ywòyádá֤ʻ wĕ⁠ywòẖánán֙ wĕ⁠yaḋ֔ẇʻa kĕ̇ţẇbi֖ym ráʼşé֣̌y ʼáb֑wòţ wĕ⁠ha⁠kò֣̇hàni֔ym ʻal-malĕk֖ẇţ dá̇rĕyá֥weş̌ ha⁠páֽ̇rĕsiֽy׃p"],[12,23,"בְּנֵ֤י לֵוִי֙ רָאשֵׁ֣י הָֽ⁠אָב֔וֹת כְּתוּבִ֕ים עַל־סֵ֖פֶר דִּבְרֵ֣י הַ⁠יָּמִ֑ים וְ⁠עַד־יְמֵ֖י יֽוֹחָנָ֥ן בֶּן־אֶלְיָשִֽׁיב׃","bĕ̇né֤y léwiy֙ ráʼşé֣̌y háֽ⁠ʼáb֔wòţ kĕ̇ţẇbi֕ym ʻal-sé֖per di̇bĕré֣y ha⁠yá̇mi֑ym wĕ⁠ʻad-yĕmé֖y yֽwòẖáná֥n bėn-ʼelĕyáşǐֽyb׃"],[12,24,"וְ⁠רָאשֵׁ֣י הַ֠⁠לְוִיִּם חֲשַׁבְיָ֨ה שֵֽׁרֵבְיָ֜ה וְ⁠יֵשׁ֤וּעַ בֶּן־קַדְמִיאֵל֙ וַ⁠אֲחֵי⁠הֶ֣ם לְ⁠נֶגְדָּ֔⁠ם לְ⁠הַלֵּ֣ל לְ⁠הוֹד֔וֹת בְּ⁠מִצְוַ֖ת דָּוִ֣יד אִישׁ־הָ⁠אֱלֹהִ֑ים מִשְׁמָ֖ר לְ⁠עֻמַּ֥ת מִשְׁמָֽר׃","wĕ⁠ráʼşé֣̌y ha֠⁠lĕwiyi̇m ẖàşǎbĕyá֨h şéֽ̌rébĕyá֜h wĕ⁠yéş֤̌ẇʻa bėn-qadĕmiyʼél֙ wa⁠ʼàẖéy⁠he֣m lĕ⁠negĕdá̇֔⁠m lĕ⁠halé֣̇l lĕ⁠hwòd֔wòţ bĕ̇⁠miẕĕwa֖ţ dá̇wi֣yd ʼiyş̌-há⁠ʼèlòhi֑ym mişĕ̌má֖r lĕ⁠ʻumȧ֥ţ mişĕ̌máֽr׃"],[12,25,"מַתַּנְיָ֧ה וּ⁠בַקְבֻּֽקְיָ֛ה עֹבַדְיָ֥ה מְשֻׁלָּ֖ם טַלְמ֣וֹן עַקּ֑וּב שֹׁמְרִ֤ים שֽׁוֹעֲרִים֙ מִשְׁמָ֔ר בַּ⁠אֲסֻפֵּ֖י הַ⁠שְּׁעָרִֽים׃","maţȧnĕyá֧h ẇ⁠baqĕbuֽ̇qĕyá֛h ʻòbadĕyá֥h mĕşǔlá֖̇m talĕm֣wòn ʻaq֑̇ẇb şò̌mĕri֤ym şֽ̌wòʻàriym֙ mişĕ̌má֔r bȧ⁠ʼàsupé֖̇y ha⁠şĕ̇̌ʻáriֽym׃"],[12,26,"אֵ֕לֶּה בִּ⁠ימֵ֛י יוֹיָקִ֥ים בֶּן־יֵשׁ֖וּעַ בֶּן־יוֹצָדָ֑ק וּ⁠בִ⁠ימֵי֙ נְחֶמְיָ֣ה הַ⁠פֶּחָ֔ה וְ⁠עֶזְרָ֥א הַ⁠כֹּהֵ֖ן הַ⁠סּוֹפֵֽר׃פ","ʼé֕lėh bi̇⁠ymé֛y ywòyáqi֥ym bėn-yéş֖̌ẇʻa bėn-ywòẕádá֑q ẇ⁠bi⁠yméy֙ nĕẖemĕyá֣h ha⁠pėẖá֔h wĕ⁠ʻezĕrá֥ʼ ha⁠kò̇hé֖n ha⁠ṡwòpéֽr׃p"],[12,27,"וּ⁠בַ⁠חֲנֻכַּ֞ת חוֹמַ֣ת יְרוּשָׁלִַ֗ם בִּקְשׁ֤וּ אֶת־הַ⁠לְוִיִּם֙ מִ⁠כָּל־מְק֣וֹמֹתָ֔⁠ם לַ⁠הֲבִיאָ֖⁠ם לִֽ⁠ירוּשָׁלִָ֑ם לַ⁠עֲשֹׂ֨ת חֲנֻכָּ֤ה וְ⁠שִׂמְחָה֙ וּ⁠בְ⁠תוֹד֣וֹת וּ⁠בְ⁠שִׁ֔יר מְצִלְתַּ֖יִם נְבָלִ֥ים וּ⁠בְ⁠כִנֹּרֽוֹת׃","ẇ⁠ba⁠ẖànukȧ֞ţ ẖwòma֣ţ yĕrẇşá̌lia֗m bi̇qĕş֤̌ẇ ʼeţ-ha⁠lĕwiyi̇m֙ mi⁠ká̇l-mĕq֣wòmòţá֔⁠m la⁠hàbiyʼá֖⁠m liֽ⁠yrẇşá̌liá֑m la⁠ʻàşò̂֨ţ ẖànuká֤̇h wĕ⁠şîmĕẖáh֙ ẇ⁠bĕ⁠ţwòd֣wòţ ẇ⁠bĕ⁠şǐ֔yr mĕẕilĕţȧ֖yim nĕbáli֥ym ẇ⁠bĕ⁠kinò̇rֽwòţ׃"],[12,28,"וַ⁠יֵּאָ֣סְפ֔וּ בְּנֵ֖י הַ⁠מְשֹׁרְרִ֑ים וּ⁠מִן־הַ⁠כִּכָּר֙ סְבִיב֣וֹת יְרוּשָׁלִַ֔ם וּ⁠מִן־חַצְרֵ֖י נְטֹפָתִֽי׃","wa⁠yé̇ʼá֣sĕp֔ẇ bĕ̇né֖y ha⁠mĕşò̌rĕri֑ym ẇ⁠min-ha⁠ki̇ká̇r֙ sĕbiyb֣wòţ yĕrẇşá̌lia֔m ẇ⁠min-ẖaẕĕré֖y nĕtòpáţiֽy׃"],[12,29,"וּ⁠מִ⁠בֵּית֙ הַגִּלְגָּ֔ל וּ⁠מִ⁠שְּׂד֥וֹת גֶּ֖בַע וְ⁠עַזְמָ֑וֶת כִּ֣י חֲצֵרִ֗ים בָּנ֤וּ לָ⁠הֶם֙ הַ⁠מְשֹׁ֣רֲרִ֔ים סְבִיב֖וֹת יְרוּשָׁלִָֽם׃","ẇ⁠mi⁠bé̇yţ֙ hagi̇lĕgá̇֔l ẇ⁠mi⁠şĕ̇̂d֥wòţ gė֖baʻ wĕ⁠ʻazĕmá֑weţ ki֣̇y ẖàẕéri֗ym bá̇n֤ẇ lá⁠hem֙ ha⁠mĕşò֣̌ràri֔ym sĕbiyb֖wòţ yĕrẇşá̌liáֽm׃"],[12,30,"וַ⁠יִּֽטַּהֲר֔וּ הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּ֑ם וַֽ⁠יְטַהֲרוּ֙ אֶת־הָ⁠עָ֔ם וְ⁠אֶת־הַ⁠שְּׁעָרִ֖ים וְ⁠אֶֽת־הַ⁠חוֹמָֽה׃","wa⁠yiֽ̇tȧhàr֔ẇ ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyi֑̇m waֽ⁠yĕtahàrẇ֙ ʼeţ-há⁠ʻá֔m wĕ⁠ʼeţ-ha⁠şĕ̇̌ʻári֖ym wĕ⁠ʼeֽţ-ha⁠ẖwòmáֽh׃"],[12,31,"וָ⁠אַעֲלֶה֙ אֶת־שָׂרֵ֣י יְהוּדָ֔ה מֵ⁠עַ֖ל לַ⁠חוֹמָ֑ה וָ⁠אַעֲמִ֡ידָ⁠ה שְׁתֵּ֣י תוֹדֹת֩ גְּדוֹלֹ֨ת וְ⁠תַהֲלֻכֹ֤ת לַ⁠יָּמִין֙ מֵ⁠עַ֣ל לַ⁠חוֹמָ֔ה לְ⁠שַׁ֖עַר הָ⁠אַשְׁפֹּֽת׃","wá⁠ʼaʻàleh֙ ʼeţ-şá̂ré֣y yĕhẇdá֔h mé⁠ʻa֖l la⁠ẖwòmá֑h wá⁠ʼaʻàmi֡ydá⁠h şĕ̌ţé֣̇y ţwòdòţ֩ gĕ̇dwòlò֨ţ wĕ⁠ţahàlukò֤ţ la⁠yá̇miyn֙ mé⁠ʻa֣l la⁠ẖwòmá֔h lĕ⁠şǎ֖ʻar há⁠ʼaşĕ̌pòֽ̇ţ׃"],[12,32,"וַ⁠יֵּ֤לֶךְ אַחֲרֵי⁠הֶם֙ הוֹשַׁ֣עְיָ֔ה וַ⁠חֲצִ֖י שָׂרֵ֥י יְהוּדָֽה׃","wa⁠yé֤̇lekĕ ʼaẖàréy⁠hem֙ hwòşǎ֣ʻĕyá֔h wa⁠ẖàẕi֖y şá̂ré֥y yĕhẇdáֽh׃"],[12,33,"וַ⁠עֲזַרְיָ֥ה עֶזְרָ֖א וּ⁠מְשֻׁלָּֽם׃","wa⁠ʻàzarĕyá֥h ʻezĕrá֖ʼ ẇ⁠mĕşǔláֽ̇m׃"],[12,34,"יְהוּדָה֙ וּ⁠בִנְיָמִ֔ן וּֽ⁠שְׁמַֽעְיָ֖ה וְ⁠יִרְמְיָֽה׃ס","yĕhẇdáh֙ ẇ⁠binĕyámi֔n ẇֽ⁠şĕ̌maֽʻĕyá֖h wĕ⁠yirĕmĕyáֽh׃s"],[12,35,"וּ⁠מִ⁠בְּנֵ֥י הַ⁠כֹּהֲנִ֖ים בַּ⁠חֲצֹצְר֑וֹת זְכַרְיָ֨ה בֶן־יֽוֹנָתָ֜ן בֶּן־שְׁמַֽעְיָ֗ה בֶּן־מַתַּנְיָה֙ בֶּן־מִ֣יכָיָ֔ה בֶּן־זַכּ֖וּר בֶּן־אָסָֽף׃","ẇ⁠mi⁠bĕ̇né֥y ha⁠kò̇hàni֖ym bȧ⁠ẖàẕòẕĕr֑wòţ zĕkarĕyá֨h ben-yֽwònáţá֜n bėn-şĕ̌maֽʻĕyá֗h bėn-maţȧnĕyáh֙ bėn-mi֣ykáyá֔h bėn-zak֖̇ẇr bėn-ʼásáֽp׃"],[12,36,"וְֽ⁠אֶחָ֡י⁠ו שְֽׁמַעְיָ֡ה וַ⁠עֲזַרְאֵ֡ל מִֽלֲלַ֡י גִּֽלֲלַ֡י מָעַ֞י נְתַנְאֵ֤ל וִֽ⁠יהוּדָה֙ חֲנָ֔נִי בִּ⁠כְלֵי־שִׁ֥יר דָּוִ֖יד אִ֣ישׁ הָ⁠אֱלֹהִ֑ים וְ⁠עֶזְרָ֥א הַ⁠סּוֹפֵ֖ר לִ⁠פְנֵי⁠הֶֽם׃","wĕֽ⁠ʼeẖá֡y⁠w şĕֽ̌maʻĕyá֡h wa⁠ʻàzarĕʼé֡l miֽlàla֡y giֽ̇làla֡y máʻa֞y nĕţanĕʼé֤l wiֽ⁠yhẇdáh֙ ẖàná֔niy bi̇⁠kĕléy-şǐ֥yr dá̇wi֖yd ʼi֣yş̌ há⁠ʼèlòhi֑ym wĕ⁠ʻezĕrá֥ʼ ha⁠ṡwòpé֖r li⁠pĕnéy⁠heֽm׃"],[12,37,"וְ⁠עַל֩ שַׁ֨עַר הָ⁠עַ֜יִן וְ⁠נֶגְדָּ֗⁠ם עָלוּ֙ עַֽל־מַעֲלוֹת֙ עִ֣יר דָּוִ֔יד בַּֽ⁠מַּעֲלֶ֖ה לַ⁠חוֹמָ֑ה מֵ⁠עַל֙ לְ⁠בֵ֣ית דָּוִ֔יד וְ⁠עַ֛ד שַׁ֥עַר הַ⁠מַּ֖יִם מִזְרָֽח׃","wĕ⁠ʻal֩ şǎ֨ʻar há⁠ʻa֜yin wĕ⁠negĕdá̇֗⁠m ʻálẇ֙ ʻaֽl-maʻàlwòţ֙ ʻi֣yr dá̇wi֔yd bȧֽ⁠mȧʻàle֖h la⁠ẖwòmá֑h mé⁠ʻal֙ lĕ⁠bé֣yţ dá̇wi֔yd wĕ⁠ʻa֛d şǎ֥ʻar ha⁠mȧ֖yim mizĕráֽẖ׃"],[12,38,"וְ⁠הַ⁠תּוֹדָ֧ה הַ⁠שֵּׁנִ֛ית הַ⁠הוֹלֶ֥כֶת לְ⁠מ֖וֹאל וַ⁠אֲנִ֣י אַחֲרֶ֑י⁠הָ וַ⁠חֲצִ֨י הָ⁠עָ֜ם מֵ⁠עַ֣ל לְ⁠הַ⁠חוֹמָ֗ה מֵ⁠עַל֙ לְ⁠מִגְדַּ֣ל הַ⁠תַּנּוּרִ֔ים וְ⁠עַ֖ד הַ⁠חוֹמָ֥ה הָ⁠רְחָבָֽה׃","wĕ⁠ha⁠ţ̇wòdá֧h ha⁠şé̇̌ni֛yţ ha⁠hwòle֥keţ lĕ⁠m֖wòʼl wa⁠ʼàni֣y ʼaẖàre֑y⁠há wa⁠ẖàẕi֨y há⁠ʻá֜m mé⁠ʻa֣l lĕ⁠ha⁠ẖwòmá֗h mé⁠ʻal֙ lĕ⁠migĕdȧ֣l ha⁠ţȧṅẇri֔ym wĕ⁠ʻa֖d ha⁠ẖwòmá֥h há⁠rĕẖábáֽh׃"],[12,39,"וּ⁠מֵ⁠עַ֣ל לְ⁠שַֽׁעַר־אֶ֠פְרַיִם וְ⁠עַל־שַׁ֨עַר הַיְשָׁנָ֜ה וְ⁠עַל־שַׁ֣עַר הַ⁠דָּגִ֗ים וּ⁠מִגְדַּ֤ל חֲנַנְאֵל֙ וּ⁠מִגְדַּ֣ל הַ⁠מֵּאָ֔ה וְ⁠עַ֖ד שַׁ֣עַר הַ⁠צֹּ֑אן וְ⁠עָ֣מְד֔וּ בְּ⁠שַׁ֖עַר הַ⁠מַּטָּרָֽה׃","ẇ⁠mé⁠ʻa֣l lĕ⁠şǎֽʻar-ʼe֠pĕrayim wĕ⁠ʻal-şǎ֨ʻar hayĕşá̌ná֜h wĕ⁠ʻal-şǎ֣ʻar ha⁠dá̇gi֗ym ẇ⁠migĕdȧ֤l ẖànanĕʼél֙ ẇ⁠migĕdȧ֣l ha⁠mé̇ʼá֔h wĕ⁠ʻa֖d şǎ֣ʻar ha⁠ẕò֑̇ʼn wĕ⁠ʻá֣mĕd֔ẇ bĕ̇⁠şǎ֖ʻar ha⁠mȧtá̇ráֽh׃"],[12,40,"וַֽ⁠תַּעֲמֹ֛דְנָה שְׁתֵּ֥י הַ⁠תּוֹדֹ֖ת בְּ⁠בֵ֣ית הָ⁠אֱלֹהִ֑ים וַ⁠אֲנִ֕י וַ⁠חֲצִ֥י הַ⁠סְּגָנִ֖ים עִמִּֽ⁠י׃","waֽ⁠ţȧʻàmò֛dĕnáh şĕ̌ţé֥̇y ha⁠ţ̇wòdò֖ţ bĕ̇⁠bé֣yţ há⁠ʼèlòhi֑ym wa⁠ʼàni֕y wa⁠ẖàẕi֥y ha⁠sĕ̇gáni֖ym ʻimiֽ̇⁠y׃"],[12,41,"וְ⁠הַ⁠כֹּהֲנִ֡ים אֶלְיָקִ֡ים מַעֲשֵׂיָ֡ה מִ֠נְיָמִין מִיכָיָ֧ה אֶלְיוֹעֵינַ֛י זְכַרְיָ֥ה חֲנַנְיָ֖ה בַּ⁠חֲצֹצְרֽוֹת׃","wĕ⁠ha⁠kò̇hàni֡ym ʼelĕyáqi֡ym maʻàşé̂yá֡h mi֠nĕyámiyn miykáyá֧h ʼelĕywòʻéyna֛y zĕkarĕyá֥h ẖànanĕyá֖h bȧ⁠ẖàẕòẕĕrֽwòţ׃"],[12,42,"וּ⁠מַעֲשֵׂיָ֨ה וּֽ⁠שְׁמַֽעְיָ֜ה וְ⁠אֶלְעָזָ֧ר וְ⁠עֻזִּ֛י וִֽ⁠יהוֹחָנָ֥ן וּ⁠מַלְכִּיָּ֖ה וְ⁠עֵילָ֣ם וָ⁠עָ֑זֶר וַ⁠יַּשְׁמִ֨יעוּ֙ הַ⁠מְשֹׁ֣רְרִ֔ים וְ⁠יִֽזְרַחְיָ֖ה הַ⁠פָּקִֽיד׃","ẇ⁠maʻàşé̂yá֨h ẇֽ⁠şĕ̌maֽʻĕyá֜h wĕ⁠ʼelĕʻázá֧r wĕ⁠ʻuzi֛̇y wiֽ⁠yhwòẖáná֥n ẇ⁠malĕki̇yá֖̇h wĕ⁠ʻéylá֣m wá⁠ʻá֑zer wa⁠yȧşĕ̌mi֨yʻẇ֙ ha⁠mĕşò֣̌rĕri֔ym wĕ⁠yiֽzĕraẖĕyá֖h ha⁠pá̇qiֽyd׃"],[12,43,"וַ⁠יִּזְבְּח֣וּ בַ⁠יּוֹם־הַ֠⁠הוּא זְבָחִ֨ים גְּדוֹלִ֜ים וַ⁠יִּשְׂמָ֗חוּ כִּ֤י הָ⁠אֱלֹהִים֙ שִׂמְּחָ⁠ם֙ שִׂמְחָ֣ה גְדוֹלָ֔ה וְ⁠גַ֧ם הַ⁠נָּשִׁ֛ים וְ⁠הַ⁠יְלָדִ֖ים שָׂמֵ֑חוּ וַ⁠תִּשָּׁמַ֛ע שִׂמְחַ֥ת יְרוּשָׁלִַ֖ם מֵ⁠רָחֽוֹק׃","wa⁠yi̇zĕbĕ̇ẖ֣ẇ ba⁠ẏwòm-ha֠⁠hẇʼ zĕbáẖi֨ym gĕ̇dwòli֜ym wa⁠yi̇şĕ̂má֗ẖẇ ki֤̇y há⁠ʼèlòhiym֙ şîmĕ̇ẖá⁠m֙ şîmĕẖá֣h gĕdwòlá֔h wĕ⁠ga֧m ha⁠ná̇şǐ֛ym wĕ⁠ha⁠yĕládi֖ym şá̂mé֑ẖẇ wa⁠ţi̇şá̇̌ma֛ʻ şîmĕẖa֥ţ yĕrẇşá̌lia֖m mé⁠ráẖֽwòq׃"],[12,44,"וַ⁠יִּפָּקְד֣וּ בַ⁠יּוֹם֩ הַ⁠ה֨וּא אֲנָשִׁ֜ים עַל־הַ⁠נְּשָׁכ֗וֹת לָ⁠א֨וֹצָר֥וֹת לַ⁠תְּרוּמוֹת֮ לָ⁠רֵאשִׁ֣ית וְ⁠לַ⁠מַּֽעַשְׂרוֹת֒ לִ⁠כְנ֨וֹס בָּ⁠הֶ֜ם לִ⁠שְׂדֵ֤י הֶ⁠עָרִים֙ מְנָא֣וֹת הַ⁠תּוֹרָ֔ה לַ⁠כֹּהֲנִ֖ים וְ⁠לַ⁠לְוִיִּ֑ם כִּ֚י שִׂמְחַ֣ת יְהוּדָ֔ה עַל־הַ⁠כֹּהֲנִ֥ים וְ⁠עַל־הַ⁠לְוִיִּ֖ם הָ⁠עֹמְדִֽים׃","wa⁠yi̇pá̇qĕd֣ẇ ba⁠ẏwòm֩ ha⁠h֨ẇʼ ʼànáşǐ֜ym ʻal-ha⁠nĕ̇şá̌k֗wòţ lá⁠ʼ֨wòẕár֥wòţ la⁠ţĕ̇rẇmwòţ֮ lá⁠réʼşǐ֣yţ wĕ⁠la⁠mȧֽʻaşĕ̂rwòţ֒ li⁠kĕn֨wòs bá̇⁠he֜m li⁠şĕ̂dé֤y he⁠ʻáriym֙ mĕnáʼ֣wòţ ha⁠ţ̇wòrá֔h la⁠kò̇hàni֖ym wĕ⁠la⁠lĕwiyi֑̇m ki֚̇y şîmĕẖa֣ţ yĕhẇdá֔h ʻal-ha⁠kò̇hàni֥ym wĕ⁠ʻal-ha⁠lĕwiyi֖̇m há⁠ʻòmĕdiֽym׃"],[12,45,"וַֽ⁠יִּשְׁמְר֞וּ מִשְׁמֶ֤רֶת אֱלֹֽהֵי⁠הֶם֙ וּ⁠מִשְׁמֶ֣רֶת הַֽ⁠טָּהֳרָ֔ה וְ⁠הַ⁠מְשֹׁרְרִ֖ים וְ⁠הַ⁠שֹּׁעֲרִ֑ים כְּ⁠מִצְוַ֥ת דָּוִ֖יד שְׁלֹמֹ֥ה בְנֽ⁠וֹ׃","waֽ⁠yi̇şĕ̌mĕr֞ẇ mişĕ̌me֤reţ ʼèlòֽhéy⁠hem֙ ẇ⁠mişĕ̌me֣reţ haֽ⁠tá̇horá֔h wĕ⁠ha⁠mĕşò̌rĕri֖ym wĕ⁠ha⁠şò̇̌ʻàri֑ym kĕ̇⁠miẕĕwa֥ţ dá̇wi֖yd şĕ̌lòmò֥h bĕnֽ⁠wò׃"],[12,46,"כִּֽי־בִ⁠ימֵ֥י דָוִ֛יד וְ⁠אָסָ֖ף מִ⁠קֶּ֑דֶם ראש הַ⁠מְשֹׁ֣רְרִ֔ים וְ⁠שִׁיר־תְּהִלָּ֥ה וְ⁠הֹד֖וֹת לֵֽ⁠אלֹהִֽים׃","kiֽ̇y-bi⁠ymé֥y dáwi֛yd wĕ⁠ʼásá֖p mi⁠qė֑dem rʼş ha⁠mĕşò֣̌rĕri֔ym wĕ⁠şǐyr-ţĕ̇hilá֥̇h wĕ⁠hòd֖wòţ léֽ⁠ʼlòhiֽym׃"],[12,47,"וְ⁠כָל־יִשְׂרָאֵל֩ בִּ⁠ימֵ֨י זְרֻבָּבֶ֜ל וּ⁠בִ⁠ימֵ֣י נְחֶמְיָ֗ה נֹֽתְנִ֛ים מְנָי֛וֹת הַ⁠מְשֹׁרְרִ֥ים וְ⁠הַ⁠שֹּׁעֲרִ֖ים דְּבַר־י֣וֹם בְּ⁠יוֹמ֑⁠וֹ וּ⁠מַקְדִּשִׁים֙ לַ⁠לְוִיִּ֔ם וְ⁠הַ⁠לְוִיִּ֔ם מַקְדִּשִׁ֖ים לִ⁠בְנֵ֥י אַהֲרֹֽן׃פ","wĕ⁠kál-yişĕ̂ráʼél֩ bi̇⁠ymé֨y zĕrubá̇be֜l ẇ⁠bi⁠ymé֣y nĕẖemĕyá֗h nòֽţĕni֛ym mĕnáy֛wòţ ha⁠mĕşò̌rĕri֥ym wĕ⁠ha⁠şò̇̌ʻàri֖ym dĕ̇bar-y֣wòm bĕ̇⁠ywòm֑⁠wò ẇ⁠maqĕdi̇şǐym֙ la⁠lĕwiyi̇֔m wĕ⁠ha⁠lĕwiyi̇֔m maqĕdi̇şǐ֖ym li⁠bĕné֥y ʼahàròֽn׃p"],[13,1,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נִקְרָ֛א בְּ⁠סֵ֥פֶר מֹשֶׁ֖ה בְּ⁠אָזְנֵ֣י הָ⁠עָ֑ם וְ⁠נִמְצָא֙ כָּת֣וּב בּ֔⁠וֹ אֲ֠שֶׁר לֹא־יָב֨וֹא עַמֹּנִ֧י וּ⁠מֹאָבִ֛י בִּ⁠קְהַ֥ל הָ⁠אֱלֹהִ֖ים עַד־עוֹלָֽם׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ niqĕrá֛ʼ bĕ̇⁠sé֥per mòşě֖h bĕ̇⁠ʼázĕné֣y há⁠ʻá֑m wĕ⁠nimĕẕáʼ֙ ká̇ţ֣ẇb ḃ֔⁠wò ʼà֠şěr lòʼ-yáb֨wòʼ ʻamò̇ni֧y ẇ⁠mòʼábi֛y bi̇⁠qĕha֥l há⁠ʼèlòhi֖ym ʻad-ʻwòláֽm׃"],[13,2,"כִּ֣י לֹ֧א קִדְּמ֛וּ אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל בַּ⁠לֶּ֣חֶם וּ⁠בַ⁠מָּ֑יִם וַ⁠יִּשְׂכֹּ֨ר עָלָ֤י⁠ו אֶת־בִּלְעָם֙ לְ⁠קַֽלְל֔⁠וֹ וַ⁠יַּהֲפֹ֧ךְ אֱלֹהֵ֛י⁠נוּ הַ⁠קְּלָלָ֖ה לִ⁠בְרָכָֽה׃","ki֣̇y lò֧ʼ qidĕ̇m֛ẇ ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l bȧ⁠lė֣ẖem ẇ⁠ba⁠má֑̇yim wa⁠yi̇şĕ̂kò̇֨r ʻálá֤y⁠w ʼeţ-bi̇lĕʻám֙ lĕ⁠qaֽlĕl֔⁠wò wa⁠yȧhàpò֧kĕ ʼèlòhé֛y⁠nẇ ha⁠qĕ̇lálá֖h li⁠bĕrákáֽh׃"],[13,3,"וַ⁠יְהִ֖י כְּ⁠שָׁמְעָ֣⁠ם אֶת־הַ⁠תּוֹרָ֑ה וַ⁠יַּבְדִּ֥ילוּ כָל־עֵ֖רֶב מִ⁠יִּשְׂרָאֵֽל׃","wa⁠yĕhi֖y kĕ̇⁠şá̌mĕʻá֣⁠m ʼeţ-ha⁠ţ̇wòrá֑h wa⁠yȧbĕdi֥̇ylẇ kál-ʻé֖reb mi⁠yi̇şĕ̂ráʼéֽl׃"],[13,4,"וְ⁠לִ⁠פְנֵ֣י מִ⁠זֶּ֔ה אֶלְיָשִׁיב֙ הַ⁠כֹּהֵ֔ן נָת֖וּן בְּ⁠לִשְׁכַּ֣ת בֵּית־אֱלֹהֵ֑י⁠נוּ קָר֖וֹב לְ⁠טוֹבִיָּֽה׃","wĕ⁠li⁠pĕné֣y mi⁠zė֔h ʼelĕyáşǐyb֙ ha⁠kò̇hé֔n náţ֖ẇn bĕ̇⁠lişĕ̌kȧ֣ţ bé̇yţ-ʼèlòhé֑y⁠nẇ qár֖wòb lĕ⁠twòbiyáֽ̇h׃"],[13,5,"וַ⁠יַּ֨עַשׂ ל֜⁠וֹ לִשְׁכָּ֣ה גְדוֹלָ֗ה וְ⁠שָׁ֣ם הָי֪וּ לְ⁠פָנִ֟ים נֹ֠תְנִים אֶת־הַ⁠מִּנְחָ֨ה הַ⁠לְּבוֹנָ֜ה וְ⁠הַ⁠כֵּלִ֗ים וּ⁠מַעְשַׂ֤ר הַ⁠דָּגָן֙ הַ⁠תִּיר֣וֹשׁ וְ⁠הַ⁠יִּצְהָ֔ר מִצְוַת֙ הַ⁠לְוִיִּ֔ם וְ⁠הַ⁠מְשֹׁרְרִ֖ים וְ⁠הַ⁠שֹּׁעֲרִ֑ים וּ⁠תְרוּמַ֖ת הַ⁠כֹּהֲנִֽים׃","wa⁠yȧ֨ʻaş̂ l֜⁠wò lişĕ̌ká֣̇h gĕdwòlá֗h wĕ⁠şá֣̌m háy֪ẇ lĕ⁠páni֟ym nò֠ţĕniym ʼeţ-ha⁠mi̇nĕẖá֨h ha⁠lĕ̇bwòná֜h wĕ⁠ha⁠ké̇li֗ym ẇ⁠maʻĕşâ֤r ha⁠dá̇gán֙ ha⁠ţi̇yr֣wòş̌ wĕ⁠ha⁠yi̇ẕĕhá֔r miẕĕwaţ֙ ha⁠lĕwiyi̇֔m wĕ⁠ha⁠mĕşò̌rĕri֖ym wĕ⁠ha⁠şò̇̌ʻàri֑ym ẇ⁠ţĕrẇma֖ţ ha⁠kò̇hàniֽym׃"],[13,6,"וּ⁠בְ⁠כָל־זֶ֕ה לֹ֥א הָיִ֖יתִי בִּֽ⁠ירוּשָׁלִָ֑ם כִּ֡י בִּ⁠שְׁנַת֩ שְׁלֹשִׁ֨ים וּ⁠שְׁתַּ֜יִם לְ⁠אַרְתַּחְשַׁ֤סְתְּא מֶֽלֶךְ־בָּבֶל֙ בָּ֣אתִי אֶל־הַ⁠מֶּ֔לֶךְ וּ⁠לְ⁠קֵ֥ץ יָמִ֖ים נִשְׁאַ֥לְתִּי מִן־הַ⁠מֶּֽלֶךְ׃","ẇ⁠bĕ⁠kál-ze֕h lò֥ʼ háyi֖yţiy biֽ̇⁠yrẇşá̌liá֑m ki̇֡y bi̇⁠şĕ̌naţ֩ şĕ̌lòşǐ֨ym ẇ⁠şĕ̌ţȧ֜yim lĕ⁠ʼarĕţȧẖĕşǎ֤sĕţĕ̇ʼ meֽlekĕ-bá̇bel֙ bá֣̇ʼţiy ʼel-ha⁠mė֔lekĕ ẇ⁠lĕ⁠qé֥ẕ yámi֖ym nişĕ̌ʼa֥lĕţi̇y min-ha⁠mėֽlekĕ׃"],[13,7,"וָ⁠אָב֖וֹא לִֽ⁠ירוּשָׁלִָ֑ם וָ⁠אָבִ֣ינָ⁠ה בָ⁠רָעָ֗ה אֲשֶׁ֨ר עָשָׂ֤ה אֶלְיָשִׁיב֙ לְ⁠ט֣וֹבִיָּ֔ה לַ⁠עֲשׂ֥וֹת ל⁠וֹ֙ נִשְׁכָּ֔ה בְּ⁠חַצְרֵ֖י בֵּ֥ית הָ⁠אֱלֹהִֽים׃","wá⁠ʼáb֖wòʼ liֽ⁠yrẇşá̌liá֑m wá⁠ʼábi֣yná⁠h bá⁠ráʻá֗h ʼàşě֨r ʻáşá֤̂h ʼelĕyáşǐyb֙ lĕ⁠t֣wòbiyá̇֔h la⁠ʻàş֥̂wòţ l⁠wò֙ nişĕ̌ká̇֔h bĕ̇⁠ẖaẕĕré֖y bé֥̇yţ há⁠ʼèlòhiֽym׃"],[13,8,"וַ⁠יֵּ֥רַֽע לִ֖⁠י מְאֹ֑ד וָֽ⁠אַשְׁלִ֜יכָ⁠ה אֶֽת־כָּל־כְּלֵ֧י בֵית־טוֹבִיָּ֛ה הַ⁠ח֖וּץ מִן־הַ⁠לִּשְׁכָּֽה׃","wa⁠yé֥̇raֽʻ li֖⁠y mĕʼò֑d wֽá⁠ʼaşĕ̌li֜yká⁠h ʼeֽţ-ká̇l-kĕ̇lé֧y béyţ-twòbiyá֛̇h ha⁠ẖ֖ẇẕ min-ha⁠li̇şĕ̌káֽ̇h׃"],[13,9,"וָ⁠אֹ֣מְרָ֔⁠ה וַֽ⁠יְטַהֲר֖וּ הַ⁠לְּשָׁכ֑וֹת וָ⁠אָשִׁ֣יבָ⁠ה שָּׁ֗ם כְּלֵי֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים אֶת־הַ⁠מִּנְחָ֖ה וְ⁠הַ⁠לְּבוֹנָֽה׃פ","wá⁠ʼò֣mĕrá֔⁠h waֽ⁠yĕtahàr֖ẇ ha⁠lĕ̇şá̌k֑wòţ wá⁠ʼáşǐ֣ybá⁠h şá̇̌֗m kĕ̇léy֙ bé֣̇yţ há⁠ʼèlòhi֔ym ʼeţ-ha⁠mi̇nĕẖá֖h wĕ⁠ha⁠lĕ̇bwònáֽh׃p"],[13,10,"וָ⁠אֵ֣דְעָ֔⁠ה כִּֽי־מְנָי֥וֹת הַ⁠לְוִיִּ֖ם לֹ֣א נִתָּ֑נָה וַ⁠יִּבְרְח֧וּ אִישׁ־לְ⁠שָׂדֵ֛⁠הוּ הַ⁠לְוִיִּ֥ם וְ⁠הַ⁠מְשֹׁרְרִ֖ים עֹשֵׂ֥י הַ⁠מְּלָאכָֽה׃","wá⁠ʼé֣dĕʻá֔⁠h kiֽ̇y-mĕnáy֥wòţ ha⁠lĕwiyi֖̇m lò֣ʼ niţá֑̇náh wa⁠yi̇bĕrĕẖ֧ẇ ʼiyş̌-lĕ⁠şá̂dé֛⁠hẇ ha⁠lĕwiyi֥̇m wĕ⁠ha⁠mĕşò̌rĕri֖ym ʻòşé֥̂y ha⁠mĕ̇láʼkáֽh׃"],[13,11,"וָ⁠אָרִ֨יבָ⁠ה֙ אֶת־הַ⁠סְּגָנִ֔ים וָ⁠אֹ֣מְרָ֔⁠ה מַדּ֖וּעַ נֶעֱזַ֣ב בֵּית־הָ⁠אֱלֹהִ֑ים וָֽ⁠אֶ֨קְבְּצֵ֔⁠ם וָֽ⁠אַעֲמִדֵ֖⁠ם עַל־עָמְדָֽ⁠ם׃","wá⁠ʼári֨ybá⁠h֙ ʼeţ-ha⁠sĕ̇gáni֔ym wá⁠ʼò֣mĕrá֔⁠h maḋ֖ẇʻa neʻèza֣b bé̇yţ-há⁠ʼèlòhi֑ym wáֽ⁠ʼe֨qĕbĕ̇ẕé֔⁠m wáֽ⁠ʼaʻàmidé֖⁠m ʻal-ʻámĕdáֽ⁠m׃"],[13,12,"וְ⁠כָל־יְהוּדָ֗ה הֵבִ֜יאוּ מַעְשַׂ֧ר הַ⁠דָּגָ֛ן וְ⁠הַ⁠תִּיר֥וֹשׁ וְ⁠הַ⁠יִּצְהָ֖ר לָ⁠אוֹצָרֽוֹת׃","wĕ⁠kál-yĕhẇdá֗h hébi֜yʼẇ maʻĕşâ֧r ha⁠dá̇gá֛n wĕ⁠ha⁠ţi̇yr֥wòş̌ wĕ⁠ha⁠yi̇ẕĕhá֖r lá⁠ʼwòẕárֽwòţ׃"],[13,13,"וָ⁠אוֹצְרָ֣⁠ה עַל־א֠וֹצָרוֹת שֶׁלֶמְיָ֨ה הַ⁠כֹּהֵ֜ן וְ⁠צָד֣וֹק הַ⁠סּוֹפֵ֗ר וּ⁠פְדָיָה֙ מִן־הַ⁠לְוִיִּ֔ם וְ⁠עַל־יָדָ֔⁠ם חָנָ֥ן בֶּן־זַכּ֖וּר בֶּן־מַתַּנְיָ֑ה כִּ֤י נֶאֱמָנִים֙ נֶחְשָׁ֔בוּ וַ⁠עֲלֵי⁠הֶ֖ם לַ⁠חֲלֹ֥ק לַ⁠אֲחֵי⁠הֶֽם׃פ","wá⁠ʼwòẕĕrá֣⁠h ʻal-ʼ֠wòẕárwòţ şělemĕyá֨h ha⁠kò̇hé֜n wĕ⁠ẕád֣wòq ha⁠ṡwòpé֗r ẇ⁠pĕdáyáh֙ min-ha⁠lĕwiyi̇֔m wĕ⁠ʻal-yádá֔⁠m ẖáná֥n bėn-zak֖̇ẇr bėn-maţȧnĕyá֑h ki֤̇y neʼèmániym֙ neẖĕşá̌֔bẇ wa⁠ʻàléy⁠he֖m la⁠ẖàlò֥q la⁠ʼàẖéy⁠heֽm׃p"],[13,14,"זָכְרָ⁠ה־לִּ֥⁠י אֱלֹהַ֖⁠י עַל־זֹ֑את וְ⁠אַל־תֶּ֣מַח חֲסָדַ֗⁠י אֲשֶׁ֥ר עָשִׂ֛יתִי בְּ⁠בֵ֥ית אֱלֹהַ֖⁠י וּ⁠בְ⁠מִשְׁמָרָֽי⁠ו׃","zákĕrá⁠h-li֥̇⁠y ʼèlòha֖⁠y ʻal-zò֑ʼţ wĕ⁠ʼal-ţė֣maẖ ẖàsáda֗⁠y ʼàşě֥r ʻáşî֛yţiy bĕ̇⁠bé֥yţ ʼèlòha֖⁠y ẇ⁠bĕ⁠mişĕ̌máráֽy⁠w׃"],[13,15,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֡מָּה רָאִ֣יתִי בִֽ⁠יהוּדָ֣ה ׀ דֹּֽרְכִֽים־גִּתּ֣וֹת ׀ בַּ⁠שַּׁבָּ֡ת וּ⁠מְבִיאִ֣ים הָ⁠עֲרֵמ֣וֹת וְֽ⁠עֹמְסִ֪ים עַל־הַ⁠חֲמֹרִ֟ים וְ⁠אַף־יַ֜יִן עֲנָבִ֤ים וּ⁠תְאֵנִים֙ וְ⁠כָל־מַשָּׂ֔א וּ⁠מְבִיאִ֥ים יְרוּשָׁלִַ֖ם בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֑ת וָ⁠אָעִ֕יד בְּ⁠י֖וֹם מִכְרָ֥⁠ם צָֽיִד׃","bȧ⁠yá̇mi֣ym há⁠hé֡má̇h ráʼi֣yţiy biֽ⁠yhẇdá֣h ׀ dòֽ̇rĕkiֽym-gi̇ţ֣̇wòţ ׀ bȧ⁠şȧ̌bá̇֡ţ ẇ⁠mĕbiyʼi֣ym há⁠ʻàrém֣wòţ wĕֽ⁠ʻòmĕsi֪ym ʻal-ha⁠ẖàmòri֟ym wĕ⁠ʼap-ya֜yin ʻànábi֤ym ẇ⁠ţĕʼéniym֙ wĕ⁠kál-maşá̇̂֔ʼ ẇ⁠mĕbiyʼi֥ym yĕrẇşá̌lia֖m bĕ̇⁠y֣wòm ha⁠şȧ̌bá֑̇ţ wá⁠ʼáʻi֕yd bĕ̇⁠y֖wòm mikĕrá֥⁠m ẕáֽyid׃"],[13,16,"וְ⁠הַ⁠צֹּרִים֙ יָ֣שְׁבוּ בָ֔⁠הּ מְבִיאִ֥ים דָּ֖אג וְ⁠כָל־מֶ֑כֶר וּ⁠מֹכְרִ֧ים בַּ⁠שַּׁבָּ֛ת לִ⁠בְנֵ֥י יְהוּדָ֖ה וּ⁠בִ⁠ירוּשָׁלִָֽם׃","wĕ⁠ha⁠ẕò̇riym֙ yá֣şĕ̌bẇ bá֔⁠ḣ mĕbiyʼi֥ym dá֖̇ʼg wĕ⁠kál-me֑ker ẇ⁠mòkĕri֧ym bȧ⁠şȧ̌bá֛̇ţ li⁠bĕné֥y yĕhẇdá֖h ẇ⁠bi⁠yrẇşá̌liáֽm׃"],[13,17,"וָ⁠אָרִ֕יבָ⁠ה אֵ֖ת חֹרֵ֣י יְהוּדָ֑ה וָ⁠אֹמְרָ֣⁠ה לָ⁠הֶ֗ם מָֽה־הַ⁠דָּבָ֨ר הָ⁠רָ֤ע הַ⁠זֶּה֙ אֲשֶׁ֣ר אַתֶּ֣ם עֹשִׂ֔ים וּֽ⁠מְחַלְּלִ֖ים אֶת־י֥וֹם הַ⁠שַּׁבָּֽת׃","wá⁠ʼári֕ybá⁠h ʼé֖ţ ẖòré֣y yĕhẇdá֑h wá⁠ʼòmĕrá֣⁠h lá⁠he֗m máֽh-ha⁠dá̇bá֨r há⁠rá֤ʻ ha⁠zėh֙ ʼàşě֣r ʼaţė֣m ʻòşî֔ym ẇֽ⁠mĕẖalĕ̇li֖ym ʼeţ-y֥wòm ha⁠şȧ̌báֽ̇ţ׃"],[13,18,"הֲ⁠ל֨וֹא כֹ֤ה עָשׂוּ֙ אֲבֹ֣תֵי⁠כֶ֔ם וַ⁠יָּבֵ֨א אֱלֹהֵ֜י⁠נוּ עָלֵ֗י⁠נוּ אֵ֚ת כָּל־הָ⁠רָעָ֣ה הַ⁠זֹּ֔את וְ⁠עַ֖ל הָ⁠עִ֣יר הַ⁠זֹּ֑את וְ⁠אַתֶּ֞ם מוֹסִיפִ֤ים חָרוֹן֙ עַל־יִשְׂרָאֵ֔ל לְ⁠חַלֵּ֖ל אֶת־הַ⁠שַּׁבָּֽת׃פ","hà⁠l֨wòʼ kò֤h ʻáş̂ẇ֙ ʼàbò֣ţéy⁠ke֔m wa⁠yá̇bé֨ʼ ʼèlòhé֜y⁠nẇ ʻálé֗y⁠nẇ ʼé֚ţ ká̇l-há⁠ráʻá֣h ha⁠zò̇֔ʼţ wĕ⁠ʻa֖l há⁠ʻi֣yr ha⁠zò֑̇ʼţ wĕ⁠ʼaţė֞m mwòsiypi֤ym ẖárwòn֙ ʻal-yişĕ̂ráʼé֔l lĕ⁠ẖalé֖̇l ʼeţ-ha⁠şȧ̌báֽ̇ţ׃p"],[13,19,"וַ⁠יְהִ֡י כַּ⁠אֲשֶׁ֣ר צָֽלֲלוּ֩ שַׁעֲרֵ֨י יְרוּשָׁלִַ֜ם לִ⁠פְנֵ֣י הַ⁠שַּׁבָּ֗ת וָ⁠אֹֽמְרָ⁠ה֙ וַ⁠יִּסָּגְר֣וּ הַ⁠דְּלָת֔וֹת וָ⁠אֹ֣מְרָ֔⁠ה אֲשֶׁר֙ לֹ֣א יִפְתָּח֔וּ⁠ם עַ֖ד אַחַ֣ר הַ⁠שַּׁבָּ֑ת וּ⁠מִ⁠נְּעָרַ֗⁠י הֶֽעֱמַ֨דְתִּי֙ עַל־הַ⁠שְּׁעָרִ֔ים לֹא־יָב֥וֹא מַשָּׂ֖א בְּ⁠י֥וֹם הַ⁠שַּׁבָּֽת׃","wa⁠yĕhi֡y kȧ⁠ʼàşě֣r ẕáֽlàlẇ֩ şǎʻàré֨y yĕrẇşá̌lia֜m li⁠pĕné֣y ha⁠şȧ̌bá̇֗ţ wá⁠ʼòֽmĕrá⁠h֙ wa⁠yi̇sá̇gĕr֣ẇ ha⁠dĕ̇láţ֔wòţ wá⁠ʼò֣mĕrá֔⁠h ʼàşěr֙ lò֣ʼ yipĕţá̇ẖ֔ẇ⁠m ʻa֖d ʼaẖa֣r ha⁠şȧ̌bá֑̇ţ ẇ⁠mi⁠nĕ̇ʻára֗⁠y hֽeʻèma֨dĕţi̇y֙ ʻal-ha⁠şĕ̇̌ʻári֔ym lòʼ-yáb֥wòʼ maşá֖̇̂ʼ bĕ̇⁠y֥wòm ha⁠şȧ̌báֽ̇ţ׃"],[13,20,"וַ⁠יָּלִ֨ינוּ הָ⁠רֹכְלִ֜ים וּ⁠מֹכְרֵ֧י כָל־מִמְכָּ֛ר מִ⁠ח֥וּץ לִ⁠ירוּשָׁלִָ֖ם פַּ֥עַם וּ⁠שְׁתָּֽיִם׃","wa⁠yá̇li֨ynẇ há⁠ròkĕli֜ym ẇ⁠mòkĕré֧y kál-mimĕká֛̇r mi⁠ẖ֥ẇẕ li⁠yrẇşá̌liá֖m pȧ֥ʻam ẇ⁠şĕ̌ţáֽ̇yim׃"],[13,21,"וָ⁠אָעִ֣ידָ⁠ה בָ⁠הֶ֗ם וָ⁠אֹמְרָ֤⁠ה אֲלֵי⁠הֶם֙ מַדּ֜וּעַ אַתֶּ֤ם לֵנִים֙ נֶ֣גֶד הַ⁠חוֹמָ֔ה אִם־תִּשְׁנ֕וּ יָ֖ד אֶשְׁלַ֣ח בָּ⁠כֶ֑ם מִן־הָ⁠עֵ֣ת הַ⁠הִ֔יא לֹא־בָ֖אוּ בַּ⁠שַּׁבָּֽת׃ס","wá⁠ʼáʻi֣ydá⁠h bá⁠he֗m wá⁠ʼòmĕrá֤⁠h ʼàléy⁠hem֙ maḋ֜ẇʻa ʼaţė֤m léniym֙ ne֣ged ha⁠ẖwòmá֔h ʼim-ţi̇şĕ̌n֕ẇ yá֖d ʼeşĕ̌la֣ẖ bá̇⁠ke֑m min-há⁠ʻé֣ţ ha⁠hi֔yʼ lòʼ-bá֖ʼẇ bȧ⁠şȧ̌báֽ̇ţ׃s"],[13,22,"וָ⁠אֹמְרָ֣⁠ה לַ⁠לְוִיִּ֗ם אֲשֶׁ֨ר יִֽהְי֤וּ מִֽטַּהֲרִים֙ וּ⁠בָאִים֙ שֹׁמְרִ֣ים הַ⁠שְּׁעָרִ֔ים לְ⁠קַדֵּ֖שׁ אֶת־י֣וֹם הַ⁠שַּׁבָּ֑ת גַּם־זֹאת֙ זָכְרָ⁠ה־לִּ֣⁠י אֱלֹהַ֔⁠י וְ⁠ח֥וּסָ⁠ה עָלַ֖⁠י כְּ⁠רֹ֥ב חַסְדֶּֽ⁠ךָ׃פ","wá⁠ʼòmĕrá֣⁠h la⁠lĕwiyi̇֗m ʼàşě֨r yiֽhĕy֤ẇ miֽtȧhàriym֙ ẇ⁠báʼiym֙ şò̌mĕri֣ym ha⁠şĕ̇̌ʻári֔ym lĕ⁠qadé֖̇ş̌ ʼeţ-y֣wòm ha⁠şȧ̌bá֑̇ţ gȧm-zòʼţ֙ zákĕrá⁠h-li֣̇⁠y ʼèlòha֔⁠y wĕ⁠ẖ֥ẇsá⁠h ʻála֖⁠y kĕ̇⁠rò֥b ẖasĕdėֽ⁠ká׃p"],[13,23,"גַּ֣ם ׀ בַּ⁠יָּמִ֣ים הָ⁠הֵ֗ם רָאִ֤יתִי אֶת־הַ⁠יְּהוּדִים֙ הֹשִׁ֗יבוּ נָשִׁים֙ אשדודיות עמוניות מוֹאֲבִיּֽוֹת׃","gȧ֣m ׀ bȧ⁠yá̇mi֣ym há⁠hé֗m ráʼi֤yţiy ʼeţ-ha⁠yĕ̇hẇdiym֙ hòşǐ֗ybẇ náşǐym֙ ʼşdwdywţ ʻmwnywţ mwòʼàbiẏֽwòţ׃"],[13,24,"וּ⁠בְנֵי⁠הֶ֗ם חֲצִי֙ מְדַבֵּ֣ר אַשְׁדּוֹדִ֔ית וְ⁠אֵינָ֥⁠ם מַכִּירִ֖ים לְ⁠דַבֵּ֣ר יְהוּדִ֑ית וְ⁠כִ⁠לְשׁ֖וֹן עַ֥ם וָ⁠עָֽם׃","ẇ⁠bĕnéy⁠he֗m ẖàẕiy֙ mĕdabé֣̇r ʼaşĕ̌ḋwòdi֔yţ wĕ⁠ʼéyná֥⁠m maki̇yri֖ym lĕ⁠dabé֣̇r yĕhẇdi֑yţ wĕ⁠ki⁠lĕş֖̌wòn ʻa֥m wá⁠ʻáֽm׃"],[13,25,"וָ⁠אָרִ֤יב עִמָּ⁠ם֙ וָ⁠אֲקַֽלְלֵ֔⁠ם וָ⁠אַכֶּ֥ה מֵ⁠הֶ֛ם אֲנָשִׁ֖ים וָֽ⁠אֶמְרְטֵ֑⁠ם וָ⁠אַשְׁבִּיעֵ֣⁠ם בֵּֽ⁠אלֹהִ֗ים אִם־תִּתְּנ֤וּ בְנֹֽתֵי⁠כֶם֙ לִ⁠בְנֵי⁠הֶ֔ם וְ⁠אִם־תִּשְׂאוּ֙ מִ⁠בְּנֹ֣תֵי⁠הֶ֔ם לִ⁠בְנֵי⁠כֶ֖ם וְ⁠לָ⁠כֶֽם׃","wá⁠ʼári֤yb ʻimá̇⁠m֙ wá⁠ʼàqaֽlĕlé֔⁠m wá⁠ʼakė֥h mé⁠he֛m ʼànáşǐ֖ym wáֽ⁠ʼemĕrĕté֑⁠m wá⁠ʼaşĕ̌bi̇yʻé֣⁠m béֽ̇⁠ʼlòhi֗ym ʼim-ţi̇ţĕ̇n֤ẇ bĕnòֽţéy⁠kem֙ li⁠bĕnéy⁠he֔m wĕ⁠ʼim-ţi̇şĕ̂ʼẇ֙ mi⁠bĕ̇nò֣ţéy⁠he֔m li⁠bĕnéy⁠ke֖m wĕ⁠lá⁠keֽm׃"],[13,26,"הֲ⁠ל֣וֹא עַל־אֵ֣לֶּה חָטָֽא־שְׁלֹמֹ֣ה מֶ֣לֶךְ יִשְׂרָאֵ֡ל וּ⁠בַ⁠גּוֹיִ֣ם הָ⁠רַבִּים֩ לֹֽא־הָיָ֨ה מֶ֜לֶךְ כָּמֹ֗⁠הוּ וְ⁠אָה֤וּב לֵֽ⁠אלֹהָי⁠ו֙ הָיָ֔ה וַ⁠יִּתְּנֵ֣⁠הוּ אֱלֹהִ֔ים מֶ֖לֶךְ עַל־כָּל־יִשְׂרָאֵ֑ל גַּם־אוֹת֣⁠וֹ הֶחֱטִ֔יאוּ הַ⁠נָּשִׁ֖ים הַ⁠נָּכְרִיּֽוֹת׃","hà⁠l֣wòʼ ʻal-ʼé֣lėh ẖátáֽʼ-şĕ̌lòmò֣h me֣lekĕ yişĕ̂ráʼé֡l ẇ⁠ba⁠ġwòyi֣m há⁠rabi̇ym֩ lòֽʼ-háyá֨h me֜lekĕ ká̇mò֗⁠hẇ wĕ⁠ʼáh֤ẇb léֽ⁠ʼlòháy⁠w֙ háyá֔h wa⁠yi̇ţĕ̇né֣⁠hẇ ʼèlòhi֔ym me֖lekĕ ʻal-ká̇l-yişĕ̂ráʼé֑l gȧm-ʼwòţ֣⁠wò heẖèti֔yʼẇ ha⁠ná̇şǐ֖ym ha⁠ná̇kĕriẏֽwòţ׃"],[13,27,"וְ⁠לָ⁠כֶ֣ם הֲ⁠נִשְׁמַ֗ע לַ⁠עֲשֹׂת֙ אֵ֣ת כָּל־הָ⁠רָעָ֤ה הַ⁠גְּדוֹלָה֙ הַ⁠זֹּ֔את לִ⁠מְעֹ֖ל בֵּֽ⁠אלֹהֵ֑י⁠נוּ לְ⁠הֹשִׁ֖יב נָשִׁ֥ים נָכְרִיּֽוֹת׃","wĕ⁠lá⁠ke֣m hà⁠nişĕ̌ma֗ʻ la⁠ʻàşò̂ţ֙ ʼé֣ţ ká̇l-há⁠ráʻá֤h ha⁠gĕ̇dwòláh֙ ha⁠zò̇֔ʼţ li⁠mĕʻò֖l béֽ̇⁠ʼlòhé֑y⁠nẇ lĕ⁠hòşǐ֖yb náşǐ֥ym nákĕriẏֽwòţ׃"],[13,28,"וּ⁠מִ⁠בְּנֵ֨י יוֹיָדָ֤ע בֶּן־אֶלְיָשִׁיב֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל חָתָ֖ן לְ⁠סַנְבַלַּ֣ט הַ⁠חֹרֹנִ֑י וָ⁠אַבְרִיחֵ֖⁠הוּ מֵ⁠עָלָֽ⁠י׃","ẇ⁠mi⁠bĕ̇né֨y ywòyádá֤ʻ bėn-ʼelĕyáşǐyb֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl ẖáţá֖n lĕ⁠sanĕbalȧ֣t ha⁠ẖòròni֑y wá⁠ʼabĕriyẖé֖⁠hẇ mé⁠ʻáláֽ⁠y׃"],[13,29,"זָכְרָ֥⁠ה לָ⁠הֶ֖ם אֱלֹהָ֑⁠י עַ֚ל גָּאֳלֵ֣י הַ⁠כְּהֻנָּ֔ה וּ⁠בְרִ֥ית הַ⁠כְּהֻנָּ֖ה וְ⁠הַ⁠לְוִיִּֽם׃","zákĕrá֥⁠h lá⁠he֖m ʼèlòhá֑⁠y ʻa֚l gá̇ʼolé֣y ha⁠kĕ̇huná̇֔h ẇ⁠bĕri֥yţ ha⁠kĕ̇huná֖̇h wĕ⁠ha⁠lĕwiyiֽ̇m׃"],[13,30,"וְ⁠טִֽהַרְתִּ֖י⁠ם מִ⁠כָּל־נֵכָ֑ר וָ⁠אַעֲמִ֧ידָ⁠ה מִשְׁמָר֛וֹת לַ⁠כֹּהֲנִ֥ים וְ⁠לַ⁠לְוִיִּ֖ם אִ֥ישׁ בִּ⁠מְלַאכְתּֽ⁠וֹ׃","wĕ⁠tiֽharĕţi֖̇y⁠m mi⁠ká̇l-néká֑r wá⁠ʼaʻàmi֧ydá⁠h mişĕ̌már֛wòţ la⁠kò̇hàni֥ym wĕ⁠la⁠lĕwiyi֖̇m ʼi֥yş̌ bi̇⁠mĕlaʼkĕţֽ̇⁠wò׃"],[13,31,"וּ⁠לְ⁠קֻרְבַּ֧ן הָ⁠עֵצִ֛ים בְּ⁠עִתִּ֥ים מְזֻמָּנ֖וֹת וְ⁠לַ⁠בִּכּוּרִ֑ים זָכְרָ⁠ה־לִּ֥⁠י אֱלֹהַ֖⁠י לְ⁠טוֹבָֽה׃","ẇ⁠lĕ⁠qurĕbȧ֧n há⁠ʻéẕi֛ym bĕ̇⁠ʻiţi֥̇ym mĕzumá̇n֖wòţ wĕ⁠la⁠bi̇k̇ẇri֑ym zákĕrá⁠h-li֥̇⁠y ʼèlòha֖⁠y lĕ⁠twòbáֽh׃"]]}};